window.OTTER2_STORYSUB = window.OTTER2_STORYSUB || {};
window.OTTER2_STORYSUB["2"] = {"hsk2-01": {"dur": 132.68, "cues": [[6.805, 10.265, "这个周末，我想做很多事。", "Zhè Ge Zhōu Mò, Wǒ Xiǎng Zuò Hěn Duō Shì.", "Cuối tuần này, tôi muốn làm nhiều việc."], [10.265, 13.173, "这个星期六我没有课。", "Zhè Ge Xīng Qī Liù Wǒ Méi Yǒu Kè.", "Thứ Bảy này tôi không có tiết học."], [13.173, 18.241, "星期五晚上，我问自己：先做什么呢？", "Xīng Qī Wǔ Wǎn Shàng, Wǒ Wèn Zì Jǐ: Xiān Zuò Shén Me Ne?", "Tối thứ Sáu, tôi tự hỏi: nên làm gì trước nhỉ?"], [18.245, 21.537, "上午我想去图书馆看书。", "Shàng Wǔ Wǒ Xiǎng Qù Tú Shū Guǎn Kàn Shū.", "Buổi sáng tôi muốn đến thư viện đọc sách."], [21.537, 25.261, "图书馆人不多，我可以慢慢看。", "Tú Shū Guǎn Rén Bù Duō, Wǒ Kě Yǐ Màn Màn Kàn.", "Thư viện không đông người, tôi có thể đọc từ từ."], [25.261, 27.809, "我想看一本新书。", "Wǒ Xiǎng Kàn Yì Běn Xīn Shū.", "Tôi muốn đọc một cuốn sách mới."], [27.811, 31.151, "中午我回家吃一点儿东西。", "Zhōng Wǔ Wǒ Huí Jiā Chī Yì Diǎn Ér Dōng Xi.", "Trưa tôi về nhà ăn một chút."], [31.151, 34.491, "下午朋友请我去他家吃饭。", "Xià Wǔ Péng Yǒu Qǐng Wǒ Qù Tā Jiā Chī Fàn.", "Buổi chiều bạn mời tôi đến nhà ăn cơm."], [34.511, 39.003, "朋友给我打电话，说：“你几点来？”", "Péng Yǒu Gěi Wǒ Dǎ Diàn Huà, Shuō: “Nǐ Jǐ Diǎn Lái?”", "Bạn gọi điện cho tôi, nói: “Mấy giờ bạn đến?”"], [39.003, 42.895, "我说：“三点半，我带水果去。”", "Wǒ Shuō: “Sān Diǎn Bàn, Wǒ Dài Shuǐ Guǒ Qù.”", "Tôi nói: “Ba giờ rưỡi, tôi mang hoa quả đến.”"], [42.895, 46.019, "我去商店买了一些水果。", "Wǒ Qù Shāng Diàn Mǎi Le Yì Xiē Shuǐ Guǒ.", "Tôi ra cửa hàng mua một ít hoa quả."], [46.045, 49.217, "到了朋友家，他很高兴。", "Dào Le Péng Yǒu Jiā, Tā Hěn Gāo Xìng.", "Đến nhà bạn, anh ấy rất vui."], [49.217, 52.917, "他做中国菜，我觉得很好吃。", "Tā Zuò Zhōng Guó Cài, Wǒ Jué De Hěn Hǎo Chī.", "Anh ấy nấu món Trung, tôi thấy rất ngon."], [52.945, 56.069, "我问他：“这是什么菜？”", "Wǒ Wèn Tā: “Zhè Shì Shén Me Cài?”", "Tôi hỏi anh ấy: “Đây là món gì?”"], [56.069, 61.041, "他笑着说：“你先吃，吃完再告诉你。”", "Tā Xiào Zhe Shuō: “Nǐ Xiān Chī, Chī Wán Zài Gào Sù Nǐ.”", "Anh ấy cười nói: “Bạn ăn trước đi, ăn xong tôi sẽ nói cho bạn.”"], [61.041, 65.173, "我们吃饭的时候，说了很多学校的事。", "Wǒ Men Chī Fàn De Shí Hòu, Shuō Le Hěn Duō Xué Xiào De Shì.", "Lúc ăn cơm, chúng tôi nói rất nhiều chuyện ở trường."], [65.178, 69.742, "晚上我们一起看电视，然后我回家睡觉。", "Wǎn Shàng Wǒ Men Yì Qǐ Kàn Diàn Shì, Rán Hòu Wǒ Huí Jiā Shuì Jiào.", "Buổi tối chúng tôi xem ti vi, sau đó tôi về nhà ngủ."], [69.742, 74.306, "回家以后，我觉得很累，可是很高兴。", "Huí Jiā Yǐ Hòu, Wǒ Jué De Hěn Lèi, Kě Shì Hěn Gāo Xìng.", "Về nhà rồi, tôi thấy rất mệt nhưng rất vui."], [74.311, 77.819, "星期天我还想去公园走走。", "Xīng Qī Tiān Wǒ Hái Xiǎng Qù Gōng Yuán Zǒu Zǒu.", "Chủ nhật tôi còn muốn ra công viên đi dạo."], [77.819, 81.567, "星期天早上，我先看天气。", "Xīng Qī Tiān Zǎo Shàng, Wǒ Xiān Kàn Tiān Qì.", "Sáng Chủ nhật, tôi xem thời tiết trước."], [81.567, 85.651, "可是外面在下雨，我有点儿担心。", "Kě Shì Wài Miàn Zài Xià Yǔ, Wǒ Yǒu Yì Diǎn Ér Dān Xīn.", "Nhưng bên ngoài đang mưa, tôi hơi lo."], [85.651, 90.023, "我想：雨还下，我去不去公园？", "Wǒ Xiǎng: Yǔ Hái Xià, Wǒ Qù Bú Qù Gōng Yuán?", "Tôi nghĩ: mưa vẫn rơi, tôi có đi công viên không?"], [90.023, 93.147, "十点的时候，雨小了。", "Shí Diǎn De Shí Hòu, Yǔ Xiǎo Le.", "Lúc mười giờ, mưa nhỏ lại."], [93.147, 96.367, "我很高兴，马上出门。", "Wǒ Hěn Gāo Xìng, Mǎ Shàng Chū Mén.", "Tôi rất vui, lập tức ra khỏi nhà."], [96.385, 100.037, "如果天气好，我就骑自行车。", "Rú Guǒ Tiān Qì Hǎo, Wǒ Jiù Qí Zì Xíng Chē.", "Nếu thời tiết đẹp, tôi sẽ đi xe đạp."], [100.037, 103.737, "公园里人很多，有孩子在玩儿。", "Gōng Yuán Lǐ Rén Hěn Duō, Yǒu Hái Zi Zài Wánr.", "Trong công viên rất đông người, có trẻ con đang chơi."], [103.737, 106.981, "我在公园走了很长时间。", "Wǒ Zài Gōng Yuán Zǒu Le Hěn Cháng Shí Jiān.", "Tôi đi dạo trong công viên rất lâu."], [106.985, 109.773, "我想在外面吃午饭。", "Wǒ Xiǎng Zài Wài Miàn Chī Wǔ Fàn.", "Tôi muốn ăn trưa ở ngoài."], [109.773, 113.521, "下午我在家休息，睡了一会儿。", "Xià Wǔ Wǒ Zài Jiā Xiū Xi, Shuì Le Yí Huì Er.", "Buổi chiều tôi nghỉ ở nhà, ngủ một lúc."], [113.525, 115.977, "晚上早一点儿睡觉。", "Wǎn Shàng Zǎo Yì Diǎn Ér Shuì Jiào.", "Tối tôi sẽ ngủ sớm hơn một chút."], [115.977, 118.957, "这样星期一才有精神。", "Zhè Yàng Xīng Qī Yī Cái Yǒu Jīng Shén.", "Như vậy thứ Hai mới có tinh thần."], [118.957, 122.393, "我把这个计划写在本子上了。", "Wǒ Bǎ Zhè Ge Jì Huà Xiě Zài Běn Zi Shàng Le.", "Tôi đã viết kế hoạch này vào vở."]]}, "hsk2-02": {"dur": 152.41, "cues": [[7.053, 10.009, "你坐过北京的地铁吗？", "Nǐ Zuò Guò Běi Jīng De Dì Tiě Ma?", "Bạn đã từng đi tàu điện ngầm Bắc Kinh chưa?"], [10.009, 13.709, "昨天我第一次坐北京的地铁。", "Zuó Tiān Wǒ Dì Yī Cì Zuò Běi Jīng De Dì Tiě.", "Hôm qua tôi đi tàu điện ngầm Bắc Kinh lần đầu."], [13.709, 17.649, "那天早上，我要去学校看朋友。", "Nà Tiān Zǎo Shàng, Wǒ Yào Qù Xué Xiào Kàn Péng Yǒu.", "Sáng hôm đó, tôi muốn đến trường gặp bạn."], [17.653, 22.409, "朋友说：“坐地铁吧，又快又方便。”", "Péng Yǒu Shuō: “Zuò Dì Tiě Ba, Yòu Kuài Yòu Fāng Biàn.”", "Bạn nói: “Đi tàu điện ngầm đi, vừa nhanh vừa tiện.”"], [22.409, 26.493, "我说：“好，可是我不会买票。”", "Wǒ Shuō: “Hǎo, Kě Shì Wǒ Bú Huì Mǎi Piào.”", "Tôi nói: “Được, nhưng tôi không biết mua vé.”"], [26.493, 31.033, "朋友笑着说：“没关系，我帮你。”", "Péng Yǒu Xiào Zhe Shuō: “Méi Guān Xì, Wǒ Bāng Nǐ.”", "Bạn cười nói: “Không sao, tôi giúp bạn.”"], [31.033, 34.037, "我们一起走到地铁站。", "Wǒ Men Yì Qǐ Zǒu Dào Dì Tiě Zhàn.", "Chúng tôi cùng đi bộ đến ga tàu điện ngầm."], [34.037, 37.329, "人很多，我有一点儿紧张。", "Rén Hěn Duō, Wǒ Yǒu Yì Diǎn Ér Jǐn Zhāng.", "Người rất đông, tôi hơi lo."], [37.333, 41.249, "朋友告诉我先买票，再进站。", "Péng Yǒu Gào Sù Wǒ Xiān Mǎi Piào, Zài Jìn Zhàn.", "Bạn bảo tôi mua vé trước, rồi vào ga."], [41.249, 45.333, "我慢慢地买了票，跟朋友一起进去。", "Wǒ Màn Màn De Mǎi Le Piào, Gēn Péng Yǒu Yì Qǐ Jìn Qù.", "Tôi từ từ mua vé, cùng bạn đi vào trong."], [45.333, 48.673, "车来的时候，人更多了。", "Chē Lái De Shí Hòu, Rén Gèng Duō Le.", "Lúc tàu đến, người còn đông hơn."], [48.673, 51.629, "我担心一直要站着。", "Wǒ Dān Xīn Yì Zhí Yào Zhàn Zhe.", "Tôi lo phải đứng suốt."], [51.629, 55.809, "朋友说：“别担心，站我旁边。”", "Péng Yǒu Shuō: “Bié Dān Xīn, Zhàn Wǒ Páng Biān.”", "Bạn nói: “Đừng lo, đứng cạnh tôi.”"], [55.833, 60.757, "我们坐了四站，下车以后就到学校了。", "Wǒ Men Zuò Le Sì Zhàn, Xià Chē Yǐ Hòu Jiù Dào Xué Xiào Le.", "Chúng tôi đi bốn trạm, xuống là đến trường."], [60.757, 64.865, "我说：“真快，比坐车快多了。”", "Wǒ Shuō: “Zhēn Kuài, Bǐ Zuò Chē Kuài Duō Le.”", "Tôi nói: “Nhanh thật, nhanh hơn đi xe nhiều.”"], [64.865, 68.613, "现在我觉得地铁又快又方便。", "Xiàn Zài Wǒ Jué De Dì Tiě Yòu Kuài Yòu Fāng Biàn.", "Bây giờ tôi thấy tàu điện vừa nhanh vừa tiện."], [68.613, 72.505, "过了几天，我又坐地铁去学校。", "Guò Le Jǐ Tiān, Wǒ Yòu Zuò Dì Tiě Qù Xué Xiào.", "Qua mấy ngày, tôi lại đi tàu điện ngầm đến trường."], [72.505, 76.301, "这次我一个人去，有点儿紧张。", "Zhè Cì Wǒ Yí Gè Rén Qù, Yǒu Yì Diǎn Ér Jǐn Zhāng.", "Lần này tôi đi một mình, hơi lo."], [76.301, 79.253, "第二次我自己买票。", "Dì Èr Cì Wǒ Zì Jǐ Mǎi Piào.", "Lần thứ hai tôi tự mua vé."], [79.253, 83.049, "买完票，我不知道从哪儿进站。", "Mǎi Wán Piào, Wǒ Bù Zhī Dào Cóng Nǎ Er Jìn Zhàn.", "Mua vé xong, tôi không biết vào ga từ đâu."], [83.049, 87.205, "我问旁边的人：“请问，怎么进站？”", "Wǒ Wèn Páng Biān De Rén: “Qǐng Wèn, Zěn Me Jìn Zhàn?”", "Tôi hỏi người bên cạnh: “Xin hỏi, vào ga thế nào ạ?”"], [87.205, 91.145, "他告诉我：“往前走，就在那儿。”", "Tā Gào Sù Wǒ: “Wǎng Qián Zǒu, Jiù Zài Nà Er.”", "Anh ấy bảo tôi: “Đi về phía trước, ở ngay đó.”"], [91.153, 94.709, "我谢谢他，很快就进站了。", "Wǒ Xiè Xie Tā, Hěn Kuài Jiù Jìn Zhàn Le.", "Tôi cảm ơn anh ấy, rất nhanh đã vào được ga."], [94.709, 98.289, "车上人很多，我站了四站。", "Chē Shàng Rén Hěn Duō, Wǒ Zhàn Le Sì Zhàn.", "Trên tàu rất đông, tôi đứng suốt bốn trạm."], [98.289, 102.733, "虽然人还是很多，可是我不紧张了。", "Suī Rán Rén Hái Shì Hěn Duō, Kě Shì Wǒ Bù Jǐn Zhāng Le.", "Dù người vẫn đông, tôi không còn lo nữa."], [102.733, 106.409, "到了学校那一站，我下了车。", "Dào Le Xué Xiào Nà Yí Zhàn, Wǒ Xià Le Chē.", "Đến trạm trường, tôi xuống tàu."], [106.409, 109.365, "我看着地图找出口。", "Wǒ Kàn Zhe Dì Tú Zhǎo Chū Kǒu.", "Tôi xem bản đồ để tìm lối ra."], [109.365, 115.969, "就在这时候，我看见一位老奶奶站在地图前，看了很久。", "Jiù Zài Zhè Shí Hòu, Wǒ Kàn Jiàn Yí Wèi Lǎo Nǎi Nai Zhàn Zài Dì Tú Qián, Kàn Le Hěn Jiǔ.", "Ngay lúc đó, tôi thấy một bà cụ đứng trước tấm bản đồ, nhìn rất lâu."], [115.973, 120.633, "我走过去问她：“奶奶，您要去哪儿？”", "Wǒ Zǒu Guò Qù Wèn Tā: “Nǎi Nai, Nín Yào Qù Nǎ Er?”", "Tôi đi lại hỏi bà: “Bà ơi, bà muốn đi đâu ạ?”"], [120.633, 125.077, "她要去医院，不知道在哪一站下。", "Tā Yào Qù Yī Yuàn, Bù Zhī Dào Zài Nǎ Yí Zhàn Xià.", "Bà muốn đi bệnh viện mà không biết xuống trạm nào."], [125.077, 130.481, "我告诉她：“下一站下车，医院就在旁边。”", "Wǒ Gào Sù Tā: “Xià Yí Zhàn Xià Chē, Yī Yuàn Jiù Zài Páng Biān.”", "Tôi bảo bà: “Xuống ở trạm tiếp theo, bệnh viện ở ngay bên cạnh.”"], [130.507, 133.967, "老奶奶高兴地说：“谢谢你。”", "Lǎo Nǎi Nai Gāo Xìng De Shuō: “Xiè Xie Nǐ.”", "Bà vui vẻ nói: “Cảm ơn cháu.”"], [133.967, 138.651, "我看着老奶奶慢慢走远了，也笑了。", "Wǒ Kàn Zhe Lǎo Nǎi Nai Màn Màn Zǒu Yuǎn Le, Yě Xiào Le.", "Tôi nhìn bà cụ từ từ đi xa, cũng mỉm cười."], [138.651, 142.231, "现在我觉得自己是北京人了。", "Xiàn Zài Wǒ Jué De Zì Jǐ Shì Běi Jīng Rén Le.", "Bây giờ tôi thấy mình như người Bắc Kinh."]]}, "hsk2-03": {"dur": 147.24, "cues": [[7.698, 11.422, "那天早上，我一点儿也不舒服。", "Nà Tiān Zǎo Shàng, Wǒ Yì Diǎn Ér Yě Bù Shū Fu.", "Sáng hôm đó, tôi thấy rất không khỏe."], [11.422, 15.506, "星期一早上我头痛，也不想吃饭。", "Xīng Qī Yī Zǎo Shàng Wǒ Tóu Tòng, Yě Bù Xiǎng Chī Fàn.", "Sáng thứ Hai tôi đau đầu và không muốn ăn."], [15.506, 18.75, "我坐在床上，不想起来。", "Wǒ Zuò Zài Chuáng Shàng, Bù Xiǎng Qǐ Lái.", "Tôi ngồi trên giường, không muốn dậy."], [18.765, 22.657, "妈妈走进来，问我：“你怎么了？”", "Mā Ma Zǒu Jìn Lái, Wèn Wǒ: “Nǐ Zěn Me Le?”", "Mẹ đi vào, hỏi tôi: “Con sao thế?”"], [22.657, 26.549, "我说：“我头痛，身体也很累。”", "Wǒ Shuō: “Wǒ Tóu Tòng, Shēn Tǐ Yě Hěn Lèi.”", "Tôi nói: “Con đau đầu, người cũng rất mệt.”"], [26.549, 31.713, "妈妈把手放在我的头上，说：“有点儿热。”", "Mā Ma Bǎ Shǒu Fàng Zài Wǒ De Tóu Shàng, Shuō: “Yǒu Yì Diǎn Ér Rè.”", "Mẹ đặt tay lên đầu tôi, nói: “Hơi nóng.”"], [31.731, 35.671, "妈妈让我在家休息，不要去学校。", "Mā Ma Ràng Wǒ Zài Jiā Xiū Xi, Bú Yào Qù Xué Xiào.", "Mẹ bảo tôi nghỉ ở nhà, đừng đến trường."], [35.671, 40.835, "我担心地说：“今天有考试，我不能去了。”", "Wǒ Dān Xīn De Shuō: “Jīn Tiān Yǒu Kǎo Shì, Wǒ Bù Néng Qù Le.”", "Tôi lo lắng nói: “Hôm nay có bài kiểm tra, con không đi được rồi.”"], [40.835, 45.063, "妈妈说：“身体最重要，先休息吧。”", "Mā Ma Shuō: “Shēn Tǐ Zuì Zhòng Yào, Xiān Xiū Xi Ba.”", "Mẹ nói: “Sức khỏe quan trọng nhất, cứ nghỉ trước đi.”"], [45.065, 49.005, "我说：“好，妈妈，我听你的。”", "Wǒ Shuō: “Hǎo, Mā Ma, Wǒ Tīng Nǐ De.”", "Tôi nói: “Vâng, mẹ, con nghe lời mẹ ạ.”"], [49.005, 53.329, "我睡了两个小时，头不那么痛了。", "Wǒ Shuì Le Liǎng Gè Xiǎo Shí, Tóu Bú Nà Me Tòng Le.", "Tôi ngủ hai tiếng, đầu không đau nhiều nữa."], [53.331, 56.791, "我慢慢坐起来，喝了热水。", "Wǒ Màn Màn Zuò Qǐ Lái, Hē Le Rè Shuǐ.", "Tôi từ từ ngồi dậy, uống nước nóng."], [56.791, 60.131, "我喝了很多水，也吃了药。", "Wǒ Hē Le Hěn Duō Shuǐ, Yě Chī Le Yào.", "Tôi uống nhiều nước và cũng uống thuốc."], [60.131, 63.663, "吃完药，我觉得想吃东西了。", "Chī Wán Yào, Wǒ Jué De Xiǎng Chī Dōng Xi Le.", "Uống thuốc xong, tôi thấy muốn ăn rồi."], [63.665, 66.909, "我问妈妈：“中午吃什么？”", "Wǒ Wèn Mā Ma: “Zhōng Wǔ Chī Shén Me?”", "Tôi hỏi mẹ: “Trưa ăn gì ạ?”"], [66.909, 71.329, "妈妈笑着说：“给你做你喜欢的面。”", "Mā Ma Xiào Zhe Shuō: “Gěi Nǐ Zuò Nǐ Xǐ Huan De Miàn.”", "Mẹ cười nói: “Mẹ nấu món mì con thích cho con.”"], [71.329, 74.165, "妈妈给我做了鸡蛋面。", "Mā Ma Gěi Wǒ Zuò Le Jī Dàn Miàn.", "Mẹ nấu mì trứng cho tôi."], [74.165, 78.273, "面很热，也很好吃，我吃了很多。", "Miàn Hěn Rè, Yě Hěn Hǎo Chī, Wǒ Chī Le Hěn Duō.", "Mì rất nóng, cũng rất ngon, tôi ăn rất nhiều."], [78.273, 81.901, "吃完以后，我又休息了一会儿。", "Chī Wán Yǐ Hòu, Wǒ Yòu Xiū Xi Le Yí Huì Er.", "Ăn xong, tôi lại nghỉ một lúc."], [81.905, 85.221, "下午我给老师发了短信。", "Xià Wǔ Wǒ Gěi Lǎo Shī Fā Le Duǎn Xìn.", "Chiều tôi nhắn tin cho thầy."], [85.221, 90.865, "我在短信里说：“老师，我今天不能去学校了。”", "Wǒ Zài Duǎn Xìn Lǐ Shuō: “Lǎo Shī, Wǒ Jīn Tiān Bù Néng Qù Xué Xiào Le.”", "Tôi viết trong tin nhắn: “Thầy ơi, hôm nay em không đến trường được.”"], [90.865, 94.853, "老师说没关系，让我好好休息。", "Lǎo Shī Shuō Méi Guān Xì, Ràng Wǒ Hǎo Hǎo Xiū Xi.", "Thầy nói không sao và bảo tôi nghỉ cho khỏe."], [94.871, 99.459, "老师还告诉我，考试可以下个星期再考。", "Lǎo Shī Hái Gào Sù Wǒ, Kǎo Shì Kě Yǐ Xià Gè Xīng Qī Zài Kǎo.", "Thầy còn bảo tôi, bài kiểm tra có thể tuần sau làm cũng được."], [99.459, 102.919, "听了老师的话，我不担心了。", "Tīng Le Lǎo Shī De Huà, Wǒ Bù Dān Xīn Le.", "Nghe thầy nói vậy, tôi không lo nữa."], [102.921, 106.885, "妈妈说我要多喝水，少看电脑。", "Mā Ma Shuō Wǒ Yào Duō Hē Shuǐ, Shǎo Kàn Diàn Nǎo.", "Mẹ nói tôi nên uống nhiều nước và ít nhìn máy tính."], [106.885, 111.421, "所以那天我没有看电脑，早早就睡觉了。", "Suǒ Yǐ Nà Tiān Wǒ Méi Yǒu Kàn Diàn Nǎo, Zǎo Zǎo Jiù Shuì Jiào Le.", "Vì vậy hôm đó tôi không xem máy tính, ngủ từ sớm."], [111.421, 116.177, "星期二，我的头不痛了，也能吃饭了。", "Xīng Qī Èr, Wǒ De Tóu Bú Tòng Le, Yě Néng Chī Fàn Le.", "Thứ Ba, đầu tôi hết đau, cũng ăn được rồi."], [116.177, 119.925, "可是妈妈说：“再休息一天吧。”", "Kě Shì Mā Ma Shuō: “Zài Xiū Xi Yì Tiān Ba.”", "Nhưng mẹ nói: “Nghỉ thêm một ngày nữa đi.”"], [119.925, 124.561, "同学给我打电话，问我好一点儿了没有。", "Tóng Xué Gěi Wǒ Dǎ Diàn Huà, Wèn Wǒ Hǎo Yì Diǎn Ér Le Méi Yǒu.", "Bạn cùng lớp gọi điện cho tôi, hỏi tôi đỡ hơn chưa."], [124.561, 128.957, "我说：“好多了，谢谢你，明天见。”", "Wǒ Shuō: “Hǎo Duō Le, Xiè Xie Nǐ, Míng Tiān Jiàn.”", "Tôi nói: “Đỡ nhiều rồi, cảm ơn bạn, mai gặp nhé.”"], [128.957, 132.273, "星期三我又回到了教室。", "Xīng Qī Sān Wǒ Yòu Huí Dào Le Jiào Shì.", "Thứ Tư tôi lại trở lại lớp."], [132.273, 137.001, "我对同学们说：“谢谢你们。”大家都笑了。", "Wǒ Duì Tóng Xué Men Shuō: “Xiè Xie Nǐ Men.” Dà Jiā Dōu Xiào Le.", "Tôi nói với các bạn: “Cảm ơn các bạn.” Mọi người đều cười."]]}, "hsk2-04": {"dur": 152.39, "cues": [[6.859, 9.959, "给妹妹买什么礼物好呢？", "Gěi Mèi Mei Mǎi Shén Me Lǐ Wù Hǎo Ne?", "Nên mua quà gì cho em gái đây?"], [9.959, 13.083, "星期天是妹妹的生日。", "Xīng Qī Tiān Shì Mèi Mei De Shēng Rì.", "Chủ nhật là sinh nhật em gái."], [13.083, 15.919, "我想给她买一个礼物。", "Wǒ Xiǎng Gěi Tā Mǎi Yí Gè Lǐ Wù.", "Tôi muốn mua cho em một món quà."], [15.926, 18.978, "可是我不知道买什么好。", "Kě Shì Wǒ Bù Zhī Dào Mǎi Shén Me Hǎo.", "Nhưng tôi không biết mua gì thì tốt."], [18.978, 22.678, "我问妈妈：“妹妹最喜欢什么？”", "Wǒ Wèn Mā Ma: “Mèi Mei Zuì Xǐ Huan Shén Me?”", "Tôi hỏi mẹ: “Em thích nhất cái gì?”"], [22.678, 27.194, "妈妈说：“她喜欢画画，也喜欢看书。”", "Mā Ma Shuō: “Tā Xǐ Huan Huà Huà, Yě Xǐ Huan Kàn Shū.”", "Mẹ nói: “Em thích vẽ, cũng thích đọc sách.”"], [27.226, 31.334, "我想了想，说：“我去商店看看。”", "Wǒ Xiǎng Le Xiǎng, Shuō: “Wǒ Qù Shāng Diàn Kàn Kan.”", "Tôi nghĩ một lúc, nói: “Con đi cửa hàng xem thử.”"], [31.334, 35.442, "星期六下午，我一个人去了商店。", "Xīng Qī Liù Xià Wǔ, Wǒ Yí Gè Rén Qù Le Shāng Diàn.", "Chiều thứ Bảy, tôi một mình đến cửa hàng."], [35.442, 39.334, "商店里有书、衣服和玩具。", "Shāng Diàn Lǐ Yǒu Shū, Yī Fu Hé Wán Jù.", "Trong cửa hàng có sách, quần áo và đồ chơi."], [39.359, 44.667, "我先看衣服，衣服很漂亮，可是太贵了。", "Wǒ Xiān Kàn Yī Fu, Yī Fu Hěn Piào Liang, Kě Shì Tài Guì Le.", "Tôi xem quần áo trước, quần áo rất đẹp nhưng đắt quá."], [44.667, 50.071, "我又看玩具，玩具很多，我不知道选哪个。", "Wǒ Yòu Kàn Wán Jù, Wán Jù Hěn Duō, Wǒ Bù Zhī Dào Xuǎn Nǎ Ge.", "Tôi lại xem đồ chơi, đồ chơi rất nhiều, tôi không biết chọn cái nào."], [50.092, 54.248, "这时候，我看见了一本画画的书。", "Zhè Shí Hòu, Wǒ Kàn Jiàn Le Yì Běn Huà Huà De Shū.", "Lúc này, tôi thấy một cuốn sách về vẽ."], [54.248, 59.388, "书很好看，可是妹妹已经有这样的书了。", "Shū Hěn Hǎo Kàn, Kě Shì Mèi Mei Yǐ Jīng Yǒu Zhè Yàng De Shū Le.", "Sách rất đẹp, nhưng em đã có cuốn như vậy rồi."], [59.388, 62.992, "我有点儿担心，时间不多了。", "Wǒ Yǒu Yì Diǎn Ér Dān Xīn, Shí Jiān Bù Duō Le.", "Tôi hơi lo, thời gian không còn nhiều."], [62.992, 66.716, "服务员走过来问：“你想买什么？”", "Fú Wù Yuán Zǒu Guò Lái Wèn: “Nǐ Xiǎng Mǎi Shén Me?”", "Nhân viên đi tới hỏi: “Bạn muốn mua gì?”"], [66.716, 70.776, "我说：“我想给妹妹买生日礼物。”", "Wǒ Shuō: “Wǒ Xiǎng Gěi Mèi Mei Mǎi Shēng Rì Lǐ Wù.”", "Tôi nói: “Tôi muốn mua quà sinh nhật cho em gái.”"], [70.776, 76.156, "服务员说：“她喜欢画画，你可以买彩色笔。”", "Fú Wù Yuán Shuō: “Tā Xǐ Huan Huà Huà, Nǐ Kě Yǐ Mǎi Cǎi Sè Bǐ.”", "Nhân viên nói: “Em ấy thích vẽ, bạn có thể mua bút màu.”"], [76.159, 81.635, "我听了很高兴，说：“对，我怎么没想到呢？”", "Wǒ Tīng Le Hěn Gāo Xìng, Shuō: “Duì, Wǒ Zěn Me Méi Xiǎng Dào Ne?”", "Nghe vậy tôi rất vui, nói: “Đúng rồi, sao tôi không nghĩ ra nhỉ?”"], [81.635, 86.055, "妹妹喜欢画画，所以我买了彩色笔。", "Mèi Mei Xǐ Huan Huà Huà, Suǒ Yǐ Wǒ Mǎi Le Cǎi Sè Bǐ.", "Em thích vẽ nên tôi mua bút màu."], [86.055, 89.707, "彩色笔不贵，可是很好看。", "Cǎi Sè Bǐ Bú Guì, Kě Shì Hěn Hǎo Kàn.", "Bút màu không đắt nhưng rất đẹp."], [89.726, 94.194, "彩色笔颜色很多，妹妹一定喜欢。", "Cǎi Sè Bǐ Yán Sè Hěn Duō, Mèi Mei Yí Dìng Xǐ Huan.", "Bút màu có rất nhiều màu, em nhất định sẽ thích."], [94.194, 97.222, "我还买了一张生日卡。", "Wǒ Hái Mǎi Le Yì Zhāng Shēng Rì Kǎ.", "Tôi còn mua một tấm thiệp sinh nhật."], [97.222, 102.674, "在生日卡上，我写了：“妹妹，生日快乐！”", "Zài Shēng Rì Kǎ Shàng, Wǒ Xiě Le: “Mèi Mei, Shēng Rì Kuài Lè!”", "Trên tấm thiệp sinh nhật, tôi viết: “Em gái, sinh nhật vui vẻ!”"], [102.692, 107.472, "回家的路上，我想：妹妹会喜欢吗？", "Huí Jiā De Lù Shàng, Wǒ Xiǎng: Mèi Mei Huì Xǐ Huan Ma?", "Trên đường về nhà, tôi nghĩ: em có thích không nhỉ?"], [107.472, 110.884, "晚上我把礼物放在桌子上。", "Wǎn Shàng Wǒ Bǎ Lǐ Wù Fàng Zài Zhuō Zi Shàng.", "Tối tôi đặt quà lên bàn."], [110.892, 115.24, "我叫妹妹过来，说：“这是给你的。”", "Wǒ Jiào Mèi Mei Guò Lái, Shuō: “Zhè Shì Gěi Nǐ De.”", "Tôi gọi em lại, nói: “Cái này tặng em.”"], [115.24, 118.22, "妹妹一看见就笑了。", "Mèi Mei Yí Kàn Jiàn Jiù Xiào Le.", "Em gái vừa thấy là cười."], [118.22, 122.808, "她打开礼物，高兴地说：“好多颜色！”", "Tā Dǎ Kāi Lǐ Wù, Gāo Xìng De Shuō: “Hǎo Duō Yán Sè!”", "Em mở quà ra, vui vẻ nói: “Nhiều màu quá!”"], [122.826, 125.926, "她马上用新笔画画。", "Tā Mǎ Shàng Yòng Xīn Bǐ Huà Huà.", "Em dùng ngay bút mới để vẽ."], [125.926, 130.586, "她画了我们一家人，还画了爸爸妈妈。", "Tā Huà Le Wǒ Men Yì Jiā Rén, Hái Huà Le Bà Ba Mā Ma.", "Em vẽ cả nhà chúng tôi, còn vẽ cả bố mẹ."], [130.586, 134.478, "她把画送给我，说：“谢谢你。”", "Tā Bǎ Huà Sòng Gěi Wǒ, Shuō: “Xiè Xie Nǐ.”", "Em tặng bức vẽ cho tôi và nói: “Cảm ơn nhé!”"], [134.492, 137.616, "爸爸说我很会选礼物。", "Bà Ba Shuō Wǒ Hěn Huì Xuǎn Lǐ Wù.", "Bố nói tôi rất biết chọn quà."], [137.616, 142.156, "我们一家人一起看妹妹的画，都笑了。", "Wǒ Men Yì Jiā Rén Yì Qǐ Kàn Mèi Mei De Huà, Dōu Xiào Le.", "Cả nhà chúng tôi cùng xem bức vẽ của em gái, ai cũng cười."]]}, "hsk2-05": {"dur": 142.84, "cues": [[7.631, 10.539, "今天中午吃什么好呢？", "Jīn Tiān Zhōng Wǔ Chī Shén Me Hǎo Ne?", "Trưa nay ăn gì thì ngon nhỉ?"], [10.539, 13.255, "我已经很想吃饭了。", "Wǒ Yǐ Jīng Hěn Xiǎng Chī Fàn Le.", "Tôi đã rất muốn ăn cơm rồi."], [13.264, 16.892, "中午我们三个人去饭馆吃饭。", "Zhōng Wǔ Wǒ Men Sān Gè Rén Qù Fàn Guǎn Chī Fàn.", "Trưa ba chúng tôi ra quán ăn."], [16.892, 20.952, "这家饭馆离学校不远，人很多。", "Zhè Jiā Fàn Guǎn Lí Xué Xiào Bù Yuǎn, Rén Hěn Duō.", "Quán này cách trường không xa, rất đông người."], [20.952, 24.46, "我们找了一个桌子，坐了下来。", "Wǒ Men Zhǎo Le Yí Gè Zhuō Zi, Zuò Le Xià Lái.", "Chúng tôi tìm một cái bàn, ngồi xuống."], [24.464, 29.892, "服务员走过来，笑着说：“请进，请坐。”", "Fú Wù Yuán Zǒu Guò Lái, Xiào Zhe Shuō: “Qǐng Jìn, Qǐng Zuò.”", "Nhân viên đi tới, cười nói: “Mời vào, mời ngồi.”"], [29.892, 32.824, "服务员问我们想吃什么。", "Fú Wù Yuán Wèn Wǒ Men Xiǎng Chī Shén Me.", "Nhân viên hỏi chúng tôi muốn ăn gì."], [32.824, 35.54, "她把菜单给了我们。", "Tā Bǎ Cài Dān Gěi Le Wǒ Men.", "Cô ấy đưa thực đơn cho chúng tôi."], [35.564, 40.224, "菜单上的菜很多，我看了很长时间。", "Cài Dān Shàng De Cài Hěn Duō, Wǒ Kàn Le Hěn Cháng Shí Jiān.", "Trong thực đơn có rất nhiều món, tôi xem rất lâu."], [40.224, 44.98, "一个朋友说：“我想吃鱼，鱼对身体好。”", "Yí Gè Péng Yǒu Shuō: “Wǒ Xiǎng Chī Yú, Yú Duì Shēn Tǐ Hǎo.”", "Một người bạn nói: “Tôi muốn ăn cá, cá tốt cho sức khỏe.”"], [44.98, 50.288, "一个朋友说：“我不想吃面条，我想吃米饭。”", "Yí Gè Péng Yǒu Shuō: “Wǒ Bù Xiǎng Chī Miàn Tiáo, Wǒ Xiǎng Chī Mǐ Fàn.”", "Một người bạn nói: “Tôi không muốn ăn mì, tôi muốn ăn cơm.”"], [50.298, 55.51, "我说：“那我们点一个鱼，再点一盘青菜吧。”", "Wǒ Shuō: “Nà Wǒ Men Diǎn Yí Gè Yú, Zài Diǎn Yì Pán Qīng Cài Ba.”", "Tôi nói: “Vậy chúng ta gọi một món cá, thêm một đĩa rau nhé.”"], [55.51, 57.866, "朋友们都说好。", "Péng Yǒu Men Dōu Shuō Hǎo.", "Các bạn đều đồng ý."], [57.866, 63.174, "可是我还想吃面条，面条是这里最好吃的。", "Kě Shì Wǒ Hái Xiǎng Chī Miàn Tiáo, Miàn Tiáo Shì Zhè Lǐ Zuì Hǎo Chī De.", "Nhưng tôi còn muốn ăn mì, mì là món ngon nhất ở đây."], [63.198, 67.21, "我点了面条，朋友点了米饭和鱼。", "Wǒ Diǎn Le Miàn Tiáo, Péng Yǒu Diǎn Le Mǐ Fàn Hé Yú.", "Tôi gọi mì, bạn gọi cơm và cá."], [67.21, 70.022, "我们还点了一盘青菜。", "Wǒ Men Hái Diǎn Le Yì Pán Qīng Cài.", "Chúng tôi còn gọi một đĩa rau."], [70.031, 73.155, "服务员问：“你们喝什么？”", "Fú Wù Yuán Wèn: “Nǐ Men Hē Shén Me?”", "Nhân viên hỏi: “Các bạn uống gì?”"], [73.155, 76.687, "我们说：“我们喝茶，谢谢。”", "Wǒ Men Shuō: “Wǒ Men Hē Chá, Xiè Xie.”", "Chúng tôi nói: “Chúng tôi uống trà, cảm ơn.”"], [76.698, 80.014, "服务员很快就把菜端来了。", "Fú Wù Yuán Hěn Kuài Jiù Bǎ Cài Duān Lái Le.", "Nhân viên rất nhanh bưng món lên."], [80.014, 83.354, "菜来了以后，我们一起吃。", "Cài Lái Le Yǐ Hòu, Wǒ Men Yì Qǐ Chī.", "Món lên rồi, chúng tôi ăn cùng nhau."], [83.364, 86.152, "我先吃了一口面条。", "Wǒ Xiān Chī Le Yì Kǒu Miàn Tiáo.", "Tôi ăn thử một miếng mì trước."], [86.152, 89.06, "我觉得面条有一点儿咸。", "Wǒ Jué De Miàn Tiáo Yǒu Yì Diǎn Ér Xián.", "Tôi thấy mì hơi mặn."], [89.06, 92.952, "我有点儿担心，怕朋友们不喜欢。", "Wǒ Yǒu Yì Diǎn Ér Dān Xīn, Pà Péng Yǒu Men Bù Xǐ Huan.", "Tôi hơi lo, sợ các bạn không thích."], [92.964, 96.04, "可是朋友们都吃了很多。", "Kě Shì Péng Yǒu Men Dōu Chī Le Hěn Duō.", "Nhưng các bạn đều ăn rất nhiều."], [96.04, 98.756, "朋友说鱼很新鲜。", "Péng Yǒu Shuō Yú Hěn Xīn Xiān.", "Bạn nói cá rất tươi."], [98.756, 102.404, "一个朋友说：“青菜也很好吃。”", "Yí Gè Péng Yǒu Shuō: “Qīng Cài Yě Hěn Hǎo Chī.”", "Một người bạn nói: “Rau cũng rất ngon.”"], [102.404, 105.96, "我笑着说：“下次我们还来。”", "Wǒ Xiào Zhe Shuō: “Xià Cì Wǒ Men Hái Lái.”", "Tôi cười nói: “Lần sau chúng ta lại đến.”"], [105.96, 110.164, "吃饭的时候，我们说了很多学校的事。", "Chī Fàn De Shí Hòu, Wǒ Men Shuō Le Hěn Duō Xué Xiào De Shì.", "Lúc ăn, chúng tôi nói rất nhiều chuyện ở trường."], [110.164, 113.48, "饭不太贵，味道也很好。", "Fàn Bú Tài Guì, Wèi Dào Yě Hěn Hǎo.", "Cơm không đắt lắm, vị cũng rất ngon."], [113.504, 116.772, "吃完以后我们一起付钱。", "Chī Wán Yǐ Hòu Wǒ Men Yì Qǐ Fù Qián.", "Ăn xong chúng tôi cùng trả tiền."], [116.772, 119.844, "三个人花了六十块钱。", "Sān Gè Rén Huā Le Liù Shí Kuài Qián.", "Ba người hết sáu mươi tệ."], [119.844, 125.752, "走出饭馆，外面天气很好，我们慢慢走回学校。", "Zǒu Chū Fàn Guǎn, Wài Miàn Tiān Qì Hěn Hǎo, Wǒ Men Màn Màn Zǒu Huí Xué Xiào.", "Ra khỏi quán, ngoài trời thời tiết rất đẹp, chúng tôi từ từ đi bộ về trường."], [125.752, 132.62, "走回学校的路上，朋友们一边走一边笑，说今天的鱼真好吃。", "Zǒu Huí Xué Xiào De Lù Shàng, Péng Yǒu Men Yì Biān Zǒu Yì Biān Xiào, Shuō Jīn Tiān De Yú Zhēn Hǎo Chī.", "Trên đường đi bộ về trường, các bạn vừa đi vừa cười, nói cá hôm nay ngon thật."]]}, "hsk2-06": {"dur": 166.89, "cues": [[6.847, 9.059, "你喜欢运动吗？", "Nǐ Xǐ Huan Yùn Dòng Ma?", "Bạn có thích vận động không?"], [9.059, 11.847, "我以前不喜欢运动。", "Wǒ Yǐ Qián Bù Xǐ Huan Yùn Dòng.", "Trước đây tôi không thích vận động."], [11.847, 15.811, "我以前下课就回家，不出去玩儿。", "Wǒ Yǐ Qián Xià Kè Jiù Huí Jiā, Bù Chū Qù Wánr.", "Trước đây tan học là tôi về nhà, không ra ngoài chơi."], [15.813, 19.321, "我觉得运动很累，也不好玩儿。", "Wǒ Jué De Yùn Dòng Hěn Lèi, Yě Bù Hǎo Wánr.", "Tôi thấy vận động rất mệt, cũng không vui."], [19.321, 24.461, "有一天，同学问我：“你想不想去跑步？”", "Yǒu Yì Tiān, Tóng Xué Wèn Wǒ: “Nǐ Xiǎng Bù Xiǎng Qù Pǎo Bù?”", "Một hôm, bạn học hỏi tôi: “Bạn có muốn đi chạy bộ không?”"], [24.461, 28.377, "我说：“我跑得慢，怕跑不好。”", "Wǒ Shuō: “Wǒ Pǎo Dé Màn, Pà Pǎo Bù Hǎo.”", "Tôi nói: “Tôi chạy chậm, sợ chạy không tốt.”"], [28.38, 32.584, "同学说：“没关系，我们慢慢跑。”", "Tóng Xué Shuō: “Méi Guān Xì, Wǒ Men Màn Màn Pǎo.”", "Bạn học nói: “Không sao, chúng ta chạy chậm thôi.”"], [32.584, 39.092, "回家以后，我把这件事告诉了妈妈，妈妈笑着说：“好啊！”", "Huí Jiā Yǐ Hòu, Wǒ Bǎ Zhè Jiàn Shì Gào Sù Le Mā Ma, Mā Ma Xiào Zhe Shuō: “Hǎo A!”", "Về nhà, tôi kể chuyện này cho mẹ, mẹ cười nói: “Tốt quá!”"], [39.113, 43.197, "现在每天下午我都去操场跑步。", "Xiàn Zài Měi Tiān Xià Wǔ Wǒ Dōu Qù Cāo Chǎng Pǎo Bù.", "Bây giờ mỗi chiều tôi đều ra sân chạy bộ."], [43.197, 47.137, "下午五点，我们一起到操场。", "Xià Wǔ Wǔ Diǎn, Wǒ Men Yì Qǐ Dào Cāo Chǎng.", "Chiều lúc năm giờ, chúng tôi cùng ra sân."], [47.137, 50.405, "天气很好，不冷也不热。", "Tiān Qì Hěn Hǎo, Bù Lěng Yě Bú Rè.", "Thời tiết rất đẹp, không lạnh cũng không nóng."], [50.413, 54.305, "跑完以后，我觉得身体很好。", "Pǎo Wán Yǐ Hòu, Wǒ Jué De Shēn Tǐ Hěn Hǎo.", "Chạy xong, tôi thấy người khỏe."], [54.305, 57.645, "我晚上睡觉也睡得很好。", "Wǒ Wǎn Shàng Shuì Jiào Yě Shuì Dé Hěn Hǎo.", "Buổi tối tôi ngủ cũng rất ngon."], [57.645, 61.393, "第二天上课，我也不觉得累了。", "Dì Èr Tiān Shàng Kè, Wǒ Yě Bù Jué De Lèi Le.", "Hôm sau đi học, tôi cũng không thấy mệt nữa."], [61.393, 65.189, "星期六我还和同学打篮球。", "Xīng Qī Liù Wǒ Hái Hé Tóng Xué Dǎ Lán Qiú.", "Thứ Bảy tôi còn chơi bóng rổ với bạn học."], [65.189, 68.889, "我们班的同学都喜欢打篮球。", "Wǒ Men Bān De Tóng Xué Dōu Xǐ Huan Dǎ Lán Qiú.", "Các bạn trong lớp tôi đều thích chơi bóng rổ."], [68.889, 72.781, "打篮球以前，同学教我怎么打。", "Dǎ Lán Qiú Yǐ Qián, Tóng Xué Jiào Wǒ Zěn Me Dǎ.", "Trước khi chơi bóng rổ, bạn học dạy tôi cách chơi."], [72.793, 76.877, "虽然有时很累，可是我很快乐。", "Suī Rán Yǒu Shí Hěn Lèi, Kě Shì Wǒ Hěn Kuài Lè.", "Đôi khi rất mệt, nhưng tôi rất vui."], [76.877, 80.385, "跑步以前我先喝一点儿水。", "Pǎo Bù Yǐ Qián Wǒ Xiān Hē Yì Diǎn Ér Shuǐ.", "Trước khi chạy tôi uống một chút nước."], [80.385, 83.124, "我也先慢慢走一会儿。", "Wǒ Yě Xiān Màn Màn Zǒu Yí Huì Er.", "Tôi cũng đi bộ chậm một lúc trước."], [83.127, 86.251, "有一天，我不想跑了。", "Yǒu Yì Tiān, Wǒ Bù Xiǎng Pǎo Le.", "Có một hôm, tôi không muốn chạy nữa."], [86.251, 91.367, "我对同学说：“今天太累了，我想休息。”", "Wǒ Duì Tóng Xué Shuō: “Jīn Tiān Tài Lèi Le, Wǒ Xiǎng Xiū Xi.”", "Tôi nói với bạn học: “Hôm nay mệt quá, tôi muốn nghỉ.”"], [91.367, 95.763, "同学说：“我们今天跑慢一点儿，好吗？”", "Tóng Xué Shuō: “Wǒ Men Jīn Tiān Pǎo Màn Yì Diǎn Ér, Hǎo Ma?”", "Bạn học nói: “Hôm nay chúng ta chạy chậm một chút, được không?”"], [95.767, 99.251, "听了他的话，我又跑了一会儿。", "Tīng Le Tā De Huà, Wǒ Yòu Pǎo Le Yí Huì Er.", "Nghe bạn nói vậy, tôi lại chạy thêm một lúc."], [99.251, 105.975, "跑完以后，我们坐在操场旁边休息，说了很多运动的事。", "Pǎo Wán Yǐ Hòu, Wǒ Men Zuò Zài Cāo Chǎng Páng Biān Xiū Xi, Shuō Le Hěn Duō Yùn Dòng De Shì.", "Chạy xong, chúng tôi ngồi nghỉ bên sân vận động, nói rất nhiều chuyện về vận động."], [105.975, 110.367, "跑了二十分钟，我的衣服都湿了。", "Pǎo Le Èr Shí Fēn Zhōng, Wǒ De Yī Fu Dōu Shī Le.", "Chạy hai mươi phút, áo tôi ướt hết."], [110.367, 113.731, "同学说我比上个月快了。", "Tóng Xué Shuō Wǒ Bǐ Shàng Gè Yuè Kuài Le.", "Bạn học nói tôi nhanh hơn tháng trước."], [113.731, 119.107, "我听了很高兴，说：“谢谢你和我一起跑。”", "Wǒ Tīng Le Hěn Gāo Xìng, Shuō: “Xiè Xie Nǐ Hé Wǒ Yì Qǐ Pǎo.”", "Nghe vậy tôi rất vui, nói: “Cảm ơn bạn đã chạy cùng tôi.”"], [119.107, 122.758, "打篮球的时候我进了两个球。", "Dǎ Lán Qiú De Shí Hòu Wǒ Jìn Le Liǎng Gè Qiú.", "Lúc chơi bóng rổ tôi ghi hai bàn."], [122.758, 126.026, "同学们都说：“太好了！”", "Tóng Xué Men Dōu Shuō: “Tài Hǎo Le!”", "Các bạn đều nói: “Tuyệt quá!”"], [126.026, 130.831, "那天我回家告诉妈妈，我进了两个球。", "Nà Tiān Wǒ Huí Jiā Gào Sù Mā Ma, Wǒ Jìn Le Liǎng Gè Qiú.", "Hôm đó về nhà tôi kể với mẹ là tôi ghi được hai bàn."], [130.839, 134.875, "那天的篮球比赛，最后我们输了。", "Nà Tiān De Lán Qiú Bǐ Sài, Zuì Hòu Wǒ Men Shū Le.", "Trận bóng rổ hôm đó, cuối cùng chúng tôi thua."], [134.875, 137.856, "虽然输了也没关系。", "Suī Rán Shū Le Yě Méi Guān Xì.", "Dù thua cũng không sao."], [137.856, 141.028, "重要的是我们一起运动。", "Zhòng Yào De Shì Wǒ Men Yì Qǐ Yùn Dòng.", "Quan trọng là chúng tôi vận động cùng nhau."], [141.04, 145.363, "和同学一起运动，时间过得很快。", "Hé Tóng Xué Yì Qǐ Yùn Dòng, Shí Jiān Guò Dé Hěn Kuài.", "Vận động cùng bạn học, thời gian trôi rất nhanh."], [145.363, 148.584, "现在我每天都想运动。", "Xiàn Zài Wǒ Měi Tiān Dōu Xiǎng Yùn Dòng.", "Bây giờ ngày nào tôi cũng muốn vận động."], [148.584, 152.716, "运动让我身体好，也让我很快乐。", "Yùn Dòng Ràng Wǒ Shēn Tǐ Hǎo, Yě Ràng Wǒ Hěn Kuài Lè.", "Vận động giúp tôi khỏe và cũng giúp tôi rất vui."], [152.716, 156.656, "明天我还要和同学一起去跑步。", "Míng Tiān Wǒ Hái Yào Hé Tóng Xué Yì Qǐ Qù Pǎo Bù.", "Ngày mai tôi vẫn muốn cùng bạn học đi chạy bộ."]]}, "hsk2-07": {"dur": 147.66, "cues": [[7.113, 9.949, "你给旅馆打过电话吗？", "Nǐ Gěi Lǚ Guǎn Dǎ Guò Diàn Huà Ma?", "Bạn đã từng gọi điện cho khách sạn chưa?"], [9.949, 13.049, "下个星期我们去上海。", "Xià Gè Xīng Qī Wǒ Men Qù Shàng Hǎi.", "Tuần sau chúng tôi đi Thượng Hải."], [13.049, 15.981, "我们要去上海玩儿三天。", "Wǒ Men Yào Qù Shàng Hǎi Wánr Sān Tiān.", "Chúng tôi sẽ đến Thượng Hải chơi ba ngày."], [16.013, 20.625, "爸爸妈妈白天都很忙，没有时间打电话。", "Bà Ba Mā Ma Bái Tiān Dōu Hěn Máng, Méi Yǒu Shí Jiān Dǎ Diàn Huà.", "Ban ngày bố mẹ đều rất bận, không có thời gian gọi điện."], [20.625, 24.133, "爸爸让我打电话订一个房间。", "Bà Ba Ràng Wǒ Dǎ Diàn Huà Dìng Yí Gè Fáng Jiān.", "Bố bảo tôi gọi điện đặt một phòng."], [24.133, 27.329, "我问爸爸：“我要说什么？”", "Wǒ Wèn Bà Ba: “Wǒ Yào Shuō Shén Me?”", "Tôi hỏi bố: “Con phải nói gì?”"], [27.346, 31.118, "爸爸说：“你先问有没有房间。”", "Bà Ba Shuō: “Nǐ Xiān Wèn Yǒu Méi Yǒu Fáng Jiān.”", "Bố nói: “Con hỏi trước xem còn phòng không.”"], [31.118, 34.554, "爸爸还告诉我房间要安静。", "Bà Ba Hái Gào Sù Wǒ Fáng Jiān Yào Ān Jìng.", "Bố còn dặn tôi phòng phải yên tĩnh."], [34.554, 37.582, "我先把要说的话写下来。", "Wǒ Xiān Bǎ Yào Shuō De Huà Xiě Xià Lái.", "Tôi viết trước những điều cần nói ra."], [37.586, 41.07, "我打电话的时候有一点儿紧张。", "Wǒ Dǎ Diàn Huà De Shí Hòu Yǒu Yì Diǎn Ér Jǐn Zhāng.", "Lúc gọi điện tôi hơi hồi hộp."], [41.07, 46.666, "我拿着电话，慢慢说：“你好，我想订房间。”", "Wǒ Ná Zhe Diàn Huà, Màn Màn Shuō: “Nǐ Hǎo, Wǒ Xiǎng Dìng Fáng Jiān.”", "Tôi cầm điện thoại, chậm rãi nói: “Xin chào, tôi muốn đặt phòng.”"], [46.686, 49.666, "旅馆的人问我住几天。", "Lǚ Guǎn De Rén Wèn Wǒ Zhù Jǐ Tiān.", "Người ở khách sạn hỏi tôi ở mấy ngày."], [49.666, 52.502, "旅馆的人说话很快。", "Lǚ Guǎn De Rén Shuō Huà Hěn Kuài.", "Người ở khách sạn nói rất nhanh."], [52.502, 54.926, "我有一点儿听不懂。", "Wǒ Yǒu Yì Diǎn Ér Tīng Bù Dǒng.", "Tôi hơi không nghe hiểu."], [54.926, 57.354, "我请她慢慢说。", "Wǒ Qǐng Tā Màn Màn Shuō.", "Tôi nhờ cô ấy nói chậm."], [57.354, 60.55, "她慢慢说：“你住几天？”", "Tā Màn Màn Shuō: “Nǐ Zhù Jǐ Tiān?”", "Cô ấy nói chậm: “Bạn ở mấy ngày?”"], [60.55, 64.296, "这次我听懂了，心里很高兴。", "Zhè Cì Wǒ Tīng Dǒng Le, Xīn Lǐ Hěn Gāo Xìng.", "Lần này tôi nghe hiểu, trong lòng rất vui."], [64.296, 68.668, "我说住两个晚上，要一个安静的房间。", "Wǒ Shuō Zhù Liǎng Gè Wǎn Shàng, Yào Yí Gè Ān Jìng De Fáng Jiān.", "Tôi nói ở hai đêm và muốn một phòng yên tĩnh."], [68.668, 72.08, "我还问她：“房间多少钱？”", "Wǒ Hái Wèn Tā: “Fáng Jiān Duō Shǎo Qián?”", "Tôi còn hỏi cô ấy: “Phòng bao nhiêu tiền?”"], [72.08, 75.42, "她说：“一个晚上二百块。”", "Tā Shuō: “Yí Gè Wǎn Shàng Èr Bǎi Kuài.”", "Cô ấy nói: “Một đêm hai trăm tệ.”"], [75.43, 80.666, "我觉得不贵，就说：“好，我要这个房间。”", "Wǒ Jué De Bú Guì, Jiù Shuō: “Hǎo, Wǒ Yào Zhè Gè Fáng Jiān.”", "Tôi thấy không đắt, bèn nói: “Được, tôi lấy phòng này.”"], [80.666, 84.774, "她告诉我房间有窗户，也有热水。", "Tā Gào Sù Wǒ Fáng Jiān Yǒu Chuāng Hù, Yě Yǒu Rè Shuǐ.", "Cô ấy nói phòng có cửa sổ và có nước nóng."], [84.774, 88.09, "我问：“早上可以吃饭吗？”", "Wǒ Wèn: “Zǎo Shàng Kě Yǐ Chī Fàn Ma?”", "Tôi hỏi: “Buổi sáng có ăn cơm được không?”"], [88.096, 91.892, "她说：“可以，楼下有饭馆。”", "Tā Shuō: “Kě Yǐ, Lóu Xià Yǒu Fàn Guǎn.”", "Cô ấy nói: “Được, dưới lầu có quán ăn.”"], [91.892, 95.304, "我说：“好的，谢谢你。”", "Wǒ Shuō: “Hǎo De, Xiè Xie Nǐ.”", "Tôi nói: “Được ạ, cảm ơn bạn.”"], [95.306, 98.478, "打完电话，我不紧张了。", "Dǎ Wán Diàn Huà, Wǒ Bù Jǐn Zhāng Le.", "Gọi điện xong, tôi không còn hồi hộp nữa."], [98.478, 102.13, "妈妈在旁边听了，也很高兴。", "Mā Ma Zài Páng Biān Tīng Le, Yě Hěn Gāo Xìng.", "Mẹ ở bên cạnh nghe, cũng rất vui."], [102.14, 105.432, "我把地址写下来发给爸爸。", "Wǒ Bǎ Dì Zhǐ Xiě Xià Lái Fā Gěi Bà Ba.", "Tôi chép địa chỉ rồi gửi cho bố."], [105.432, 112.156, "写完以后，我看着本子，心里想：这是我自己订的房间。", "Xiě Wán Yǐ Hòu, Wǒ Kàn Zhe Běn Zi, Xīn Lǐ Xiǎng: Zhè Shì Wǒ Zì Jǐ Dìng De Fáng Jiān.", "Viết xong, tôi nhìn cuốn sổ, thầm nghĩ: Đây là căn phòng do chính mình đặt."], [112.173, 116.425, "爸爸看了以后，问我：“房间怎么样？”", "Bà Ba Kàn Le Yǐ Hòu, Wèn Wǒ: “Fáng Jiān Zěn Me Yàng?”", "Bố xem xong, hỏi tôi: “Phòng thế nào?”"], [116.425, 121.061, "我告诉爸爸：“房间很安静，也有热水。”", "Wǒ Gào Sù Bà Ba: “Fáng Jiān Hěn Ān Jìng, Yě Yǒu Rè Shuǐ.”", "Tôi nói với bố: “Phòng rất yên tĩnh, cũng có nước nóng.”"], [121.061, 123.897, "爸爸说我做得很对。", "Bà Ba Shuō Wǒ Zuò Dé Hěn Duì.", "Bố nói tôi làm rất đúng."], [123.906, 128.206, "爸爸说，下次打电话还可以让我打。", "Bà Ba Shuō, Xià Cì Dǎ Diàn Huà Hái Kě Yǐ Ràng Wǒ Dǎ.", "Bố nói lần sau gọi điện vẫn có thể để tôi gọi."], [128.206, 133.394, "我很高兴，下个星期我们可以去上海玩儿了。", "Wǒ Hěn Gāo Xìng, Xià Gè Xīng Qī Wǒ Men Kě Yǐ Qù Shàng Hǎi Wánr Le.", "Tôi rất vui, tuần sau chúng tôi có thể đi Thượng Hải chơi rồi."], [133.394, 137.43, "这是我第一次一个人打电话订房间。", "Zhè Shì Wǒ Dì Yī Cì Yí Gè Rén Dǎ Diàn Huà Dìng Fáng Jiān.", "Đây là lần đầu tiên tôi tự mình gọi điện đặt phòng."]]}, "hsk2-08": {"dur": 153.78, "cues": [[7.871, 10.107, "你会做饭吗？", "Nǐ Huì Zuò Fàn Ma?", "Bạn có biết nấu ăn không?"], [10.107, 13.639, "我以前不会做饭，只会吃。", "Wǒ Yǐ Qián Bú Huì Zuò Fàn, Zhǐ Huì Chī.", "Trước đây tôi không biết nấu ăn, chỉ biết ăn."], [13.641, 17.293, "昨天晚上妈妈教我做鸡蛋面。", "Zuó Tiān Wǎn Shàng Mā Ma Jiào Wǒ Zuò Jī Dàn Miàn.", "Tối qua mẹ dạy tôi nấu mì trứng."], [17.293, 20.657, "妈妈问我：“你想不想学？”", "Mā Ma Wèn Wǒ: “Nǐ Xiǎng Bù Xiǎng Xué?”", "Mẹ hỏi tôi: “Con có muốn học không?”"], [20.657, 24.741, "我说：“想，可是我怕做不好。”", "Wǒ Shuō: “Xiǎng, Kě Shì Wǒ Pà Zuò Bù Hǎo.”", "Tôi nói: “Muốn, nhưng con sợ làm không tốt.”"], [24.741, 28.513, "妈妈说：“没关系，我教你。”", "Mā Ma Shuō: “Méi Guān Xì, Wǒ Jiào Nǐ.”", "Mẹ nói: “Không sao, mẹ dạy con.”"], [28.513, 31.805, "妈妈先给我看鸡蛋和面。", "Mā Ma Xiān Gěi Wǒ Kàn Jī Dàn Hé Miàn.", "Mẹ cho tôi xem trứng và mì trước."], [31.805, 37.593, "妈妈还说：“没关系，慢慢做，你会做好的。”", "Mā Ma Hái Shuō: “Méi Guān Xì, Màn Màn Zuò, Nǐ Huì Zuò Hǎo De.”", "Mẹ còn nói: “Không sao, cứ từ từ làm, con sẽ làm tốt.”"], [37.607, 40.539, "先烧水，再放面。", "Xiān Shāo Shuǐ, Zài Fàng Miàn.", "Trước hết đun nước, rồi cho mì vào."], [40.539, 43.687, "我慢慢把面放进水里。", "Wǒ Màn Màn Bǎ Miàn Fàng Jìn Shuǐ Lǐ.", "Tôi từ từ cho mì vào nước."], [43.687, 47.147, "我在旁边看，等了几分钟。", "Wǒ Zài Páng Biān Kàn, Děng Le Jǐ Fēn Zhōng.", "Tôi ở bên cạnh nhìn, đợi mấy phút."], [47.147, 50.511, "我问妈妈：“面什么时候好？”", "Wǒ Wèn Mā Ma: “Miàn Shén Me Shí Hòu Hǎo?”", "Tôi hỏi mẹ: “Khi nào mì được ạ?”"], [50.511, 54.139, "妈妈说：“再等三分钟就好。”", "Mā Ma Shuō: “Zài Děng Sān Fēn Zhōng Jiù Hǎo.”", "Mẹ nói: “Đợi thêm ba phút nữa là được.”"], [54.139, 58.727, "面熟了以后，放一个鸡蛋和一点儿盐。", "Miàn Shú Le Yǐ Hòu, Fàng Yí Gè Jī Dàn Hé Yì Diǎn Ér Yán.", "Mì chín rồi thì cho một quả trứng và một chút muối."], [58.727, 62.547, "我怕盐放得太多，我很紧张。", "Wǒ Pà Yán Fàng Dé Tài Duō, Wǒ Hěn Jǐn Zhāng.", "Tôi sợ cho muối quá nhiều, tôi rất hồi hộp."], [62.547, 66.295, "妈妈说：“少放一点儿就可以了。”", "Mā Ma Shuō: “Shǎo Fàng Yì Diǎn Ér Jiù Kě Yǐ Le.”", "Mẹ nói: “Cho ít một chút là được.”"], [66.295, 70.019, "我听妈妈的话，只放了一点儿盐。", "Wǒ Tīng Mā Ma De Huà, Zhǐ Fàng Le Yì Diǎn Ér Yán.", "Tôi nghe lời mẹ, chỉ cho một chút muối."], [70.027, 73.511, "我吃了一口，真的很好吃。", "Wǒ Chī Le Yì Kǒu, Zhēn De Hěn Hǎo Chī.", "Tôi ăn một miếng, thật sự rất ngon."], [73.511, 76.803, "爸爸坐下来，吃了一口面。", "Bà Ba Zuò Xià Lái, Chī Le Yì Kǒu Miàn.", "Bố ngồi xuống, ăn một miếng mì."], [76.803, 80.335, "爸爸吃了一口，又吃了一口。", "Bà Ba Chī Le Yì Kǒu, Yòu Chī Le Yì Kǒu.", "Bố ăn một miếng, lại ăn thêm một miếng nữa."], [80.361, 84.061, "爸爸说很好吃，我很高兴。", "Bà Ba Shuō Hěn Hǎo Chī, Wǒ Hěn Gāo Xìng.", "Bố nói rất ngon, tôi rất vui."], [84.061, 87.329, "我问爸爸：“你还想吃吗？”", "Wǒ Wèn Bà Ba: “Nǐ Hái Xiǎng Chī Ma?”", "Tôi hỏi bố: “Bố còn muốn ăn nữa không?”"], [87.329, 91.241, "爸爸说：“想，我还想吃一碗。”", "Bà Ba Shuō: “Xiǎng, Wǒ Hái Xiǎng Chī Yì Wǎn.”", "Bố nói: “Muốn, bố muốn ăn thêm một bát nữa.”"], [91.241, 94.221, "第二次我又做了一碗。", "Dì Èr Cì Wǒ Yòu Zuò Le Yì Wǎn.", "Lần thứ hai tôi lại nấu một bát."], [94.221, 98.761, "这次我不紧张了，做得比第一次快。", "Zhè Cì Wǒ Bù Jǐn Zhāng Le, Zuò Dé Bǐ Dì Yī Cì Kuài.", "Lần này tôi không hồi hộp nữa, làm nhanh hơn lần đầu."], [98.761, 102.149, "这次我放了青菜和鸡蛋。", "Zhè Cì Wǒ Fàng Le Qīng Cài Hé Jī Dàn.", "Lần này tôi cho rau và trứng."], [102.174, 105.394, "青菜是妈妈今天买的。", "Qīng Cài Shì Mā Ma Jīn Tiān Mǎi De.", "Rau là mẹ mua hôm nay."], [105.394, 108.422, "妈妈说盐放得正好。", "Mā Ma Shuō Yán Fàng Dé Zhèng Hǎo.", "Mẹ nói muối cho vừa."], [108.422, 111.306, "我问妈妈：“真的吗？”", "Wǒ Wèn Mā Ma: “Zhēn De Ma?”", "Tôi hỏi mẹ: “Thật ạ?”"], [111.307, 115.415, "爸爸也说：“这次比上次还好吃。”", "Bà Ba Yě Shuō: “Zhè Cì Bǐ Shàng Cì Hái Hǎo Chī.”", "Bố cũng nói: “Lần này còn ngon hơn lần trước.”"], [115.415, 119.087, "我觉得自己可以帮忙做晚饭了。", "Wǒ Jué De Zì Jǐ Kě Yǐ Bāng Máng Zuò Wǎn Fàn Le.", "Tôi thấy mình có thể giúp nấu cơm tối."], [119.087, 123.435, "以后妈妈忙的时候，我可以做鸡蛋面。", "Yǐ Hòu Mā Ma Máng De Shí Hòu, Wǒ Kě Yǐ Zuò Jī Dàn Miàn.", "Sau này lúc mẹ bận, tôi có thể nấu mì trứng."], [123.435, 127.639, "妈妈说：“以后星期天你帮我做饭。”", "Mā Ma Shuō: “Yǐ Hòu Xīng Qī Tiān Nǐ Bāng Wǒ Zuò Fàn.”", "Mẹ nói: “Sau này vào Chủ nhật con giúp mẹ nấu cơm.”"], [127.639, 131.747, "我说：“好，我想学很多菜。”", "Wǒ Shuō: “Hǎo, Wǒ Xiǎng Xué Hěn Duō Cài.”", "Tôi nói: “Vâng, con muốn học nhiều món.”"], [131.754, 135.646, "星期天我想学做西红柿鸡蛋。", "Xīng Qī Tiān Wǒ Xiǎng Xué Zuò Xī Hóng Shì Jī Dàn.", "Chủ nhật tôi muốn học làm trứng cà chua."], [135.646, 138.65, "爸爸已经在等着吃了。", "Bà Ba Yǐ Jīng Zài Děng Zhe Chī Le.", "Bố đã đang đợi để ăn."], [138.65, 143.574, "爸爸把面都吃完了，我和妈妈都笑了。", "Bà Ba Bǎ Miàn Dōu Chī Wán Le, Wǒ Hé Mā Ma Dōu Xiào Le.", "Bố ăn hết sạch bát mì, tôi và mẹ đều cười."]]}, "hsk2-09": {"dur": 164.79, "cues": [[7.155, 9.655, "你喜欢看比赛吗？", "Nǐ Xǐ Huan Kàn Bǐ Sài Ma?", "Bạn có thích xem thi đấu không?"], [9.655, 13.547, "星期六下午学校有篮球比赛。", "Xīng Qī Liù Xià Wǔ Xué Xiào Yǒu Lán Qiú Bǐ Sài.", "Chiều thứ Bảy trường có trận bóng rổ."], [13.547, 17.535, "下午两点，我们班的同学都到了。", "Xià Wǔ Liǎng Diǎn, Wǒ Men Bān De Tóng Xué Dōu Dào Le.", "Hai giờ chiều, các bạn lớp tôi đều đã đến."], [17.535, 20.371, "我们班和二班比赛。", "Wǒ Men Bān Hé Èr Bān Bǐ Sài.", "Lớp chúng tôi đấu với lớp hai."], [20.371, 24.239, "二班的同学很高，也跑得很快。", "Èr Bān De Tóng Xué Hěn Gāo, Yě Pǎo Dé Hěn Kuài.", "Các bạn lớp hai rất cao, cũng chạy rất nhanh."], [24.239, 26.975, "老师也来看比赛了。", "Lǎo Shī Yě Lái Kàn Bǐ Sài Le.", "Thầy cũng đến xem trận đấu."], [26.975, 31.131, "老师对我们说：“不要怕，慢慢打。”", "Lǎo Shī Duì Wǒ Men Shuō: “Bú Yào Pà, Màn Màn Dǎ.”", "Thầy nói với chúng tôi: “Đừng sợ, cứ đánh chậm thôi.”"], [31.131, 34.735, "比赛以前我们练习了一个星期。", "Bǐ Sài Yǐ Qián Wǒ Men Liàn Xí Le Yí Gè Xīng Qī.", "Trước trận chúng tôi luyện một tuần."], [34.735, 38.985, "我们每天下午都练习打篮球和跑步。", "Wǒ Men Měi Tiān Xià Wǔ Dōu Liàn Xí Dǎ Lán Qiú Hé Pǎo Bù.", "Mỗi chiều chúng tôi đều luyện chơi bóng rổ và chạy bộ."], [38.985, 42.469, "练习的时候，我有一点儿担心。", "Liàn Xí De Shí Hòu, Wǒ Yǒu Yì Diǎn Ér Dān Xīn.", "Lúc luyện tập, tôi hơi lo lắng."], [42.469, 46.026, "我的工作是把球传给同学。", "Wǒ De Gōng Zuò Shì Bǎ Qiú Chuán Gěi Tóng Xué.", "Việc của tôi là chuyền bóng cho bạn."], [46.026, 49.677, "同学在前面，我把球给了他。", "Tóng Xué Zài Qián Miàn, Wǒ Bǎ Qiú Gěi Le Tā.", "Bạn học ở phía trước, tôi đưa bóng cho bạn ấy."], [49.685, 54.417, "比赛开始以前，同学问我：“你紧张吗？”", "Bǐ Sài Kāi Shǐ Yǐ Qián, Tóng Xué Wèn Wǒ: “Nǐ Jǐn Zhāng Ma?”", "Trước khi trận đấu bắt đầu, bạn học hỏi tôi: “Bạn có hồi hộp không?”"], [54.417, 58.597, "我说：“有一点儿，可是我准备好了。”", "Wǒ Shuō: “Yǒu Yì Diǎn Ér, Kě Shì Wǒ Zhǔn Bèi Hǎo Le.”", "Tôi nói: “Hơi một chút, nhưng tôi đã sẵn sàng rồi.”"], [58.618, 64.43, "开始的时候，二班进了三个球，我们一个也没进。", "Kāi Shǐ De Shí Hòu, Èr Bān Jìn Le Sān Gè Qiú, Wǒ Men Yí Gè Yě Méi Jìn.", "Lúc đầu, lớp hai ghi được ba bàn, còn chúng tôi chưa ghi được bàn nào."], [64.43, 68.659, "我把球传给同学，可是球没进去。", "Wǒ Bǎ Qiú Chuán Gěi Tóng Xué, Kě Shì Qiú Méi Jìn Qù.", "Tôi chuyền bóng cho bạn học, nhưng bóng không vào."], [68.659, 72.258, "我们班的同学都有一点儿不高兴。", "Wǒ Men Bān De Tóng Xué Dōu Yǒu Yì Diǎn Ér Bù Gāo Xìng.", "Các bạn lớp tôi đều hơi không vui."], [72.258, 77.111, "老师在旁边说：“没关系，还有时间！”", "Lǎo Shī Zài Páng Biān Shuō: “Méi Guān Xì, Hái Yǒu Shí Jiān!”", "Thầy ở bên cạnh nói: “Không sao, vẫn còn thời gian!”"], [77.111, 80.954, "听了老师的话，我们跑得更快了。", "Tīng Le Lǎo Shī De Huà, Wǒ Men Pǎo Dé Gèng Kuài Le.", "Nghe thầy nói vậy, chúng tôi chạy nhanh hơn."], [80.954, 85.228, "我把球传给同学，同学进了一个球。", "Wǒ Bǎ Qiú Chuán Gěi Tóng Xué, Tóng Xué Jìn Le Yí Gè Qiú.", "Tôi chuyền bóng cho bạn học, bạn ấy ghi được một bàn."], [85.228, 90.656, "这是我们班的第一个球，大家都高兴得站了起来。", "Zhè Shì Wǒ Men Bān De Dì Yí Gè Qiú, Dà Jiā Dōu Gāo Xìng De Zhàn Le Qǐ Lái.", "Đây là bàn đầu tiên của lớp tôi, mọi người đều vui mừng đứng cả dậy."], [90.656, 94.044, "大家都一起说：“太好了！”", "Dà Jiā Dōu Yì Qǐ Shuō: “Tài Hǎo Le!”", "Mọi người cùng nói: “Tuyệt quá!”"], [94.062, 97.834, "最后五分钟，我们进了很多球。", "Zuì Hòu Wǔ Fēn Zhōng, Wǒ Men Jìn Le Hěn Duō Qiú.", "Năm phút cuối, chúng tôi ghi rất nhiều bàn."], [97.834, 102.254, "看到比分一样的时候，大家都很紧张。", "Kàn Dào Bǐ Fēn Yí Yàng De Shí Hòu, Dà Jiā Dōu Hěn Jǐn Zhāng.", "Khi tỉ số hòa, mọi người đều rất hồi hộp."], [102.254, 107.227, "二班也想再进一个球，他们跑得也很快。", "Èr Bān Yě Xiǎng Zài Jìn Yí Gè Qiú, Tā Men Pǎo Dé Yě Hěn Kuài.", "Lớp hai cũng muốn ghi thêm một bàn, họ chạy cũng rất nhanh."], [107.228, 110.88, "我看了看时间，只有一分钟了。", "Wǒ Kàn Le Kàn Shí Jiān, Zhǐ Yǒu Yì Fēn Zhōng Le.", "Tôi nhìn thời gian, chỉ còn một phút."], [110.88, 114.508, "同学对我说：“快把球给我！”", "Tóng Xué Duì Wǒ Shuō: “Kuài Bǎ Qiú Gěi Wǒ!”", "Bạn học nói với tôi: “Nhanh đưa bóng cho tớ!”"], [114.508, 118.328, "我很快把球传给前面的同学。", "Wǒ Hěn Kuài Bǎ Qiú Chuán Gěi Qián Miàn De Tóng Xué.", "Tôi nhanh chóng chuyền bóng cho bạn học ở phía trước."], [118.328, 121.668, "最后一分钟，我们进球了。", "Zuì Hòu Yì Fēn Zhōng, Wǒ Men Jìn Qiú Le.", "Phút cuối chúng tôi ghi bàn."], [121.668, 126.108, "比赛结束，我们赢了，大家都很兴奋。", "Bǐ Sài Jié Shù, Wǒ Men Yíng Le, Dà Jiā Dōu Hěn Xīng Fèn.", "Hết trận chúng tôi thắng, mọi người đều rất phấn khích."], [126.108, 129.976, "老师走过来，说我们打得真好。", "Lǎo Shī Zǒu Guò Lái, Shuō Wǒ Men Dǎ Dé Zhēn Hǎo.", "Thầy đi lại, nói chúng tôi chơi thật tốt."], [129.976, 133.82, "二班的同学也过来和我们说话。", "Èr Bān De Tóng Xué Yě Guò Lái Hé Wǒ Men Shuō Huà.", "Các bạn lớp hai cũng đến nói chuyện với chúng tôi."], [133.82, 139.104, "他们说：“你们打得很好，下次我们再比赛。”", "Tā Men Shuō: “Nǐ Men Dǎ Dé Hěn Hǎo, Xià Cì Wǒ Men Zài Bǐ Sài.”", "Họ nói: “Các bạn chơi rất tốt, lần sau chúng ta lại thi đấu.”"], [139.108, 142.329, "回去的路上我们还在说话。", "Huí Qù De Lù Shang Wǒ Men Hái Zài Shuō Huà.", "Trên đường về chúng tôi vẫn còn nói về trận đó."], [142.329, 146.245, "大家都在说最后一分钟的那个球。", "Dà Jiā Dōu Zài Shuō Zuì Hòu Yì Fēn Zhōng De Nà Gè Qiú.", "Mọi người đều đang nói về bàn thắng ở phút cuối đó."], [146.245, 151.048, "大家说：“一起练习，一起比赛，真快乐！”", "Dà Jiā Shuō: “Yì Qǐ Liàn Xí, Yì Qǐ Bǐ Sài, Zhēn Kuài Lè!”", "Mọi người nói: “Cùng luyện tập, cùng thi đấu, thật vui!”"], [151.048, 154.649, "今天的比赛，我会一直记得。", "Jīn Tiān De Bǐ Sài, Wǒ Huì Yì Zhí Jì De.", "Trận đấu hôm nay, tôi sẽ luôn nhớ."]]}, "hsk2-10": {"dur": 167.6, "cues": [[7.206, 10.186, "你去机场接过人吗？", "Nǐ Qù Jī Chǎng Jiē Guò Rén Ma?", "Bạn đã từng ra sân bay đón người chưa?"], [10.186, 14.146, "哥哥很久没回家了，我很想他。", "Gē Ge Hěn Jiǔ Méi Huí Jiā Le, Wǒ Hěn Xiǎng Tā.", "Anh trai lâu rồi chưa về nhà, tôi rất nhớ anh."], [14.146, 17.797, "今天上午我去机场接哥哥。", "Jīn Tiān Shàng Wǔ Wǒ Qù Jī Chǎng Jiē Gē Ge.", "Sáng nay tôi ra sân bay đón anh trai."], [17.797, 20.681, "他从广州来北京。", "Tā Cóng Guǎng Zhōu Lái Běi Jīng.", "Anh ấy từ Quảng Châu đến Bắc Kinh."], [20.681, 24.934, "妈妈说：“哥哥上午十点到北京。”", "Mā Ma Shuō: “Gē Ge Shàng Wǔ Shí Diǎn Dào Běi Jīng.”", "Mẹ nói: “Anh con mười giờ sáng đến Bắc Kinh.”"], [24.945, 28.405, "我问妈妈：“我要几点出门？”", "Wǒ Wèn Mā Ma: “Wǒ Yào Jǐ Diǎn Chū Mén?”", "Tôi hỏi mẹ: “Con phải ra khỏi nhà lúc mấy giờ?”"], [28.405, 32.514, "妈妈说：“早一点儿去，不要迟到。”", "Mā Ma Shuō: “Zǎo Yì Diǎn Ér Qù, Bú Yào Chí Dào.”", "Mẹ nói: “Đi sớm một chút, đừng đến muộn.”"], [32.514, 35.541, "我早上七点就出门了。", "Wǒ Zǎo Shàng Qī Diǎn Jiù Chū Mén Le.", "Tôi ra khỏi nhà từ bảy giờ sáng."], [35.546, 40.086, "出门的时候，天气很好，我很高兴。", "Chū Mén De Shí Hòu, Tiān Qì Hěn Hǎo, Wǒ Hěn Gāo Xìng.", "Lúc ra khỏi nhà, thời tiết rất đẹp, tôi rất vui."], [40.086, 43.761, "我走在路上，一直想着哥哥。", "Wǒ Zǒu Zài Lù Shàng, Yì Zhí Xiǎng Zhe Gē Ge.", "Đi trên đường, tôi cứ nghĩ đến anh trai."], [43.761, 46.355, "路上有一点儿堵车。", "Lù Shang Yǒu Yì Diǎn Ér Dǔ Chē.", "Trên đường hơi tắc."], [46.355, 50.464, "车很多，走得很慢，我很担心。", "Chē Hěn Duō, Zǒu Dé Hěn Màn, Wǒ Hěn Dān Xīn.", "Xe rất đông, đi rất chậm, tôi rất lo."], [50.464, 54.188, "我怕迟到，就提前坐地铁。", "Wǒ Pà Chí Dào, Jiù Tí Qián Zuò Dì Tiě.", "Tôi sợ muộn nên đi tàu điện sớm."], [54.188, 58.272, "地铁很快，十分钟就到机场了。", "Dì Tiě Hěn Kuài, Shí Fēn Zhōng Jiù Dào Jī Chǎng Le.", "Tàu điện rất nhanh, mười phút là đến sân bay."], [58.288, 61.989, "我到机场的时候，才八点半。", "Wǒ Dào Jī Chǎng De Shí Hòu, Cái Bā Diǎn Bàn.", "Lúc tôi đến sân bay mới tám giờ rưỡi."], [61.989, 65.784, "我看了看手机，飞机还没到。", "Wǒ Kàn Le Kàn Shǒu Jī, Fēi Jī Hái Méi Dào.", "Tôi nhìn điện thoại, máy bay vẫn chưa đến."], [65.784, 69.508, "我去买了水，坐下来慢慢等。", "Wǒ Qù Mǎi Le Shuǐ, Zuò Xià Lái Màn Màn Děng.", "Tôi đi mua nước, ngồi xuống từ từ đợi."], [69.522, 72.43, "飞机晚了二十分钟。", "Fēi Jī Wǎn Le Èr Shí Fēn Zhōng.", "Máy bay muộn hai mươi phút."], [72.43, 76.058, "我有一点儿担心，怕哥哥有事。", "Wǒ Yǒu Yì Diǎn Ér Dān Xīn, Pà Gē Ge Yǒu Shì.", "Tôi hơi lo, sợ anh có chuyện gì."], [76.058, 80.862, "可是我想，他在飞机上，不能打电话。", "Kě Shì Wǒ Xiǎng, Tā Zài Fēi Jī Shàng, Bù Néng Dǎ Diàn Huà.", "Nhưng tôi nghĩ, anh đang trên máy bay, không gọi điện được."], [80.862, 84.826, "我告诉自己，再等二十分钟就好。", "Wǒ Gào Sù Zì Jǐ, Zài Děng Èr Shí Fēn Zhōng Jiù Hǎo.", "Tôi tự nhủ, đợi thêm hai mươi phút nữa là được."], [84.826, 89.511, "我在出口等他，手里拿着他的名字。", "Wǒ Zài Chū Kǒu Děng Tā, Shǒu Lǐ Ná Zhe Tā De Míng Zì.", "Tôi đợi anh ở cửa ra, tay cầm tên của anh."], [89.511, 93.883, "出口的人很多，我把名字拿得很高。", "Chū Kǒu De Rén Hěn Duō, Wǒ Bǎ Míng Zì Ná Dé Hěn Gāo.", "Ở cửa ra có rất nhiều người, tôi cầm tên anh giơ thật cao."], [93.895, 97.427, "我看着出口，等哥哥出来。", "Wǒ Kàn Zhe Chū Kǒu, Děng Gē Ge Chū Lái.", "Tôi nhìn cửa ra, đợi anh đi ra."], [97.427, 101.103, "哥哥一下飞机就给我打电话。", "Gē Ge Yí Xià Fēi Jī Jiù Gěi Wǒ Dǎ Diàn Huà.", "Anh vừa xuống máy bay là gọi cho tôi."], [101.103, 106.576, "哥哥在电话里说：“我到了，我去出口找你。”", "Gē Ge Zài Diàn Huà Lǐ Shuō: “Wǒ Dào Le, Wǒ Qù Chū Kǒu Zhǎo Nǐ.”", "Anh nói trong điện thoại: “Anh đến rồi, anh ra cửa ra tìm em.”"], [106.576, 111.644, "我说：“我就在出口，手里有你的名字。”", "Wǒ Shuō: “Wǒ Jiù Zài Chū Kǒu, Shǒu Lǐ Yǒu Nǐ De Míng Zì.”", "Tôi nói: “Em ở ngay cửa ra, tay cầm tên của anh.”"], [111.644, 116.519, "过了一会儿，哥哥出来了，我看见他了。", "Guò Le Yí Huì Er, Gē Ge Chū Lái Le, Wǒ Kàn Jiàn Tā Le.", "Một lúc sau, anh đi ra, tôi nhìn thấy anh."], [116.519, 120.796, "哥哥看见我，很高兴，跑了过来。", "Gē Ge Kàn Jiàn Wǒ, Hěn Gāo Xìng, Pǎo Le Guò Lái.", "Anh nhìn thấy tôi, rất vui, chạy lại."], [120.808, 124.341, "哥哥笑着说：“我也很想你。”", "Gē Ge Xiào Zhe Shuō: “Wǒ Yě Hěn Xiǎng Nǐ.”", "Anh cười nói: “Anh cũng rất nhớ em.”"], [124.341, 128.833, "见到哥哥以后，我们一起坐地铁回家。", "Jiàn Dào Gē Ge Yǐ Hòu, Wǒ Men Yì Qǐ Zuò Dì Tiě Huí Jiā.", "Gặp anh rồi, chúng tôi cùng đi tàu điện về nhà."], [128.843, 133.382, "在地铁上，哥哥告诉我广州很好玩儿。", "Zài Dì Tiě Shàng, Gē Ge Gào Sù Wǒ Guǎng Zhōu Hěn Hǎo Wánr.", "Trên tàu điện, anh nói với tôi Quảng Châu rất vui."], [133.382, 137.659, "回到家，妈妈看见哥哥，很高兴。", "Huí Dào Jiā, Mā Ma Kàn Jiàn Gē Ge, Hěn Gāo Xìng.", "Về đến nhà, mẹ nhìn thấy anh, rất vui."], [137.675, 140.944, "他带了很多广州的水果。", "Tā Dài Le Hěn Duō Guǎng Zhōu De Shuǐ Guǒ.", "Anh mang rất nhiều hoa quả Quảng Châu."], [140.944, 144.619, "晚上我们把水果分给大家吃。", "Wǎn Shàng Wǒ Men Bǎ Shuǐ Guǒ Fēn Gěi Dà Jiā Chī.", "Tối chúng tôi chia hoa quả cho mọi người ăn."], [144.619, 152.088, "哥哥笑着说：广州的水果很甜，在北京吃不到，你们多吃一点儿。", "Gē Ge Xiào Zhe Shuō: Guǎng Zhōu De Shuǐ Guǒ Hěn Tián, Zài Běi Jīng Chī Bú Dào, Nǐ Men Duō Chī Yì Diǎn Ér.", "Anh cười nói: Hoa quả Quảng Châu rất ngọt, ở Bắc Kinh không ăn được vị này, mọi người ăn nhiều một chút nhé."], [152.088, 157.395, "爸爸妈妈都说水果很好吃，我们都很高兴。", "Bà Ba Mā Ma Dōu Shuō Shuǐ Guǒ Hěn Hǎo Chī, Wǒ Men Dōu Hěn Gāo Xìng.", "Bố mẹ đều nói hoa quả rất ngon, chúng tôi đều rất vui."]]}, "hsk2-11": {"dur": 149.77, "cues": [[6.887, 10.059, "你喜欢看中文故事书吗？", "Nǐ Xǐ Huān Kàn Zhōng Wén Gù Shì Shū Ma?", "Bạn có thích đọc truyện tiếng Trung không?"], [10.059, 14.575, "我很喜欢，所以星期六常常去图书馆。", "Wǒ Hěn Xǐ Huān, Suǒ Yǐ Xīng Qī Liù Cháng Cháng Qù Tú Shū Guǎn.", "Tôi rất thích, nên thứ Bảy thường đến thư viện."], [14.575, 19.043, "星期六上午，我去学校图书馆借书。", "Xīng Qī Liù Shàng Wǔ, Wǒ Qù Xué Xiào Tú Shū Guǎn Jiè Shū.", "Sáng thứ Bảy, tôi đến thư viện trường để mượn sách."], [19.053, 24.001, "图书馆里人很多，我先找一个位子坐下。", "Tú Shū Guǎn Lǐ Rén Hěn Duō, Wǒ Xiān Zhǎo Yí Gè Wèi Zi Zuò Xià.", "Trong thư viện có nhiều người, tôi tìm một chỗ ngồi xuống trước."], [24.001, 29.861, "我想借一本中文故事书，可是找了很久也没找到。", "Wǒ Xiǎng Jiè Yì Běn Zhōng Wén Gù Shì Shū, Kě Shì Zhǎo Le Hěn Jiǔ Yě Méi Zhǎo Dào.", "Tôi muốn mượn một cuốn truyện tiếng Trung, nhưng tìm mãi vẫn không thấy."], [29.861, 34.401, "我找了一本，又找了一本，还是没有。", "Wǒ Zhǎo Le Yì Běn, Yòu Zhǎo Le Yì Běn, Hái Shì Méi Yǒu.", "Tôi tìm cuốn này rồi cuốn khác, vẫn không thấy."], [34.42, 38.312, "我有点儿担心，今天借不到书了。", "Wǒ Yǒu Diǎn Ér Dān Xīn, Jīn Tiān Jiè Bú Dào Shū Le.", "Tôi hơi lo, hôm nay không mượn được sách rồi."], [38.32, 41.828, "一个工作人员问我要找什么书。", "Yí Gè Gōng Zuò Rén Yuán Wèn Wǒ Yào Zhǎo Shén Me Shū.", "Một nhân viên hỏi tôi muốn tìm cuốn sách gì."], [41.828, 46.464, "我告诉她，我想看一本中文故事书。", "Wǒ Gào Sù Tā, Wǒ Xiǎng Kàn Yì Běn Zhōng Wén Gù Shì Shū.", "Tôi nói với cô ấy là tôi muốn đọc một cuốn truyện tiếng Trung."], [46.464, 51.412, "我说了书的名字，她很快就帮我找到了。", "Wǒ Shuō Le Shū De Míng Zì, Tā Hěn Kuài Jiù Bāng Wǒ Zhǎo Dào Le.", "Tôi nói tên sách, cô ấy nhanh chóng tìm giúp tôi."], [51.42, 54.856, "她问我：“你看过这本书吗？”", "Tā Wèn Wǒ: “Nǐ Kàn Guò Zhè Běn Shū Ma?”", "Cô ấy hỏi tôi: “Bạn đã đọc cuốn này chưa?”"], [54.856, 58.436, "我说：“没有，我第一次看。”", "Wǒ Shuō: “Méi Yǒu, Wǒ Dì Yī Cì Kàn.”", "Tôi nói: “Chưa, đây là lần đầu tôi đọc.”"], [58.436, 63.312, "她说：“这本书很好看，你会喜欢的。”", "Tā Shuō: “Zhè Běn Shū Hěn Hǎo Kàn, Nǐ Huì Xǐ Huān De.”", "Cô ấy nói: “Cuốn này rất hay, bạn sẽ thích đấy.”"], [63.32, 67.212, "我很高兴，对她说：“谢谢你！”", "Wǒ Hěn Gāo Xìng, Duì Tā Shuō: “Xiè Xie Nǐ!”", "Tôi rất vui, nói với cô ấy: “Cảm ơn cô!”"], [67.212, 71.1, "借书以前，我给她看了学生证。", "Jiè Shū Yǐ Qián, Wǒ Gěi Tā Kàn Le Xué Shēng Zhèng.", "Trước khi mượn, tôi đưa thẻ học sinh cho cô ấy xem."], [71.1, 75.544, "她看了看学生证，又问了我的名字。", "Tā Kàn Le Kàn Xué Shēng Zhèng, Yòu Wèn Le Wǒ De Míng Zì.", "Cô ấy xem thẻ học sinh, rồi hỏi tên tôi."], [75.544, 79.172, "她说一本书可以借两个星期。", "Tā Shuō Yì Běn Shū Kě Yǐ Jiè Liǎng Gè Xīng Qī.", "Cô ấy nói một cuốn sách có thể mượn hai tuần."], [79.172, 83.352, "她还告诉我，看完以后要按时还书。", "Tā Hái Gào Sù Wǒ, Kàn Wán Yǐ Hòu Yào Àn Shí Huán Shū.", "Cô ấy còn dặn tôi đọc xong phải trả sách đúng hạn."], [83.367, 87.379, "我说：“好，我知道了，谢谢。”", "Wǒ Shuō: “Hǎo, Wǒ Zhī Dào Le, Xiè Xie.”", "Tôi nói: “Vâng, em biết rồi, cảm ơn cô.”"], [87.379, 91.487, "然后我拿着书，去找靠窗的位子。", "Rán Hòu Wǒ Ná Zhe Shū, Qù Zhǎo Kào Chuāng De Wèi Zi.", "Sau đó tôi cầm sách đi tìm chỗ cạnh cửa sổ."], [91.5, 95.608, "我坐在靠窗的位子，看了一个下午。", "Wǒ Zuò Zài Kào Chuāng De Wèi Zǐ, Kàn Le Yí Gè Xià Wǔ.", "Tôi ngồi ở chỗ cạnh cửa sổ và đọc cả buổi chiều."], [95.608, 100.388, "窗户外面天气很好，我看书看得很认真。", "Chuāng Hù Wài Miàn Tiān Qì Hěn Hǎo, Wǒ Kàn Shū Kàn De Hěn Rèn Zhēn.", "Ngoài cửa sổ trời rất đẹp, tôi đọc sách rất chăm chú."], [100.388, 105.264, "故事很好看，我看了很久也不想回家。", "Gù Shì Hěn Hǎo Kàn, Wǒ Kàn Le Hěn Jiǔ Yě Bù Xiǎng Huí Jiā.", "Truyện rất hay, tôi đọc rất lâu mà vẫn không muốn về nhà."], [105.264, 110.28, "故事太好看了，我一直看，不想停下来。", "Gù Shì Tài Hǎo Kàn Le, Wǒ Yì Zhí Kàn, Bù Xiǎng Tíng Xià Lái.", "Truyện hay quá, tôi cứ đọc mãi, không muốn dừng lại."], [110.28, 114.22, "后来天晚了，我才拿着书回家。", "Hòu Lái Tiān Wǎn Le, Wǒ Cái Ná Zhe Shū Huí Jiā.", "Sau đó trời tối, tôi mới cầm sách về nhà."], [114.22, 119.26, "在家我每天都看一点儿，两个星期看完了。", "Zài Jiā Wǒ Měi Tiān Dōu Kàn Yì Diǎn Ér, Liǎng Gè Xīng Qī Kàn Wán Le.", "Ở nhà mỗi ngày tôi đọc một chút, hai tuần là đọc xong."], [119.26, 124.712, "两个星期以后，我按时把书还给了工作人员。", "Liǎng Gè Xīng Qī Yǐ Hòu, Wǒ Àn Shí Bǎ Shū Hái Gěi Le Gōng Zuò Rén Yuán.", "Hai tuần sau, tôi trả sách đúng hạn cho nhân viên."], [124.712, 128.359, "工作人员说我是常来的学生。", "Gōng Zuò Rén Yuán Shuō Wǒ Shì Cháng Lái De Xué Shēng.", "Nhân viên nói tôi là học sinh hay đến thư viện."], [128.359, 131.748, "她问我：“这本书好看吗？”", "Tā Wèn Wǒ: “Zhè Běn Shū Hǎo Kàn Ma?”", "Cô ấy hỏi tôi: “Cuốn này có hay không?”"], [131.748, 135.448, "我说：“很好看，我很喜欢。”", "Wǒ Shuō: “Hěn Hǎo Kàn, Wǒ Hěn Xǐ Huān.”", "Tôi nói: “Rất hay, em rất thích.”"], [135.448, 139.58, "我想下个星期再借一本新故事书。", "Wǒ Xiǎng Xià Gè Xīng Qī Zài Jiè Yì Běn Xīn Gù Shì Shū.", "Tuần sau tôi muốn mượn thêm một cuốn truyện mới."]]}, "hsk2-12": {"dur": 137.27, "cues": [[7.405, 11.369, "你出门的时候，会先看天气吗？", "Nǐ Chū Mén De Shí Hòu, Huì Xiān Kàn Tiān Qì Ma?", "Khi ra ngoài, bạn có xem thời tiết trước không?"], [11.369, 15.909, "我以前不会，出门只想快一点儿出去玩儿。", "Wǒ Yǐ Qián Bú Huì, Chū Mén Zhǐ Xiǎng Kuài Yì Diǎn Ér Chū Qù Wán Ér.", "Trước đây tôi không biết, ra ngoài chỉ muốn nhanh ra chơi."], [15.909, 19.801, "早上天气很好，我想出去玩儿。", "Zǎo Shàng Tiān Qì Hěn Hǎo, Wǒ Xiǎng Chū Qù Wán Ér.", "Sáng thời tiết đẹp, tôi muốn ra ngoài chơi."], [19.805, 23.529, "妈妈问我：“你今天去哪儿玩儿？”", "Mā Ma Wèn Wǒ: “Nǐ Jīn Tiān Qù Nǎ Ér Wán Ér?”", "Mẹ hỏi tôi: “Hôm nay con đi đâu chơi?”"], [23.529, 27.805, "我说：“我去公园，和朋友一起玩儿。”", "Wǒ Shuō: “Wǒ Qù Gōng Yuán, Hé Péng Yǒu Yì Qǐ Wán Ér.”", "Tôi nói: “Con đi công viên, chơi cùng bạn.”"], [27.805, 31.937, "妈妈说：“好，玩儿的时候慢一点儿。”", "Mā Ma Shuō: “Hǎo, Wán Ér De Shí Hòu Màn Yì Diǎn Ér.”", "Mẹ nói: “Ừ, lúc chơi chậm rãi một chút nhé.”"], [31.939, 36.503, "上午天气很好，我和朋友玩儿得很高兴。", "Shàng Wǔ Tiān Qì Hěn Hǎo, Wǒ Hé Péng Yǒu Wán Ér De Hěn Gāo Xìng.", "Buổi sáng trời đẹp, tôi và bạn chơi rất vui."], [36.503, 40.707, "中午忽然刮风，下午又下雨了。", "Zhōng Wǔ Hū Rán Guā Fēng, Xià Wǔ Yòu Xià Yǔ Le.", "Trưa đột nhiên nổi gió, chiều lại mưa."], [40.707, 43.687, "我觉得雨会下得很大。", "Wǒ Jué De Yǔ Huì Xià De Hěn Dà.", "Tôi thấy mưa sẽ rất lớn."], [43.705, 47.573, "我想马上回家，可是已经晚了。", "Wǒ Xiǎng Mǎ Shàng Huí Jiā, Kě Shì Yǐ Jīng Wǎn Le.", "Tôi muốn về nhà ngay, nhưng đã muộn rồi."], [47.573, 51.105, "我没带雨伞，衣服都湿了。", "Wǒ Méi Dài Yǔ Sǎn, Yī Fu Dōu Shī Le.", "Tôi không mang ô, quần áo ướt hết."], [51.105, 54.781, "雨很大，我走路的时候很慢。", "Yǔ Hěn Dà, Wǒ Zǒu Lù De Shí Hòu Hěn Màn.", "Mưa rất lớn, lúc đi bộ tôi đi rất chậm."], [54.805, 59.105, "我很冷，也有点儿担心妈妈会说我。", "Wǒ Hěn Lěng, Yě Yǒu Diǎn Ér Dān Xīn Mā Ma Huì Shuō Wǒ.", "Tôi rất lạnh, cũng hơi lo mẹ sẽ mắng."], [59.105, 62.493, "回到家，我马上换衣服。", "Huí Dào Jiā, Wǒ Mǎ Shàng Huàn Yī Fu.", "Về đến nhà tôi đổi quần áo ngay."], [62.493, 66.337, "妈妈给我热水，让我先坐下。", "Mā Ma Gěi Wǒ Rè Shuǐ, Ràng Wǒ Xiān Zuò Xià.", "Mẹ đưa tôi nước nóng, bảo tôi ngồi xuống trước."], [66.339, 70.663, "妈妈说，出门以前要看天气预报。", "Mā Ma Shuō, Chū Mén Yǐ Qián Yào Kàn Tiān Qì Yù Bào.", "Mẹ nói trước khi ra ngoài phải xem dự báo thời tiết."], [70.663, 74.435, "妈妈问我：“你为什么不带雨伞？”", "Mā Ma Wèn Wǒ: “Nǐ Wèi Shén Me Bú Dài Yǔ Sǎn?”", "Mẹ hỏi tôi: “Sao con không mang ô?”"], [74.435, 79.263, "我说：“早上天气好，我觉得不会下雨。”", "Wǒ Shuō: “Zǎo Shàng Tiān Qì Hǎo, Wǒ Jué De Bú Huì Xià Yǔ.”", "Tôi nói: “Sáng trời đẹp, con nghĩ sẽ không mưa.”"], [79.272, 84.508, "我说：“好，我以后出门会先看天气。”", "Wǒ Shuō: “Hǎo, Wǒ Yǐ Hòu Chū Mén Huì Xiān Kàn Tiān Qì.”", "Tôi nói: “Vâng, sau này ra ngoài con sẽ xem thời tiết trước.”"], [84.512, 87.636, "第二天我买了一把雨伞。", "Dì Èr Tiān Wǒ Mǎi Le Yì Bǎ Yǔ Sǎn.", "Hôm sau tôi mua một cái ô."], [87.636, 91.864, "买伞的时候，妈妈和我一起去商店。", "Mǎi Sǎn De Shí Hòu, Mā Ma Hé Wǒ Yì Qǐ Qù Shāng Diàn.", "Lúc mua ô, mẹ đi cửa hàng cùng tôi."], [91.864, 96.572, "我看了很多把伞，最后买了这一把。", "Wǒ Kàn Le Hěn Duō Bǎ Sǎn, Zuì Hòu Mǎi Le Zhè Yì Bǎ.", "Tôi xem nhiều cái ô, cuối cùng mua cái này."], [96.579, 99.775, "伞不大，可是很好用。", "Sǎn Bú Dà, Kě Shì Hěn Hǎo Yòng.", "Ô không lớn nhưng rất tiện."], [99.775, 104.699, "我选了一把红色的伞，妈妈说很好看。", "Wǒ Xuǎn Le Yí Bǎ Hóng Sè De Sǎn, Mā Ma Shuō Hěn Hǎo Kàn.", "Tôi chọn một chiếc ô màu đỏ, mẹ nói rất đẹp."], [104.712, 107.98, "现在出门我先看天气。", "Xiàn Zài Chū Mén Wǒ Xiān Kàn Tiān Qì.", "Bây giờ trước khi ra ngoài tôi xem thời tiết trước."], [107.98, 112.52, "每天早上，我先看手机上的天气预报。", "Měi Tiān Zǎo Shàng, Wǒ Xiān Kàn Shǒu Jī Shàng De Tiān Qì Yù Bào.", "Mỗi sáng, tôi xem dự báo thời tiết trên điện thoại trước."], [112.52, 115.932, "如果要下雨，我就带伞。", "Rú Guǒ Yào Xià Yǔ, Wǒ Jiù Dài Sǎn.", "Nếu sắp mưa, tôi mang ô."], [115.945, 120.317, "如果天气很好，我就开心地出去玩儿。", "Rú Guǒ Tiān Qì Hěn Hǎo, Wǒ Jiù Kāi Xīn De Chū Qù Wán Ér.", "Nếu trời đẹp, tôi vui vẻ ra ngoài chơi."], [120.317, 123.729, "妈妈说这样才是好习惯。", "Mā Ma Shuō Zhè Yàng Cái Shì Hǎo Xí Guàn.", "Mẹ nói như vậy mới là thói quen tốt."], [123.729, 127.021, "我再也不想把衣服弄湿了。", "Wǒ Zài Yě Bù Xiǎng Bǎ Yī Fu Nòng Shī Le.", "Tôi không muốn làm ướt quần áo nữa."]]}, "hsk2-13": {"dur": 138.71, "cues": [[6.199, 10.307, "你第一次去新学校的时候，紧张吗？", "Nǐ Dì Yī Cì Qù Xīn Xué Xiào De Shí Hòu, Jǐn Zhāng Ma?", "Lần đầu đến trường mới, bạn có căng thẳng không?"], [10.307, 15.735, "我想，小雨第一天来我们班，也有点儿紧张。", "Wǒ Xiǎng, Xiǎo Yǔ Dì Yī Tiān Lái Wǒ Men Bān, Yě Yǒu Diǎn Ér Jǐn Zhāng.", "Tôi nghĩ ngày đầu đến lớp chúng tôi, Tiểu Vũ cũng hơi căng thẳng."], [15.735, 19.239, "这个月我们班来了一个新同学。", "Zhè Ge Yuè Wǒ Men Bān Lái Le Yí Gè Xīn Tóng Xué.", "Tháng này lớp có một bạn mới."], [19.239, 22.435, "她叫小雨，从南京来。", "Tā Jiào Xiǎo Yǔ, Cóng Nán Jīng Lái.", "Bạn ấy tên Tiểu Vũ, đến từ Nam Kinh."], [22.435, 26.855, "老师告诉我们，小雨是我们的新同学。", "Lǎo Shī Gào Sù Wǒ Men, Xiǎo Yǔ Shì Wǒ Men De Xīn Tóng Xué.", "Thầy nói với chúng tôi Tiểu Vũ là bạn mới của lớp."], [26.855, 30.699, "老师让我带她去看看我们的学校。", "Lǎo Shī Ràng Wǒ Dài Tā Qù Kàn Kan Wǒ Men De Xué Xiào.", "Thầy bảo tôi dẫn bạn đi xem trường của chúng tôi."], [30.706, 33.494, "第一天她不太说话。", "Dì Yī Tiān Tā Bú Tài Shuō Huà.", "Ngày đầu bạn ấy không nói nhiều."], [33.494, 37.362, "她说话很小声，也不太看大家。", "Tā Shuō Huà Hěn Xiǎo Shēng, Yě Bú Tài Kàn Dà Jiā.", "Bạn ấy nói rất nhỏ, cũng không hay nhìn mọi người."], [37.362, 41.062, "我问她：“你想坐在我旁边吗？”", "Wǒ Wèn Tā: “Nǐ Xiǎng Zuò Zài Wǒ Páng Biān Ma?”", "Tôi hỏi bạn: “Bạn muốn ngồi cạnh mình không?”"], [41.073, 44.317, "她说：“想，谢谢你。”", "Tā Shuō: “Xiǎng, Xiè Xie Nǐ.”", "Bạn ấy nói: “Muốn, cảm ơn bạn.”"], [44.317, 49.001, "我带她去教室，也告诉她食堂在哪儿。", "Wǒ Dài Tā Qù Jiào Shì, Yě Gào Sù Tā Shí Táng Zài Nǎ Ér.", "Tôi đưa bạn đến lớp và chỉ nhà ăn ở đâu."], [49.001, 53.349, "我还告诉她，图书馆就在教室旁边。", "Wǒ Hái Gào Sù Tā, Tú Shū Guǎn Jiù Zài Jiào Shì Páng Biān.", "Tôi còn nói thư viện ngay cạnh lớp học."], [53.373, 57.649, "她问我：“下课以后可以去图书馆吗？”", "Tā Wèn Wǒ: “Xià Kè Yǐ Hòu Kě Yǐ Qù Tú Shū Guǎn Ma?”", "Bạn ấy hỏi tôi: “Tan học có thể đến thư viện không?”"], [57.649, 61.973, "我说：“可以，我带你去看一看。”", "Wǒ Shuō: “Kě Yǐ, Wǒ Dài Nǐ Qù Kàn Yí Kàn.”", "Tôi nói: “Được, mình dẫn bạn đi xem.”"], [61.973, 65.025, "中午我带小雨去食堂。", "Zhōng Wǔ Wǒ Dài Xiǎo Yǔ Qù Shí Táng.", "Trưa tôi đưa Tiểu Vũ đến căn tin."], [65.039, 67.947, "她不知道哪个菜好吃。", "Tā Bù Zhī Dào Nǎ Gè Cài Hǎo Chī.", "Bạn ấy không biết món nào ngon."], [67.947, 71.503, "她问我：“你常常吃什么菜？”", "Tā Wèn Wǒ: “Nǐ Cháng Cháng Chī Shén Me Cài?”", "Bạn ấy hỏi tôi: “Bạn thường ăn món gì?”"], [71.503, 76.279, "我说：“我常常吃面条，也吃米饭。”", "Wǒ Shuō: “Wǒ Cháng Cháng Chī Miàn Tiáo, Yě Chī Mǐ Fàn.”", "Tôi nói: “Mình thường ăn mì, cũng ăn cơm.”"], [76.279, 79.403, "她说南京的菜比较甜。", "Tā Shuō Nán Jīng De Cài Bǐ Jiào Tián.", "Bạn ấy nói món Nam Kinh ngọt hơn."], [79.403, 84.249, "她说她喜欢甜的菜，也想吃这里的菜。", "Tā Shuō Tā Xǐ Huān Tián De Cài, Yě Xiǎng Chī Zhè Lǐ De Cài.", "Bạn ấy nói bạn thích món ngọt, cũng muốn ăn món ở đây."], [84.249, 89.389, "我们一边吃，一边说话，她慢慢不紧张了。", "Wǒ Men Yì Biān Chī, Yì Biān Shuō Huà, Tā Màn Màn Bù Jǐn Zhāng Le.", "Chúng tôi vừa ăn vừa nói chuyện, bạn ấy dần không căng thẳng nữa."], [89.389, 94.193, "下午她问了我很多问题，我都回答了。", "Xià Wǔ Tā Wèn Le Wǒ Hěn Duō Wèn Tí, Wǒ Dōu Huí Dá Le.", "Buổi chiều bạn ấy hỏi tôi nhiều câu, tôi đều trả lời."], [94.193, 99.813, "下课以后，她说：“谢谢你，我今天很高兴。”", "Xià Kè Yǐ Hòu, Tā Shuō: “Xiè Xie Nǐ, Wǒ Jīn Tiān Hěn Gāo Xìng.”", "Tan học, bạn ấy nói: “Cảm ơn bạn, hôm nay mình rất vui.”"], [99.816, 103.084, "我们约好周末一起去公园。", "Wǒ Men Yuē Hǎo Zhōu Mò Yì Qǐ Qù Gōng Yuán.", "Chúng tôi hẹn cuối tuần cùng đi công viên."], [103.084, 107.576, "周末天气很好，我们在公园玩儿了很久。", "Zhōu Mò Tiān Qì Hěn Hǎo, Wǒ Men Zài Gōng Yuán Wán Ér Le Hěn Jiǔ.", "Cuối tuần trời đẹp, chúng tôi chơi ở công viên rất lâu."], [107.576, 112.668, "她告诉我南京的事，我也告诉她这里的事。", "Tā Gào Sù Wǒ Nán Jīng De Shì, Wǒ Yě Gào Sù Tā Zhè Lǐ De Shì.", "Bạn ấy kể tôi chuyện Nam Kinh, tôi cũng kể bạn chuyện ở đây."], [112.683, 117.535, "后来她在班里说话多了，笑得也多了。", "Hòu Lái Tā Zài Bān Lǐ Shuō Huà Duō Le, Xiào De Yě Duō Le.", "Sau này bạn ấy nói nhiều hơn trong lớp, cười cũng nhiều hơn."], [117.535, 120.971, "现在她在班里有很多朋友。", "Xiàn Zài Tā Zài Bān Lǐ Yǒu Hěn Duō Péng Yǒu.", "Bây giờ bạn ấy có nhiều bạn trong lớp."], [120.983, 124.155, "现在我们已经是好朋友了。", "Xiàn Zài Wǒ Men Yǐ Jīng Shì Hǎo Péng Yǒu Le.", "Bây giờ chúng tôi đã là bạn tốt."], [124.155, 128.479, "小雨笑着说：“认识你，我真高兴。”", "Xiǎo Yǔ Xiào Zhe Shuō: “Rèn Shi Nǐ, Wǒ Zhēn Gāo Xìng.”", "Tiểu Vũ cười nói: “Được quen bạn, mình thật sự rất vui.”"]]}, "hsk2-14": {"dur": 142.13, "cues": [[7.205, 10.401, "你在家上过汉语课吗？", "Nǐ Zài Jiā Shàng Guò Hàn Yǔ Kè Ma?", "Bạn đã học tiếng Trung ở nhà chưa?"], [10.401, 14.749, "那天早上雨下得很大，我不能去学校。", "Nà Tiān Zǎo Shàng Yǔ Xià De Hěn Dà, Wǒ Bù Néng Qù Xué Xiào.", "Sáng hôm đó mưa rất to, tôi không thể đến trường."], [14.749, 18.975, "因为下雨，今天的汉语课在网上。", "Yīn Wèi Xià Yǔ, Jīn Tiān De Hàn Yǔ Kè Zài Wǎng Shàng.", "Vì trời mưa, tiết tiếng Trung hôm nay học trên mạng."], [18.975, 22.483, "老师让我们八点打开电脑。", "Lǎo Shī Ràng Wǒ Men Bā Diǎn Dǎ Kāi Diàn Nǎo.", "Thầy bảo chúng tôi tám giờ mở máy tính."], [22.483, 26.999, "七点半，我就坐在桌子前面等老师。", "Qī Diǎn Bàn, Wǒ Jiù Zuò Zài Zhuō Zi Qián Miàn Děng Lǎo Shī.", "Bảy giờ rưỡi, tôi đã ngồi trước bàn chờ thầy."], [26.999, 30.891, "我的电脑有一点儿慢，差点儿迟到。", "Wǒ De Diàn Nǎo Yǒu Yì Diǎn Ér Màn, Chà Diǎn Ér Chí Dào.", "Máy tính của tôi hơi chậm, suýt muộn."], [30.908, 35.136, "我有点儿担心，怕听不见老师说话。", "Wǒ Yǒu Diǎn Ér Dān Xīn, Pà Tīng Bú Jiàn Lǎo Shī Shuō Huà.", "Tôi hơi lo, sợ không nghe thấy thầy nói."], [35.136, 38.62, "我等了一会儿，老师就来了。", "Wǒ Děng Le Yí Huì Er, Lǎo Shī Jiù Lái Le.", "Tôi chờ một lúc, thầy đã đến."], [38.62, 42.296, "老师问我们：“大家都到了吗？”", "Lǎo Shī Wèn Wǒ Men: “Dà Jiā Dōu Dào Le Ma?”", "Thầy hỏi chúng tôi: “Các em đến đủ chưa?”"], [42.308, 46.008, "我们都回答：“到了，老师好！”", "Wǒ Men Dōu Huí Dá: “Dào Le, Lǎo Shī Hǎo!”", "Chúng tôi đều trả lời: “Đủ rồi ạ, chào thầy!”"], [46.008, 50.068, "课上我们读课文，也回答问题。", "Kè Shàng Wǒ Men Dú Kè Wén, Yě Huí Dá Wèn Tí.", "Trong giờ chúng tôi đọc bài và trả lời câu hỏi."], [50.068, 53.548, "老师让我们一个一个读课文。", "Lǎo Shī Ràng Wǒ Men Yí Gè Yí Gè Dú Kè Wén.", "Thầy bảo chúng tôi lần lượt từng người đọc bài."], [53.548, 58.28, "我读得有点儿慢，可是老师说没关系。", "Wǒ Dú De Yǒu Diǎn Ér Màn, Kě Shì Lǎo Shī Shuō Méi Guān Xì.", "Tôi đọc hơi chậm, nhưng thầy nói không sao."], [58.28, 62.7, "虽然不能见面，可是也能学到很多。", "Suī Rán Bù Néng Jiàn Miàn, Kě Shì Yě Néng Xué Dào Hěn Duō.", "Dù không gặp mặt, vẫn học được rất nhiều."], [62.715, 66.847, "网上课的时候我坐在自己的房间。", "Wǎng Shàng Kè De Shí Hòu Wǒ Zuò Zài Zì Jǐ De Fáng Jiān.", "Lúc học online tôi ngồi trong phòng mình."], [66.847, 71.699, "我的书和笔都在桌子上，我准备好了。", "Wǒ De Shū Hé Bǐ Dōu Zài Zhuō Zi Shàng, Wǒ Zhǔn Bèi Hǎo Le.", "Sách và bút của tôi đều ở trên bàn, tôi đã chuẩn bị xong."], [71.699, 75.995, "妈妈提醒我要看老师，不要玩手机。", "Mā Ma Tí Xǐng Wǒ Yào Kàn Lǎo Shī, Bú Yào Wán Shǒu Jī.", "Mẹ nhắc tôi phải nhìn thầy, đừng chơi điện thoại."], [75.995, 79.719, "妈妈给我水，就走出房间了。", "Mā Ma Gěi Wǒ Shuǐ, Jiù Zǒu Chū Fáng Jiān Le.", "Mẹ đưa tôi nước rồi đi ra khỏi phòng."], [79.719, 84.091, "我把手机放在一边，认真看老师。", "Wǒ Bǎ Shǒu Jī Fàng Zài Yì Biān, Rèn Zhēn Kàn Lǎo Shī.", "Tôi để điện thoại sang một bên, chăm chú nhìn thầy."], [84.091, 88.847, "老师问问题的时候，我先想一想再回答。", "Lǎo Shī Wèn Wèn Tí De Shí Hòu, Wǒ Xiān Xiǎng Yì Xiǎng Zài Huí Dá.", "Khi thầy hỏi, tôi nghĩ một chút rồi mới trả lời."], [88.862, 91.722, "我回答了两个问题。", "Wǒ Huí Dá Le Liǎng Gè Wèn Tí.", "Tôi trả lời hai câu hỏi."], [91.722, 95.614, "第一个问题我会，第二个我不会。", "Dì Yī Gè Wèn Tí Wǒ Huì, Dì Èr Gè Wǒ Bú Huì.", "Câu đầu tôi biết làm, câu thứ hai tôi không biết."], [95.614, 99.262, "老师说我的发音比以前好。", "Lǎo Shī Shuō Wǒ De Fā Yīn Bǐ Yǐ Qián Hǎo.", "Thầy nói phát âm của tôi tốt hơn trước."], [99.262, 103.418, "我听了很高兴，想以后读得更好。", "Wǒ Tīng Le Hěn Gāo Xìng, Xiǎng Yǐ Hòu Dú De Gèng Hǎo.", "Nghe vậy tôi rất vui, muốn sau này đọc tốt hơn nữa."], [103.418, 109.014, "后来我们一起读课文，老师说我们读得很好。", "Hòu Lái Wǒ Men Yì Qǐ Dú Kè Wén, Lǎo Shī Shuō Wǒ Men Dú De Hěn Hǎo.", "Sau đó chúng tôi cùng đọc bài, thầy nói chúng tôi đọc rất tốt."], [109.028, 112.872, "下课以后我把作业发给老师。", "Xià Kè Yǐ Hòu Wǒ Bǎ Zuò Yè Fā Gěi Lǎo Shī.", "Tan học tôi gửi bài cho thầy."], [112.872, 118.324, "发作业以前，我先看了看，没有问题才发。", "Fā Zuò Yè Yǐ Qián, Wǒ Xiān Kàn Le Kàn, Méi Yǒu Wèn Tí Cái Fā.", "Trước khi gửi bài, tôi xem lại, không có vấn đề mới gửi."], [118.324, 122.744, "老师很快回短信，说我的作业很好。", "Lǎo Shī Hěn Kuài Huí Duǎn Xìn, Shuō Wǒ De Zuò Yè Hěn Hǎo.", "Thầy nhanh chóng trả lời tin nhắn, nói bài của tôi rất tốt."], [122.762, 126.462, "虽然在家，我也认真学习。", "Suī Rán Zài Jiā, Wǒ Yě Rèn Zhēn Xué Xí.", "Dù ở nhà, tôi vẫn học nghiêm túc."], [126.462, 131.938, "下课以后，我关了电脑，去帮妈妈做饭了。", "Xià Kè Yǐ Hòu, Wǒ Guān Le Diàn Nǎo, Qù Bāng Mā Ma Zuò Fàn Le.", "Tan học, tôi tắt máy tính, đi giúp mẹ nấu cơm."]]}, "hsk2-15": {"dur": 146.68, "cues": [[7.386, 11.83, "你的房间乱的时候，你会想收拾吗？", "Nǐ De Fáng Jiān Luàn De Shí Hòu, Nǐ Huì Xiǎng Shōu Shí Ma?", "Khi phòng bạn bừa, bạn có muốn dọn không?"], [11.83, 15.719, "妈妈常常说：“你的房间太乱了！”", "Mā Ma Cháng Cháng Shuō: “Nǐ De Fáng Jiān Tài Luàn Le!”", "Mẹ thường nói: “Phòng con bừa quá!”"], [15.719, 18.507, "我的房间以前很乱。", "Wǒ De Fáng Jiān Yǐ Qián Hěn Luàn.", "Phòng tôi trước đây rất bừa."], [18.507, 22.039, "书在床上，衣服在椅子上。", "Shū Zài Chuáng Shàng, Yī Fu Zài Yǐ Zi Shàng.", "Sách ở trên giường, quần áo ở trên ghế."], [22.039, 26.195, "桌子上有很多书，地上也有衣服。", "Zhuō Zi Shàng Yǒu Hěn Duō Shū, Dì Shàng Yě Yǒu Yī Fu.", "Trên bàn có nhiều sách, dưới đất cũng có quần áo."], [26.219, 29.895, "我找东西的时候，常常找不到。", "Wǒ Zhǎo Dōng Xi De Shí Hòu, Cháng Cháng Zhǎo Bú Dào.", "Khi tôi tìm đồ, thường không tìm thấy."], [29.895, 34.531, "有一次我找笔，找了很久也没找到。", "Yǒu Yí Cì Wǒ Zhǎo Bǐ, Zhǎo Le Hěn Jiǔ Yě Méi Zhǎo Dào.", "Có lần tôi tìm bút, tìm rất lâu cũng không thấy."], [34.531, 38.735, "我觉得房间太乱，找东西真不方便。", "Wǒ Jué De Fáng Jiān Tài Luàn, Zhǎo Dōng Xi Zhēn Bù Fāng Biàn.", "Tôi thấy phòng quá bừa, tìm đồ thật bất tiện."], [38.753, 42.189, "星期天上午我开始收拾。", "Xīng Qī Tiān Shàng Wǔ Wǒ Kāi Shǐ Shōu Shí.", "Sáng chủ nhật tôi bắt đầu dọn."], [42.189, 46.129, "我先打开窗户，房间里很舒服。", "Wǒ Xiān Dǎ Kāi Chuāng Hù, Fáng Jiān Lǐ Hěn Shū Fú.", "Tôi mở cửa sổ trước, trong phòng rất dễ chịu."], [46.129, 51.269, "我对自己说：“先收拾书，再收拾衣服。”", "Wǒ Duì Zì Jǐ Shuō: “Xiān Shōu Shí Shū, Zài Shōu Shí Yī Fu.”", "Tôi tự nói: “Dọn sách trước, rồi dọn quần áo.”"], [51.286, 56.018, "我把书放进书包，把衣服放进柜子。", "Wǒ Bǎ Shū Fàng Jìn Shū Bāo, Bǎ Yī Fu Fàng Jìn Guì Zi.", "Tôi cho sách vào cặp và quần áo vào tủ."], [56.018, 61.398, "书太多了，书包放不下，我就放在桌子上。", "Shū Tài Duō Le, Shū Bāo Fàng Bú Xià, Wǒ Jiù Fàng Zài Zhuō Zi Shàng.", "Sách nhiều quá, cặp không chứa hết, tôi để lên bàn."], [61.419, 65.191, "收拾了一会儿，我觉得有点儿累。", "Shōu Shí Le Yí Huì Er, Wǒ Jué De Yǒu Diǎn Ér Lèi.", "Dọn một lúc, tôi thấy hơi mệt."], [65.191, 68.987, "我坐下休息了一会儿，喝了水。", "Wǒ Zuò Xià Xiū Xi Le Yí Huì Er, Hē Le Shuǐ.", "Tôi ngồi xuống nghỉ một lúc, uống nước."], [68.987, 72.975, "休息以后，我又开始收拾房间。", "Xiū Xi Yǐ Hòu, Wǒ Yòu Kāi Shǐ Shōu Shí Fáng Jiān.", "Nghỉ xong, tôi lại bắt đầu dọn phòng."], [72.986, 75.822, "我把旧报纸扔掉了。", "Wǒ Bǎ Jiù Bào Zhǐ Rēng Diào Le.", "Tôi vứt báo cũ."], [75.822, 80.626, "我还把不穿的衣服放在一起，给妈妈看。", "Wǒ Hái Bǎ Bù Chuān De Yī Fu Fàng Zài Yì Qǐ, Gěi Mā Ma Kàn.", "Tôi còn để quần áo không mặc vào một chỗ, cho mẹ xem."], [80.626, 83.942, "收拾房间用了一个小时。", "Shōu Shí Fáng Jiān Yòng Le Yí Gè Xiǎo Shí.", "Dọn phòng mất một tiếng."], [83.942, 88.05, "现在房间干净了，我看着很舒服。", "Xiàn Zài Fáng Jiān Gān Jìng Le, Wǒ Kàn Zhe Hěn Shū Fú.", "Bây giờ phòng sạch, nhìn rất dễ chịu."], [88.059, 92.167, "桌子上现在只有一本书和一支笔。", "Zhuō Zi Shàng Xiàn Zài Zhǐ Yǒu Yì Běn Shū Hé Yì Zhī Bǐ.", "Trên bàn bây giờ chỉ có một cuốn sách và một cái bút."], [92.167, 95.959, "我找东西的时候，一下就找到了。", "Wǒ Zhǎo Dōng Xi De Shí Hòu, Yí Xià Jiù Zhǎo Dào Le.", "Khi tôi tìm đồ, thoáng cái là thấy ngay."], [95.959, 100.043, "妈妈回来以后，我让她看我的房间。", "Mā Ma Huí Lái Yǐ Hòu, Wǒ Ràng Tā Kàn Wǒ De Fáng Jiān.", "Mẹ về, tôi cho mẹ xem phòng của tôi."], [100.043, 103.119, "妈妈看见以后很高兴。", "Mā Ma Kàn Jiàn Yǐ Hòu Hěn Gāo Xìng.", "Mẹ thấy vậy rất vui."], [103.119, 106.675, "她说干净的房间让人舒服。", "Tā Shuō Gān Jìng De Fáng Jiān Ràng Rén Shū Fú.", "Mẹ nói phòng sạch khiến người ta dễ chịu."], [106.693, 110.585, "妈妈问我：“你收拾了多长时间？”", "Mā Ma Wèn Wǒ: “Nǐ Shōu Shí Le Duō Cháng Shí Jiān?”", "Mẹ hỏi tôi: “Con dọn mất bao lâu?”"], [110.585, 115.893, "我说：“一个小时，我还把旧报纸扔掉了。”", "Wǒ Shuō: “Yí Gè Xiǎo Shí, Wǒ Hái Bǎ Jiù Bào Zhǐ Rēng Diào Le.”", "Tôi nói: “Một tiếng ạ, con còn vứt báo cũ nữa.”"], [115.893, 119.881, "妈妈说：“很好，以后也要这样。”", "Mā Ma Shuō: “Hěn Hǎo, Yǐ Hòu Yě Yào Zhè Yàng.”", "Mẹ nói: “Tốt lắm, sau này cũng phải như vậy.”"], [119.893, 125.489, "我把那支找了很久的笔放在桌子上，看着它笑了。", "Wǒ Bǎ Nà Zhī Zhǎo Le Hěn Jiǔ De Bǐ Fàng Zài Zhuō Zi Shàng, Kàn Zhe Tā Xiào Le.", "Tôi đặt chiếc bút tìm mãi mới thấy lên bàn, nhìn nó mà mỉm cười."], [125.489, 131.349, "晚上，我坐在干净的桌子前看书，心里很高兴。", "Wǎn Shàng, Wǒ Zuò Zài Gān Jìng De Zhuō Zi Qián Kàn Shū, Xīn Lǐ Hěn Gāo Xìng.", "Buổi tối, tôi ngồi trước chiếc bàn sạch sẽ đọc sách, trong lòng rất vui."], [131.349, 136.463, "妈妈笑着说：“下个星期天，我们一起收拾。”", "Mā Ma Xiào Zhe Shuō: “Xià Gè Xīng Qī Tiān, Wǒ Men Yì Qǐ Shōu Shi.”", "Mẹ cười nói: “Chủ nhật sau, chúng ta cùng dọn nhé.”"]]}, "hsk2-16": {"dur": 136.6, "cues": [[6.522, 11.782, "这封信是写给爸爸的，我想今天寄出去。", "Zhè Fēng Xìn Shì Xiě Gěi Bà Ba De, Wǒ Xiǎng Jīn Tiān Jì Chū Qù.", "Lá thư này viết cho bố, tôi muốn gửi đi hôm nay."], [11.782, 15.866, "昨天下午我去邮局，可是找不到。", "Zuó Tiān Xià Wǔ Wǒ Qù Yóu Jú, Kě Shì Zhǎo Bú Dào.", "Chiều qua tôi đi bưu điện nhưng không tìm thấy."], [15.866, 20.79, "我在路上走了一会儿，还是没有看见邮局。", "Wǒ Zài Lù Shàng Zǒu Le Yí Huì Er, Hái Shì Méi Yǒu Kàn Jiàn Yóu Jú.", "Tôi đi trên đường một lúc, vẫn không thấy bưu điện."], [20.822, 24.378, "我有一点儿累，也有一点儿担心。", "Wǒ Yǒu Yì Diǎn Ér Lèi, Yě Yǒu Yì Diǎn Ér Dān Xīn.", "Tôi hơi mệt, cũng hơi lo."], [24.378, 28.39, "然后，我看见一位老人走过来。", "Rán Hòu, Wǒ Kàn Jiàn Yí Wèi Lǎo Rén Zǒu Guò Lái.", "Sau đó, tôi thấy một cụ đi tới."], [28.392, 32.716, "我问一个老人：请问，邮局在哪儿？", "Wǒ Wèn Yí Gè Lǎo Rén: Qǐng Wèn, Yóu Jú Zài Nǎ Ér?", "Tôi hỏi một cụ: Xin hỏi, bưu điện ở đâu?"], [32.716, 36.2, "老人先看了看我手里的信。", "Lǎo Rén Xiān Kàn Le Kàn Wǒ Shǒu Lǐ De Xìn.", "Cụ nhìn lá thư trên tay tôi trước."], [36.2, 39.362, "他问我：你要寄信吗？", "Tā Wèn Wǒ: Nǐ Yào Jì Xìn Ma?", "Ông hỏi tôi: Bạn muốn gửi thư à?"], [39.362, 43.35, "我说：是的，我找了很久了。", "Wǒ Shuō: Shì De, Wǒ Zhǎo Le Hěn Jiǔ Le.", "Tôi nói: Vâng, tôi tìm lâu lắm rồi."], [43.35, 48.466, "他说：一直走，到红绿灯向右拐。", "Tā Shuō: Yì Zhí Zǒu, Dào Hóng Lǜ Dēng Xiàng Yòu Guǎi.", "Ông nói: Đi thẳng, đến đèn đỏ thì rẽ phải."], [48.466, 53.242, "他还告诉我：不远，走十分钟就到。", "Tā Hái Gào Sù Wǒ: Bù Yuǎn, Zǒu Shí Fēn Zhōng Jiù Dào.", "Ông còn bảo tôi: Không xa, đi mười phút là tới."], [53.242, 56.99, "我说：谢谢，我现在就去。", "Wǒ Shuō: Xiè Xiè, Wǒ Xiàn Zài Jiù Qù.", "Tôi nói: Cảm ơn ông, tôi đi ngay đây."], [56.99, 59.826, "我按老人说的一直走。", "Wǒ Àn Lǎo Rén Shuō De Yì Zhí Zǒu.", "Tôi đi thẳng theo lời cụ."], [59.826, 63.262, "路上人很多，车也很多。", "Lù Shàng Rén Hěn Duō, Chē Yě Hěn Duō.", "Trên đường người rất đông, xe cũng rất nhiều."], [63.276, 66.784, "我走得很慢，一边走一边看。", "Wǒ Zǒu Dé Hěn Màn, Yì Biān Zǒu Yì Biān Kàn.", "Tôi đi rất chậm, vừa đi vừa nhìn."], [66.784, 70.412, "我等了一会儿，然后才过去。", "Wǒ Děng Le Yí Huì Er, Rán Hòu Cái Guò Qù.", "Tôi đợi một lúc rồi mới qua đường."], [70.412, 73.728, "过去以后，我向右拐。", "Guò Qù Yǐ Hòu, Wǒ Xiàng Yòu Guǎi.", "Qua đường xong, tôi rẽ phải."], [73.742, 77.922, "向右拐以后，我先看见了银行。", "Xiàng Yòu Guǎi Yǐ Hòu, Wǒ Xiān Kàn Jiàn Le Yín Háng.", "Rẽ phải xong, tôi thấy ngân hàng trước."], [77.922, 82.482, "可是我没有看见邮局，心里又担心了。", "Kě Shì Wǒ Méi Yǒu Kàn Jiàn Yóu Jú, Xīn Lǐ Yòu Dān Xīn Le.", "Nhưng tôi không thấy bưu điện, trong lòng lại lo."], [82.482, 85.558, "我想：是不是走错了？", "Wǒ Xiǎng: Shì Bú Shì Zǒu Cuò Le?", "Tôi nghĩ: Có phải mình đi nhầm không?"], [85.558, 88.514, "然后我又走了一会儿。", "Rán Hòu Wǒ Yòu Zǒu Le Yí Huì Er.", "Rồi tôi lại đi thêm một lúc."], [88.514, 91.614, "邮局就在银行旁边。", "Yóu Jú Jiù Zài Yín Háng Páng Biān.", "Bưu điện ở ngay cạnh ngân hàng."], [91.616, 94.884, "看见邮局，我很高兴。", "Kàn Jiàn Yóu Jú, Wǒ Hěn Gāo Xìng.", "Thấy bưu điện, tôi rất vui."], [94.884, 98.968, "我很快走进邮局，心里不担心了。", "Wǒ Hěn Kuài Zǒu Jìn Yóu Jú, Xīn Lǐ Bù Dān Xīn Le.", "Tôi nhanh chóng bước vào bưu điện, trong lòng hết lo."], [98.968, 102.068, "我寄了一封信给爸爸。", "Wǒ Jì Le Yì Fēng Xìn Gěi Bà Ba.", "Tôi gửi một lá thư cho bố."], [102.082, 106.07, "寄完信，我很高兴，也不累了。", "Jì Wán Xìn, Wǒ Hěn Gāo Xìng, Yě Bú Lèi Le.", "Gửi thư xong, tôi rất vui, cũng không mệt nữa."], [106.07, 109.89, "出来的时候我又看见那位老人。", "Chū Lái De Shí Hòu Wǒ Yòu Kàn Jiàn Nà Wèi Lǎo Rén.", "Lúc ra tôi lại gặp cụ đó."], [109.89, 113.014, "老人问我：找到了吗？", "Lǎo Rén Wèn Wǒ: Zhǎo Dào Le Ma?", "Ông hỏi tôi: Tìm thấy rồi chứ?"], [113.016, 119.284, "我高兴地说：找到了！谢谢您，邮局就在银行旁边。", "Wǒ Gāo Xìng De Shuō: Zhǎo Dào Le! Xiè Xiè Nín, Yóu Jú Jiù Zài Yín Háng Páng Biān.", "Tôi vui mừng nói: Tìm thấy rồi ạ! Cảm ơn ông, bưu điện ở ngay cạnh ngân hàng."], [119.284, 122.648, "我跟他说谢谢，他笑了。", "Wǒ Gēn Tā Shuō Xiè Xiè, Tā Xiào Le.", "Tôi nói cảm ơn, ông cười."], [122.648, 126.396, "我跟老人说再见，我们都笑了。", "Wǒ Gēn Lǎo Rén Shuō Zài Jiàn, Wǒ Men Dōu Xiào Le.", "Tôi chào tạm biệt cụ, cả hai chúng tôi đều cười."]]}, "hsk2-17": {"dur": 150.48, "cues": [[6.833, 11.469, "弟弟很喜欢小狗，看见小狗就很高兴。", "Dì Di Hěn Xǐ Huān Xiǎo Gǒu, Kàn Jiàn Xiǎo Gǒu Jiù Hěn Gāo Xìng.", "Em trai rất thích chó nhỏ, thấy chó nhỏ là vui."], [11.469, 14.449, "弟弟很想养一只小狗。", "Dì Di Hěn Xiǎng Yǎng Yì Zhī Xiǎo Gǒu.", "Em trai rất muốn nuôi một con chó nhỏ."], [14.449, 19.709, "每天晚上，他都问爸爸：我可以养小狗吗？", "Měi Tiān Wǎn Shàng, Tā Dōu Wèn Bà Ba: Wǒ Kě Yǐ Yǎng Xiǎo Gǒu Ma?", "Mỗi tối, em đều hỏi bố: Con nuôi chó nhỏ được không?"], [19.733, 23.529, "爸爸说，养狗要每天出去走。", "Bà Ba Shuō, Yǎng Gǒu Yào Měi Tiān Chū Qù Zǒu.", "Bố nói nuôi chó thì mỗi ngày phải dắt đi dạo."], [23.529, 26.653, "还要给它吃饭、喝水。", "Hái Yào Gěi Tā Chī Fàn, Hē Shuǐ.", "Còn phải cho nó ăn và uống nước."], [26.653, 32.129, "爸爸还说：下雨天也要出去，你能做到吗？", "Bà Ba Hái Shuō: Xià Yǔ Tiān Yě Yào Chū Qù, Nǐ Néng Zuò Dào Ma?", "Bố còn nói: Ngày mưa cũng phải ra ngoài, con làm được không?"], [32.133, 35.689, "弟弟想了想，他有一点儿担心。", "Dì Di Xiǎng Le Xiǎng, Tā Yǒu Yì Diǎn Ér Dān Xīn.", "Em trai nghĩ một lúc, em hơi lo."], [35.689, 40.709, "他问爸爸：“我早上能起来吗？我有一点儿担心。”", "Tā Wèn Bà Ba: “Wǒ Zǎo Shàng Néng Qǐ Lái Ma? Wǒ Yǒu Yì Diǎn Ér Dān Xīn.”", "Em hỏi bố: “Sáng con dậy được không ạ? Con hơi lo.”"], [40.709, 44.409, "爸爸说：那你要早一点儿睡觉。", "Bà Ba Shuō: Nà Nǐ Yào Zǎo Yì Diǎn Ér Shuì Jiào.", "Bố nói: Vậy thì con phải ngủ sớm một chút."], [44.433, 48.493, "妈妈说：大家一起帮忙，就好了。", "Mā Ma Shuō: Dà Jiā Yì Qǐ Bāng Máng, Jiù Hǎo Le.", "Mẹ nói: Cả nhà cùng giúp thì sẽ ổn thôi."], [48.493, 51.281, "弟弟说他可以做到。", "Dì Di Shuō Tā Kě Yǐ Zuò Dào.", "Em nói em làm được."], [51.281, 55.125, "他说：我每天早上六点起床。", "Tā Shuō: Wǒ Měi Tiān Zǎo Shàng Liù Diǎn Qǐ Chuáng.", "Em nói: Mỗi sáng con dậy lúc sáu giờ."], [55.133, 57.249, "爸爸说可以。", "Bà Ba Shuō Kě Yǐ.", "Bố nói được."], [57.249, 60.513, "弟弟听了，高兴地笑了。", "Dì Di Tīng Le, Gāo Xìng De Xiào Le.", "Em trai nghe xong, vui vẻ cười."], [60.513, 64.621, "星期天，我们去把小狗接回了家。", "Xīng Qī Tiān, Wǒ Men Qù Bǎ Xiǎo Gǒu Jiē Huí Le Jiā.", "Chủ nhật, chúng tôi đi đón chú chó nhỏ về nhà."], [64.621, 67.529, "小狗的名字叫小白。", "Xiǎo Gǒu De Míng Zì Jiào Xiǎo Bái.", "Con chó tên là Tiểu Bạch."], [67.546, 70.598, "它很小，眼睛很黑。", "Tā Hěn Xiǎo, Yǎn Jīng Hěn Hēi.", "Nó rất nhỏ, mắt rất đen."], [70.598, 74.778, "小白第一天到家的时候，有一点儿怕。", "Xiǎo Bái Dì Yī Tiān Dào Jiā De Shí Hòu, Yǒu Yì Diǎn Ér Pà.", "Ngày đầu Tiểu Bạch về nhà, nó hơi sợ."], [74.778, 78.214, "它坐在门口，不吃也不喝。", "Tā Zuò Zài Mén Kǒu, Bù Chī Yě Bù Hē.", "Nó ngồi ở cửa, không ăn cũng không uống."], [78.246, 82.282, "弟弟慢慢走到它旁边，跟它说话。", "Dì Di Màn Màn Zǒu Dào Tā Páng Biān, Gēn Tā Shuō Huà.", "Em trai chậm rãi đi đến bên nó, nói chuyện với nó."], [82.282, 86.15, "过了一会儿，小白开始吃东西了。", "Guò Le Yí Huì Er, Xiǎo Bái Kāi Shǐ Chī Dōng Xī Le.", "Một lúc sau, Tiểu Bạch bắt đầu ăn."], [86.15, 88.938, "我们看了，都笑了。", "Wǒ Men Kàn Le, Dōu Xiào Le.", "Chúng tôi nhìn thấy, đều cười."], [88.946, 93.39, "有一天下午，弟弟带小白去公园玩儿。", "Yǒu Yì Tiān Xià Wǔ, Dì Di Dài Xiǎo Bái Qù Gōng Yuán Wán Ér.", "Một buổi chiều, em trai dắt Tiểu Bạch ra công viên chơi."], [93.39, 99.034, "公园里有一只小猫，小白看见了，就跑了过去。", "Gōng Yuán Lǐ Yǒu Yì Zhī Xiǎo Māo, Xiǎo Bái Kàn Jiàn Le, Jiù Pǎo Le Guò Qù.", "Trong công viên có một con mèo nhỏ, Tiểu Bạch nhìn thấy liền chạy tới."], [99.046, 103.61, "弟弟也跑过去，可是小白跑得太快了。", "Dì Di Yě Pǎo Guò Qù, Kě Shì Xiǎo Bái Pǎo Dé Tài Kuài Le.", "Em trai cũng chạy theo, nhưng Tiểu Bạch chạy nhanh quá."], [103.61, 107.379, "过了一会儿，弟弟找不到小白了。", "Guò Le Yí Huì Er, Dì Di Zhǎo Bú Dào Xiǎo Bái Le.", "Một lúc sau, em trai không tìm thấy Tiểu Bạch nữa."], [107.379, 113.167, "他在公园里找了很久，一边找一边叫小白的名字。", "Tā Zài Gōng Yuán Lǐ Zhǎo Le Hěn Jiǔ, Yì Biān Zhǎo Yì Biān Jiào Xiǎo Bái De Míng Zì.", "Em tìm trong công viên rất lâu, vừa tìm vừa gọi tên Tiểu Bạch."], [113.167, 118.451, "天快黑了，弟弟很担心，给家里打电话。", "Tiān Kuài Hēi Le, Dì Di Hěn Dān Xīn, Gěi Jiā Lǐ Dǎ Diàn Huà.", "Trời sắp tối, em trai rất lo, gọi điện về nhà."], [118.451, 124.789, "我们都去公园帮忙找，妈妈说：“别担心，一定能找到。”", "Wǒ Men Dōu Qù Gōng Yuán Bāng Máng Zhǎo, Mā Ma Shuō: “Bié Dān Xīn, Yí Dìng Néng Zhǎo Dào.”", "Cả nhà đều ra công viên giúp tìm, mẹ nói: “Đừng lo, nhất định sẽ tìm thấy.”"], [124.789, 131.873, "过了一会儿，我们在公园门口看见了小白，它站在门口等我们。", "Guò Le Yí Huì Er, Wǒ Men Zài Gōng Yuán Mén Kǒu Kàn Jiàn Le Xiǎo Bái, Tā Zhàn Zài Mén Kǒu Děng Wǒ Men.", "Một lúc sau, chúng tôi thấy Tiểu Bạch ở cổng công viên, nó đứng ở cổng đợi chúng tôi."], [131.873, 140.253, "弟弟跑过去说：“小白，我再也不让你一个人跑了。”爸爸妈妈听了，都笑了。", "Dì Di Pǎo Guò Qù Shuō: “Xiǎo Bái, Wǒ Zài Yě Bú Ràng Nǐ Yí Gè Rén Pǎo Le.” Bà Ba Mā Ma Tīng Le, Dōu Xiào Le.", "Em trai chạy tới nói: “Tiểu Bạch, anh không để em chạy một mình nữa đâu.” Bố mẹ nghe vậy đều cười."]]}, "hsk2-18": {"dur": 148.09, "cues": [[7.875, 13.207, "老师说完考试的事，我的心里有一点儿紧张。", "Lǎo Shī Shuō Wán Kǎo Shì De Shì, Wǒ De Xīn Lǐ Yǒu Yì Diǎn Ér Jǐn Zhāng.", "Thầy nói xong chuyện thi cử, trong lòng tôi hơi căng thẳng."], [13.207, 16.523, "下星期一有汉语考试。", "Xià Xīng Qī Yī Yǒu Hàn Yǔ Kǎo Shì.", "Thứ Hai tuần sau có bài kiểm tra tiếng Trung."], [16.523, 20.485, "我有一点儿担心，因为生词很多。", "Wǒ Yǒu Yì Diǎn Ér Dān Xīn, Yīn Wéi Shēng Cí Hěn Duō.", "Tôi hơi lo vì từ mới rất nhiều."], [20.485, 23.681, "我问同学：你担心吗？", "Wǒ Wèn Tóng Xué: Nǐ Dān Xīn Ma?", "Tôi hỏi bạn học: Bạn có lo không?"], [23.681, 28.125, "同学说：我也担心，生词太多了。", "Tóng Xué Shuō: Wǒ Yě Dān Xīn, Shēng Cí Tài Duō Le.", "Bạn nói: Tôi cũng lo, từ mới nhiều quá."], [28.125, 32.809, "从那天开始，我们每天晚上一起复习。", "Cóng Nà Tiān Kāi Shǐ, Wǒ Men Měi Tiān Wǎn Shàng Yì Qǐ Fù Xí.", "Từ hôm đó, mỗi tối chúng tôi cùng nhau ôn tập."], [32.818, 37.094, "这几天我每天晚上复习一个小时。", "Zhè Jǐ Tiān Wǒ Měi Tiān Wǎn Shàng Fù Xí Yí Gè Xiǎo Shí.", "Mấy ngày nay mỗi tối tôi ôn một tiếng."], [37.094, 41.558, "有时候一个小时太少，我就多学一会儿。", "Yǒu Shí Hòu Yí Gè Xiǎo Shí Tài Shǎo, Wǒ Jiù Duō Xué Yí Huì Er.", "Có lúc một tiếng là quá ít, tôi lại học thêm một lúc."], [41.558, 45.762, "同学也帮助我练习听力和说话。", "Tóng Xué Yě Bāng Zhù Wǒ Liàn Xí Tīng Lì Hé Shuō Huà.", "Bạn học cũng giúp tôi luyện nghe và nói."], [45.762, 50.854, "同学听我说汉语，还告诉我哪里错了。", "Tóng Xué Tīng Wǒ Shuō Hàn Yǔ, Hái Gào Sù Wǒ Nǎ Lǐ Cuò Le.", "Bạn nghe tôi nói tiếng Trung, còn bảo tôi sai ở đâu."], [50.854, 54.928, "我听同学说话，也帮他看生词。", "Wǒ Tīng Tóng Xué Shuō Huà, Yě Bāng Tā Kàn Shēng Cí.", "Tôi nghe bạn nói, cũng giúp bạn xem từ mới."], [54.928, 58.916, "那天晚上，我们一直学到十点。", "Nà Tiān Wǎn Shàng, Wǒ Men Yì Zhí Xué Dào Shí Diǎn.", "Tối hôm đó, chúng tôi học mãi đến mười giờ."], [58.928, 62.148, "我把生词写在卡片上。", "Wǒ Bǎ Shēng Cí Xiě Zài Kǎ Piàn Shàng.", "Tôi viết từ mới lên thẻ."], [62.148, 66.376, "我做了很多卡片，放在书的旁边。", "Wǒ Zuò Le Hěn Duō Kǎ Piàn, Fàng Zài Shū De Páng Biān.", "Tôi làm nhiều thẻ, để bên cạnh sách."], [66.376, 70.724, "每天晚上我先看中文，再说意思。", "Měi Tiān Wǎn Shàng Wǒ Xiān Kàn Zhòng Wén, Zài Shuō Yì Sī.", "Mỗi tối tôi xem chữ Trung trước rồi nói nghĩa."], [70.728, 75.556, "如果说对了，我就把卡片放在一边。", "Rú Guǒ Shuō Duì Le, Wǒ Jiù Bǎ Kǎ Piàn Fàng Zài Yì Biān.", "Nếu nói đúng, tôi để thẻ sang một bên."], [75.556, 80.768, "如果说错了，我就再看一次，再说一次。", "Rú Guǒ Shuō Cuò Le, Wǒ Jiù Zài Kàn Yí Cì, Zài Shuō Yí Cì.", "Nếu nói sai, tôi xem lại một lần, nói lại một lần."], [80.768, 84.276, "同学问我问题，我也问他。", "Tóng Xué Wèn Wǒ Wèn Tí, Wǒ Yě Wèn Tā.", "Bạn hỏi tôi, tôi cũng hỏi bạn."], [84.276, 88.192, "有的问题我不会，我想了很久。", "Yǒu De Wèn Tí Wǒ Bú Huì, Wǒ Xiǎng Le Hěn Jiǔ.", "Có câu hỏi tôi không biết, tôi nghĩ rất lâu."], [88.192, 90.978, "有的题我还是不会。", "Yǒu De Tí Wǒ Hái Shì Bú Huì.", "Có câu tôi vẫn chưa biết."], [90.978, 94.414, "我把不会的题写在本子上。", "Wǒ Bǎ Bú Huì De Tí Xiě Zài Běn Zi Shàng.", "Tôi viết những câu chưa biết vào vở."], [94.414, 97.562, "可是我知道错在哪里。", "Kě Shì Wǒ Zhī Dào Cuò Zài Nǎ Lǐ.", "Nhưng tôi biết mình sai ở đâu."], [97.562, 102.678, "同学告诉我对的回答，我又练习了几次。", "Tóng Xué Gào Sù Wǒ Duì De Huí Dá, Wǒ Yòu Liàn Xí Le Jǐ Cì.", "Bạn cho tôi đáp án đúng, tôi lại luyện thêm vài lần."], [102.678, 106.546, "星期天晚上，我早一点儿睡觉。", "Xīng Qī Tiān Wǎn Shàng, Wǒ Zǎo Yì Diǎn Ér Shuì Jiào.", "Tối Chủ nhật, tôi đi ngủ sớm một chút."], [106.546, 110.438, "睡觉以前，我又看了看卡片。", "Shuì Jiào Yǐ Qián, Wǒ Yòu Kàn Le Kàn Kǎ Piàn.", "Trước khi ngủ, tôi lại xem thẻ một lượt."], [110.438, 114.81, "妈妈说：别担心，你准备得很好。", "Mā Ma Shuō: Bié Dān Xīn, Nǐ Zhǔn Bèi Dé Hěn Hǎo.", "Mẹ nói: Đừng lo, con chuẩn bị rất tốt rồi."], [114.812, 118.368, "我听了，心里不那么紧张了。", "Wǒ Tīng Le, Xīn Lǐ Bú Nà Me Jǐn Zhāng Le.", "Tôi nghe xong, trong lòng không căng thẳng như trước nữa."], [118.368, 121.876, "考试那一天我不那么担心了。", "Kǎo Shì Nà Yì Tiān Wǒ Bú Nà Me Dān Xīn Le.", "Ngày thi tôi không lo nhiều nữa."], [121.876, 126.08, "我对自己说：慢慢做，不要紧张。", "Wǒ Duì Zì Jǐ Shuō: Màn Màn Zuò, Bú Yào Jǐn Zhāng.", "Tôi tự nhủ: Cứ làm từ từ, đừng căng thẳng."], [126.112, 131.804, "考试的时候，我先做会的题，再做不会的题。", "Kǎo Shì De Shí Hòu, Wǒ Xiān Zuò Huì De Tí, Zài Zuò Bú Huì De Tí.", "Khi thi, tôi làm câu biết trước, rồi mới làm câu không biết."], [131.804, 137.952, "考完以后，我走出教室，看见同学，我们都笑了。", "Kǎo Wán Yǐ Hòu, Wǒ Zǒu Chū Jiào Shì, Kàn Jiàn Tóng Xué, Wǒ Men Dōu Xiào Le.", "Thi xong, tôi bước ra khỏi lớp, nhìn thấy bạn học, chúng tôi đều cười."]]}, "hsk2-19": {"dur": 132.82, "cues": [[7.643, 11.703, "这次去杭州，我们玩儿得不想回来了。", "Zhè Cì Qù Háng Zhōu, Wǒ Men Wán Ér Dé Bù Xiǎng Huí Lái Le.", "Lần đi Hàng Châu này, chúng tôi chơi đến mức không muốn về."], [11.703, 14.611, "我们在杭州玩儿了三天。", "Wǒ Men Zài Háng Zhōu Wán Ér Le Sān Tiān.", "Chúng tôi chơi ở Hàng Châu ba ngày."], [14.613, 19.561, "我们是坐火车去的，路上看了很多风景。", "Wǒ Men Shì Zuò Huǒ Chē Qù De, Lù Shàng Kàn Le Hěn Duō Fēng Jǐng.", "Chúng tôi đi tàu hỏa, trên đường ngắm nhiều phong cảnh."], [19.561, 23.141, "那里的湖很大，风景很美。", "Nà Lǐ De Hú Hěn Dà, Fēng Jǐng Hěn Měi.", "Hồ ở đó rất lớn, phong cảnh rất đẹp."], [23.146, 26.558, "第一天，我们先去看西湖。", "Dì Yì Tiān, Wǒ Men Xiān Qù Kàn Xī Hú.", "Ngày đầu tiên, chúng tôi đi xem Tây Hồ trước."], [26.558, 30.066, "我们坐船，也吃了当地的菜。", "Wǒ Men Zuò Chuán, Yě Chī Le Dāng Dì De Cài.", "Chúng tôi đi thuyền và ăn món địa phương."], [30.066, 35.014, "船开得很慢，我们一边看湖一边说话。", "Chuán Kāi Dé Hěn Màn, Wǒ Men Yì Biān Kàn Hú Yì Biān Shuō Huà.", "Thuyền đi rất chậm, chúng tôi vừa ngắm hồ vừa nói chuyện."], [35.046, 39.106, "那里的菜有一点儿甜，可是很好吃。", "Nà Lǐ De Cài Yǒu Yì Diǎn Ér Tián, Kě Shì Hěn Hǎo Chī.", "Món ở đó hơi ngọt, nhưng rất ngon."], [39.106, 41.798, "杭州的茶也很好。", "Háng Zhōu De Chá Yě Hěn Hǎo.", "Trà Hàng Châu cũng rất ngon."], [41.798, 45.594, "下午，我们在湖边坐着喝茶。", "Xià Wǔ, Wǒ Men Zài Hú Biān Zuò Zhe Hē Chá.", "Buổi chiều, chúng tôi ngồi bên hồ uống trà."], [45.613, 49.961, "有的人在看湖，有的人在说话。", "Yǒu De Rén Zài Kàn Hú, Yǒu De Rén Zài Shuō Huà.", "Có người ngắm hồ, có người nói chuyện."], [49.961, 54.213, "虽然人很多，可是我们玩儿得很开心。", "Suī Rán Rén Hěn Duō, Kě Shì Wǒ Men Wán Ér Dé Hěn Kāi Xīn.", "Dù người rất đông, chúng tôi vẫn chơi rất vui."], [54.213, 57.697, "第二天早上，忽然下雨了。", "Dì Èr Tiān Zǎo Shàng, Hū Rán Xià Yǔ Le.", "Sáng ngày thứ hai, trời bỗng đổ mưa."], [57.697, 62.549, "我们没有带伞，只能在湖边的小店里等。", "Wǒ Men Méi Yǒu Dài Sǎn, Zhǐ Néng Zài Hú Biān De Xiǎo Diàn Lǐ Děng.", "Chúng tôi không mang ô, chỉ đành đợi trong quán nhỏ bên hồ."], [62.549, 66.465, "朋友说：雨天看湖，也很美。", "Péng Yǒu Shuō: Yǔ Tiān Kàn Hú, Yě Hěn Měi.", "Bạn tôi nói: Ngày mưa ngắm hồ cũng rất đẹp."], [66.48, 71.236, "我听了他的话，再看湖，真的不一样。", "Wǒ Tīng Le Tā De Huà, Zài Kàn Hú, Zhēn De Bù Yí Yàng.", "Tôi nghe lời bạn, ngắm hồ lại, quả thật khác hẳn."], [71.236, 76.136, "过了一会儿，雨小了，我们又出去玩儿了。", "Guò Le Yí Huì Er, Yǔ Xiǎo Le, Wǒ Men Yòu Chū Qù Wán Ér Le.", "Một lúc sau, mưa nhỏ lại, chúng tôi lại ra ngoài chơi."], [76.136, 80.532, "我们又出去走了走，还买了一些茶。", "Wǒ Men Yòu Chū Qù Zǒu Le Zǒu, Hái Mǎi Le Yì Xiē Chá.", "Chúng tôi lại ra ngoài đi dạo, còn mua một ít trà."], [80.546, 85.71, "第三天，我们要回家了，我有一点儿不想走。", "Dì Sān Tiān, Wǒ Men Yào Huí Jiā Le, Wǒ Yǒu Yì Diǎn Ér Bù Xiǎng Zǒu.", "Ngày thứ ba, chúng tôi phải về, tôi hơi không muốn đi."], [85.71, 88.474, "我给家人寄了照片。", "Wǒ Gěi Jiā Rén Jì Le Zhào Piàn.", "Tôi gửi ảnh cho người nhà."], [88.474, 92.27, "我在照片后面写了杭州的名字。", "Wǒ Zài Zhào Piàn Hòu Miàn Xiě Le Háng Zhōu De Míng Zì.", "Tôi viết tên Hàng Châu sau tấm ảnh."], [92.28, 95.284, "妈妈说风景真漂亮。", "Mā Ma Shuō Fēng Jǐng Zhēn Piào Liang.", "Mẹ nói phong cảnh thật đẹp."], [95.284, 98.912, "妈妈问我：你们玩儿得开心吗？", "Mā Ma Wèn Wǒ: Nǐ Men Wán Ér Dé Kāi Xīn Ma?", "Mẹ hỏi tôi: Các con chơi có vui không?"], [98.912, 103.113, "我说：很开心，明年我们一起去。", "Wǒ Shuō: Hěn Kāi Xīn, Míng Nián Wǒ Men Yì Qǐ Qù.", "Tôi nói: Rất vui, năm sau chúng ta cùng đi."], [103.113, 106.645, "回来以后我把票放进本子里。", "Huí Lái Yǐ Hòu Wǒ Bǎ Piào Fàng Jìn Běn Zi Lǐ.", "Về rồi tôi cất vé vào vở."], [106.646, 111.45, "票的旁边，我还放了那张最美的照片。", "Piào De Páng Biān, Wǒ Hái Fàng Le Nà Zhāng Zuì Měi De Zhào Piàn.", "Bên cạnh vé, tôi còn để tấm ảnh đẹp nhất."], [111.45, 115.75, "每次看见照片，我就想到杭州的湖。", "Měi Cì Kàn Jiàn Zhào Piàn, Wǒ Jiù Xiǎng Dào Háng Zhōu De Hú.", "Mỗi lần thấy ảnh, tôi lại nhớ đến hồ ở Hàng Châu."], [115.75, 119.086, "我想明年再去看一次西湖。", "Wǒ Xiǎng Míng Nián Zài Qù Kàn Yí Cì Xī Hú.", "Năm sau tôi muốn đi xem Tây Hồ thêm lần nữa."], [119.086, 122.594, "到时候，我要带妈妈一起去。", "Dào Shí Hòu, Wǒ Yào Dài Mā Ma Yì Qǐ Qù.", "Đến lúc đó, tôi sẽ đưa mẹ đi cùng."]]}, "hsk2-20": {"dur": 142.83, "cues": [[6.813, 10.873, "早上，我听见楼上有人说话。", "Zǎo Shàng, Wǒ Tīng Jiàn Lóu Shàng Yǒu Rén Shuō Huà.", "Buổi sáng, tôi nghe thấy trên lầu có người nói chuyện."], [10.873, 14.621, "楼上的王阿姨今天要搬家。", "Lóu Shàng De Wáng Ā Yí Jīn Tiān Yào Bān Jiā.", "Hôm nay cô Vương ở tầng trên chuyển nhà."], [14.621, 18.223, "东西很多，她一个人拿不动。", "Dōng Xī Hěn Duō, Tā Yí Gè Rén Ná Bú Dòng.", "Đồ rất nhiều, một mình cô mang không nổi."], [18.223, 22.427, "王阿姨问我们：你们有时间帮忙吗？", "Wáng Ā Yí Wèn Wǒ Men: Nǐ Men Yǒu Shí Jiān Bāng Máng Ma?", "Cô Vương hỏi chúng tôi: Các cháu có thời gian giúp không?"], [22.427, 26.271, "爸爸说：有，我们现在就来。", "Bà Ba Shuō: Yǒu, Wǒ Men Xiàn Zài Jiù Lái.", "Bố nói: Có, chúng tôi đến ngay."], [26.271, 28.987, "爸爸和我去帮忙。", "Bà Ba Hé Wǒ Qù Bāng Máng.", "Bố và tôi lên giúp."], [28.99, 30.962, "今天很热。", "Jīn Tiān Hěn Rè.", "Hôm nay rất nóng."], [30.962, 35.694, "我们先把小箱子搬下楼，再搬大的。", "Wǒ Men Xiān Bǎ Xiǎo Xiāng Zi Bān Xià Lóu, Zài Bān Dà De.", "Chúng tôi chuyển thùng nhỏ xuống trước, rồi mới chuyển thùng lớn."], [35.694, 38.386, "我们搬了十个箱子。", "Wǒ Men Bān Le Shí Gè Xiāng Zǐ.", "Chúng tôi chuyển mười thùng."], [38.39, 42.618, "有一个箱子很大，爸爸和我一起拿。", "Yǒu Yí Gè Xiāng Zi Hěn Dà, Bà Ba Hé Wǒ Yì Qǐ Ná.", "Có một thùng rất to, bố và tôi cùng mang."], [42.618, 47.998, "我走得很慢，爸爸说：慢一点儿，没关系。", "Wǒ Zǒu Dé Hěn Màn, Bà Ba Shuō: Màn Yì Diǎn Ér, Méi Guān Xì.", "Tôi đi rất chậm, bố nói: Chậm một chút, không sao."], [48.0, 51.46, "新家在五楼，没有电梯。", "Xīn Jiā Zài Wǔ Lóu, Méi Yǒu Diàn Tī.", "Nhà mới ở tầng năm, không có thang máy."], [51.46, 55.664, "五楼很高，我们走得很慢，也很累。", "Wǔ Lóu Hěn Gāo, Wǒ Men Zǒu De Hěn Màn, Yě Hěn Lèi.", "Tầng năm rất cao, chúng tôi đi rất chậm, cũng rất mệt."], [55.664, 59.46, "到了三楼，我累得坐下来休息。", "Dào Le Sān Lóu, Wǒ Lèi Dé Zuò Xià Lái Xiū Xi.", "Đến tầng ba, tôi mệt đến mức ngồi xuống nghỉ."], [59.466, 64.846, "王阿姨给我水，说：先喝水，再搬。", "Wáng Ā Yí Gěi Wǒ Shuǐ, Shuō: Xiān Hē Shuǐ, Zài Bān.", "Cô Vương đưa tôi nước, nói: Uống nước trước, rồi chuyển tiếp."], [64.846, 68.138, "喝完水，我不那么累了。", "Hē Wán Shuǐ, Wǒ Bú Nà Me Lèi Le.", "Uống nước xong, tôi không mệt như trước nữa."], [68.166, 72.562, "我们把箱子搬到新家，还帮她扫地。", "Wǒ Men Bǎ Xiāng Zǐ Bān Dào Xīn Jiā, Hái Bāng Tā Sǎo Dì.", "Chúng tôi chuyển thùng sang nhà mới và giúp cô quét nhà."], [72.562, 75.998, "新家不大，可是很干净。", "Xīn Jiā Bú Dà, Kě Shì Hěn Gān Jìng.", "Nhà mới không lớn, nhưng rất sạch."], [75.998, 79.842, "我帮王阿姨把书放在桌子上。", "Wǒ Bāng Wáng Ā Yí Bǎ Shū Fàng Zài Zhuō Zi Shàng.", "Tôi giúp cô Vương để sách lên bàn."], [79.866, 83.83, "爸爸帮她把椅子搬到窗户旁边。", "Bà Ba Bāng Tā Bǎ Yǐ Zi Bān Dào Chuāng Hù Páng Biān.", "Bố giúp cô chuyển ghế đến bên cửa sổ."], [83.83, 87.17, "搬完以后我们一起喝水。", "Bān Wán Yǐ Hòu Wǒ Men Yì Qǐ Hē Shuǐ.", "Chuyển xong chúng tôi cùng uống nước."], [87.17, 90.1, "王阿姨一直说谢谢。", "Wáng Ā Yí Yì Zhí Shuō Xiè Xiè.", "Cô Vương nói cảm ơn suốt."], [90.1, 94.904, "她说：没有你们，我一个人真搬不完。", "Tā Shuō: Méi Yǒu Nǐ Men, Wǒ Yí Gè Rén Zhēn Bān Bù Wán.", "Cô nói: Không có hai bố con, một mình cô thật sự chuyển không xong."], [94.904, 100.668, "爸爸说：王阿姨住在楼上，我们帮忙是对的。", "Bà Ba Shuō: Wáng Ā Yí Zhù Zài Lóu Shàng, Wǒ Men Bāng Máng Shì Duì De.", "Bố nói: Cô Vương ở tầng trên, chúng ta giúp là đúng."], [100.668, 103.696, "她送给我们一些水果。", "Tā Sòng Gěi Wǒ Men Yì Xiē Shuǐ Guǒ.", "Cô đưa chúng tôi một ít hoa quả."], [103.7, 107.568, "水果很甜，我们吃得很开心。", "Shuǐ Guǒ Hěn Tián, Wǒ Men Chī Dé Hěn Kāi Xīn.", "Hoa quả rất ngọt, chúng tôi ăn rất vui."], [107.568, 112.18, "回家以后，我跟妈妈说了今天的事。", "Huí Jiā Yǐ Hòu, Wǒ Gēn Mā Ma Shuō Le Jīn Tiān De Shì.", "Về nhà, tôi kể cho mẹ chuyện hôm nay."], [112.18, 115.808, "妈妈说：你今天做得很好。", "Mā Ma Shuō: Nǐ Jīn Tiān Zuò Dé Hěn Hǎo.", "Mẹ nói: Hôm nay con làm rất tốt."], [115.833, 122.293, "晚上，王阿姨在门口跟我们说：“你们也早点儿休息吧。”", "Wǎn Shàng, Wáng Ā Yí Zài Mén Kǒu Gēn Wǒ Men Shuō: “Nǐ Men Yě Zǎo Diǎn Ér Xiū Xi Ba.”", "Buổi tối, cô Vương ở trước cửa nói với chúng tôi: “Mọi người cũng nghỉ sớm nhé.”"], [122.293, 126.785, "我想，以后她有事，我们还会帮忙。", "Wǒ Xiǎng, Yǐ Hòu Tā Yǒu Shì, Wǒ Men Hái Huì Bāng Máng.", "Tôi nghĩ, sau này cô có việc, chúng tôi vẫn sẽ giúp."], [126.785, 132.643, "那天晚上，我很累，八点就睡了，睡得很好。", "Nà Tiān Wǎn Shàng, Wǒ Hěn Lèi, Bā Diǎn Jiù Shuì Le, Shuì Dé Hěn Hǎo.", "Tối hôm đó, tôi rất mệt, tám giờ đã đi ngủ và ngủ rất ngon."]]}, "hsk2-21": {"dur": 135.66, "cues": [[7.173, 9.337, "你喜欢看书吗？", "Nǐ Xǐ Huan Kàn Shū Ma?", "Bạn có thích đọc sách không?"], [9.337, 13.925, "星期六下午，同学张文给我打电话。", "Xīng Qī Liù Xià Wǔ, Tóng Xué Zhāng Wén Gěi Wǒ Dǎ Diàn Huà.", "Chiều thứ Bảy, bạn học Trương Văn gọi điện cho tôi."], [13.925, 17.697, "他说想跟我一起去图书馆看书。", "Tā Shuō Xiǎng Gēn Wǒ Yì Qǐ Qù Tú Shū Guǎn Kàn Shū.", "Bạn nói muốn cùng tôi đến thư viện đọc sách."], [17.706, 22.319, "我问他想几点去，他说三点很好。", "Wǒ Wèn Tā Xiǎng Jǐ Diǎn Qù, Tā Shuō Sān Diǎn Hěn Hǎo.", "Tôi hỏi bạn muốn đi mấy giờ, bạn nói ba giờ là tốt."], [22.319, 26.186, "我们约好三点在学校门口见面。", "Wǒ Men Yuē Hǎo Sān Diǎn Zài Xué Xiào Mén Kǒu Jiàn Miàn.", "Chúng tôi hẹn ba giờ gặp ở cổng trường."], [26.206, 30.434, "我很高兴，两点半就到了学校门口。", "Wǒ Hěn Gāo Xìng, Liǎng Diǎn Bàn Jiù Dào Le Xué Xiào Mén Kǒu.", "Tôi rất vui, hai giờ rưỡi đã đến cổng trường."], [30.434, 33.986, "同学还没来，我有点儿担心。", "Tóng Xué Hái Méi Lái, Wǒ Yǒu Yì Diǎn Ér Dān Xīn.", "Bạn chưa đến, tôi hơi lo."], [33.986, 38.502, "后来他跑着来了，说路上人很多。", "Hòu Lái Tā Pǎo Zhe Lái Le, Shuō Lù Shàng Rén Hěn Duō.", "Sau đó bạn chạy đến, nói trên đường đông người."], [38.502, 42.13, "他说：“对不起，我来晚了。”", "Tā Shuō: “Duì Bu Qǐ, Wǒ Lái Wǎn Le.”", "Bạn nói: “Xin lỗi, tớ đến muộn.”"], [42.13, 45.734, "我说没关系，我们一起走吧。", "Wǒ Shuō Méi Guān Xì, Wǒ Men Yì Qǐ Zǒu Ba.", "Tôi nói không sao, chúng ta cùng đi thôi."], [45.754, 49.261, "图书馆里人不多，很安静。", "Tú Shū Guǎn Lǐ Rén Bú Duō, Hěn Ān Jìng.", "Trong thư viện không đông, rất yên tĩnh."], [49.261, 51.642, "我们先去找书。", "Wǒ Men Xiān Qù Zhǎo Shū.", "Chúng tôi đi tìm sách trước."], [51.654, 54.562, "我先借了一本汉语书。", "Wǒ Xiān Jiè Le Yì Běn Hàn Yǔ Shū.", "Tôi mượn trước một quyển sách tiếng Trung."], [54.562, 58.953, "张文借了一本他找了很久的故事书。", "Zhāng Wén Jiè Le Yì Běn Tā Zhǎo Le Hěn Jiǔ De Gù Shì Shū.", "Trương Văn mượn được một cuốn truyện mà bạn ấy tìm đã lâu."], [58.953, 62.365, "我们坐在一起看了两个小时。", "Wǒ Men Zuò Zài Yì Qǐ Kàn Le Liǎng Gè Xiǎo Shí.", "Chúng tôi ngồi cạnh nhau đọc hai tiếng."], [62.365, 66.042, "有不懂的字，他就小声教我。", "Yǒu Bù Dǒng De Zì, Tā Jiù Xiǎo Shēng Jiāo Wǒ.", "Chữ không hiểu thì bạn nhỏ giọng dạy tôi."], [66.053, 69.25, "我也告诉他一个我懂的字。", "Wǒ Yě Gào Su Tā Yí Gè Wǒ Dǒng De Zì.", "Tôi cũng chỉ cho bạn một chữ tôi hiểu."], [69.25, 72.709, "他听了以后说我学得很快。", "Tā Tīng Le Yǐ Hòu Shuō Wǒ Xué De Hěn Kuài.", "Bạn nghe xong nói tôi học rất nhanh."], [72.72, 76.204, "看书的时候，我们都不说话。", "Kàn Shū De Shí Hòu, Wǒ Men Dōu Bù Shuō Huà.", "Lúc đọc sách, chúng tôi đều không nói chuyện."], [76.204, 80.286, "因为这里很安静，大家都在学习。", "Yīn Wèi Zhè Lǐ Hěn Ān Jìng, Dà Jiā Dōu Zài Xué Xí.", "Vì ở đây rất yên tĩnh, mọi người đều đang học."], [80.286, 84.346, "后来我想喝水，可是我没有带水。", "Hòu Lái Wǒ Xiǎng Hē Shuǐ, Kě Shì Wǒ Méi Yǒu Dài Shuǐ.", "Sau đó tôi muốn uống nước, nhưng tôi không mang nước."], [84.346, 87.831, "同学把他的水给我喝了一点儿。", "Tóng Xué Bǎ Tā De Shuǐ Gěi Wǒ Hē Le Yì Diǎn Ér.", "Bạn đưa nước của bạn cho tôi uống một chút."], [87.831, 92.683, "我对他说谢谢，他笑着说：“没关系。”", "Wǒ Duì Tā Shuō Xiè Xiè, Tā Xiào Zhe Shuō: “Méi Guān Xì.”", "Tôi nói cảm ơn, bạn cười nói: “Không sao đâu.”"], [92.686, 96.722, "五点图书馆关门，我们按时离开。", "Wǔ Diǎn Tú Shū Guǎn Guān Mén, Wǒ Men Àn Shí Lí Kāi.", "Năm giờ thư viện đóng cửa, chúng tôi về đúng giờ."], [96.722, 100.614, "走出图书馆，外面已经很晚了。", "Zǒu Chū Tú Shū Guǎn, Wài Miàn Yǐ Jīng Hěn Wǎn Le.", "Ra khỏi thư viện, bên ngoài đã muộn rồi."], [100.614, 105.466, "我问他今天看书高兴吗，他说很高兴。", "Wǒ Wèn Tā Jīn Tiān Kàn Shū Gāo Xìng Ma, Tā Shuō Hěn Gāo Xìng.", "Tôi hỏi bạn hôm nay đọc sách có vui không, bạn nói rất vui."], [105.466, 109.167, "回家以后我觉得今天学了很多。", "Huí Jiā Yǐ Hòu Wǒ Jué De Jīn Tiān Xué Le Hěn Duō.", "Về nhà tôi thấy hôm nay học được rất nhiều."], [109.167, 112.578, "我把今天学的字又看了一次。", "Wǒ Bǎ Jīn Tiān Xué De Zì Yòu Kàn Le Yí Cì.", "Tôi xem lại một lần những chữ học hôm nay."], [112.601, 116.156, "他说下个星期六还想一起去。", "Tā Shuō Xià Gè Xīng Qī Liù Hái Xiǎng Yì Qǐ Qù.", "Bạn nói thứ Bảy sau vẫn muốn đi cùng."], [116.156, 120.264, "我高兴地说，那我们再做一次计划。", "Wǒ Gāo Xìng De Shuō, Nà Wǒ Men Zài Zuò Yí Cì Jì Huà.", "Tôi vui nói vậy thì ta lập kế hoạch lần nữa."], [120.264, 125.5, "今天，我不只看了书，还多了一个好朋友。", "Jīn Tiān, Wǒ Bù Zhǐ Kàn Le Shū, Hái Duō Le Yí Gè Hǎo Péng Yǒu.", "Hôm nay, tôi không chỉ đọc sách, mà còn có thêm một người bạn tốt."]]}, "hsk2-22": {"dur": 144.1, "cues": [[7.425, 11.221, "生病的时候，谁对你最好呢？", "Shēng Bìng De Shí Hòu, Shéi Duì Nǐ Zuì Hǎo Ne?", "Khi ốm, ai đối xử tốt nhất với bạn nhỉ?"], [11.221, 15.761, "今天早上我感冒了，身体不太舒服。", "Jīn Tiān Zǎo Shàng Wǒ Gǎn Mào Le, Shēn Tǐ Bú Tài Shū Fu.", "Sáng nay tôi bị cảm, người hơi không khỏe."], [15.761, 19.173, "我起来以后，头有一点儿痛。", "Wǒ Qǐ Lái Yǐ Hòu, Tóu Yǒu Yì Diǎn Ér Tòng.", "Tôi dậy rồi thấy đầu hơi đau."], [19.192, 22.868, "我不想吃饭，只想躺在家里。", "Wǒ Bù Xiǎng Chī Fàn, Zhǐ Xiǎng Tǎng Zài Jiā Lǐ.", "Tôi không muốn ăn, chỉ muốn nằm ở nhà."], [22.868, 26.688, "妈妈走进我的房间，问我怎么了。", "Mā Ma Zǒu Jìn Wǒ De Fáng Jiān, Wèn Wǒ Zěn Me Le.", "Mẹ bước vào phòng tôi, hỏi tôi sao vậy."], [26.688, 30.7, "我小声说，我的身体很不舒服。", "Wǒ Xiǎo Shēng Shuō, Wǒ De Shēn Tǐ Hěn Bù Shū Fu.", "Tôi nhỏ giọng nói người tôi rất khó chịu."], [30.725, 34.857, "妈妈说我有点儿热，让我别出门。", "Mā Ma Shuō Wǒ Yǒu Yì Diǎn Ér Rè, Ràng Wǒ Bié Chū Mén.", "Mẹ nói tôi hơi nóng và bảo đừng ra ngoài."], [34.857, 38.773, "她看了看我，说我要好好休息。", "Tā Kàn Le Kàn Wǒ, Shuō Wǒ Yào Hǎo Hǎo Xiū Xi.", "Mẹ nhìn tôi, nói tôi phải nghỉ ngơi cho tốt."], [38.773, 42.205, "她给我热水，也让我吃药。", "Tā Gěi Wǒ Rè Shuǐ, Yě Ràng Wǒ Chī Yào.", "Mẹ cho nước nóng và bảo uống thuốc."], [42.205, 45.929, "我问妈妈，吃药以后会好吗？", "Wǒ Wèn Mā Ma, Chī Yào Yǐ Hòu Huì Hǎo Ma?", "Tôi hỏi mẹ, uống thuốc rồi sẽ đỡ chứ ạ?"], [45.929, 49.773, "妈妈笑着说，吃了药就会好的。", "Mā Ma Xiào Zhe Shuō, Chī Le Yào Jiù Huì Hǎo De.", "Mẹ cười nói uống thuốc rồi sẽ đỡ thôi."], [49.773, 54.045, "我听妈妈的话，先喝水，再吃药。", "Wǒ Tīng Mā Ma De Huà, Xiān Hē Shuǐ, Zài Chī Yào.", "Tôi nghe lời mẹ, uống nước trước rồi uống thuốc."], [54.045, 57.889, "我睡了一下午，醒来好一点儿了。", "Wǒ Shuì Le Yí Xià Wǔ, Xǐng Lái Hǎo Yì Diǎn Ér Le.", "Tôi ngủ buổi chiều, tỉnh dậy đỡ hơn."], [57.889, 61.829, "醒来以后，我觉得没有那么热了。", "Xǐng Lái Yǐ Hòu, Wǒ Jué De Méi Yǒu Nà Me Rè Le.", "Tỉnh dậy, tôi thấy không còn nóng như trước."], [61.829, 65.913, "可是我还是不想吃饭，只想睡觉。", "Kě Shì Wǒ Hái Shì Bù Xiǎng Chī Fàn, Zhǐ Xiǎng Shuì Jiào.", "Nhưng tôi vẫn không muốn ăn, chỉ muốn ngủ."], [65.945, 69.645, "妈妈做了一点儿我喜欢吃的东西。", "Mā Ma Zuò Le Yì Diǎn Ér Wǒ Xǐ Huan Chī De Dōng Xi.", "Mẹ làm một ít món tôi thích ăn."], [69.645, 73.273, "我慢慢吃了一点儿，觉得好多了。", "Wǒ Màn Màn Chī Le Yì Diǎn Ér, Jué De Hǎo Duō Le.", "Tôi ăn chậm một chút, thấy đỡ nhiều rồi."], [73.278, 76.378, "晚上爸爸问我好点了吗。", "Wǎn Shàng Bà Ba Wèn Wǒ Hǎo Diǎn Le Ma.", "Tối bố hỏi đỡ chưa."], [76.378, 80.246, "我回答说，比早上好一点儿了。", "Wǒ Huí Dá Shuō, Bǐ Zǎo Shàng Hǎo Yì Diǎn Ér Le.", "Tôi trả lời là đỡ hơn buổi sáng một chút rồi."], [80.246, 83.37, "我说还想早点儿睡觉。", "Wǒ Shuō Hái Xiǎng Zǎo Yì Diǎn Ér Shuì Jiào.", "Tôi nói vẫn muốn ngủ sớm."], [83.378, 88.206, "爸爸说，睡得好，身体就好得快。", "Bà Ba Shuō, Shuì De Hǎo, Shēn Tǐ Jiù Hǎo De Kuài.", "Bố nói ngủ ngon thì người sẽ mau khỏe."], [88.206, 92.146, "妈妈说明天还不好，就去医院。", "Mā Ma Shuō Míng Tiān Hái Bù Hǎo, Jiù Qù Yī Yuàn.", "Mẹ nói mai mà còn không khỏe thì đi bệnh viện."], [92.148, 96.28, "我有点儿担心，因为我不想去医院。", "Wǒ Yǒu Yì Diǎn Ér Dān Xīn, Yīn Wèi Wǒ Bù Xiǎng Qù Yī Yuàn.", "Tôi hơi lo vì tôi không muốn đi bệnh viện."], [96.28, 100.412, "妈妈说不用担心，先好好休息。", "Mā Ma Shuō Bú Yòng Dān Xīn, Xiān Hǎo Hǎo Xiū Xi.", "Mẹ nói đừng lo, cứ nghỉ ngơi cho tốt trước."], [100.412, 103.872, "我点点头，要好好休息。", "Wǒ Diǎn Diǎn Tóu, Yào Hǎo Hǎo Xiū Xi.", "Tôi gật đầu, cần nghỉ cho khỏe."], [103.882, 107.606, "那天晚上，我很早就睡觉了。", "Nà Tiān Wǎn Shàng, Wǒ Hěn Zǎo Jiù Shuì Jiào Le.", "Tối hôm đó tôi đi ngủ rất sớm."], [107.606, 111.402, "第二天早上我又能去上课了。", "Dì Èr Tiān Zǎo Shàng Wǒ Yòu Néng Qù Shàng Kè Le.", "Sáng hôm sau tôi lại đi học được."], [111.415, 115.691, "到了学校，同学问我昨天怎么没来。", "Dào Le Xué Xiào, Tóng Xué Wèn Wǒ Zuó Tiān Zěn Me Méi Lái.", "Đến trường, bạn học hỏi sao hôm qua tôi không đến."], [115.691, 122.031, "我告诉他们我感冒了，同学们说：“你回来了，太好了！”", "Wǒ Gào Sù Tā Men Wǒ Gǎn Mào Le, Tóng Xué Men Shuō: “Nǐ Huí Lái Le, Tài Hǎo Le!”", "Tôi bảo các bạn là tôi bị cảm, các bạn nói: “Bạn quay lại rồi, tốt quá!”"], [122.048, 128.1, "晚上，我给妈妈一杯热水，说：“妈妈，谢谢您。”", "Wǎn Shàng, Wǒ Gěi Mā Ma Yì Bēi Rè Shuǐ, Shuō: “Mā Ma, Xiè Xie Nín.”", "Buổi tối, tôi đưa mẹ một cốc nước nóng và nói: “Mẹ ơi, con cảm ơn mẹ ạ.”"], [128.1, 133.84, "妈妈喝了水，笑着说：“你好了，我很高兴。”", "Mā Ma Hē Le Shuǐ, Xiào Zhe Shuō: “Nǐ Hǎo Le, Wǒ Hěn Gāo Xìng.”", "Mẹ uống nước, cười nói: “Con khỏe rồi, mẹ rất vui.”"]]}, "hsk2-23": {"dur": 138.75, "cues": [[7.208, 11.1, "你搬过家吗？搬家又累又开心。", "Nǐ Bān Guò Jiā Ma? Bān Jiā Yòu Lèi Yòu Kāi Xīn.", "Bạn đã chuyển nhà bao giờ chưa? Chuyển nhà vừa mệt vừa vui."], [11.1, 14.416, "这个星期六我们家要搬家。", "Zhè Ge Xīng Qī Liù Wǒ Men Jiā Yào Bān Jiā.", "Thứ Bảy này nhà tôi chuyển nhà."], [14.416, 18.404, "星期五晚上，我们就开始准备了。", "Xīng Qī Wǔ Wǎn Shàng, Wǒ Men Jiù Kāi Shǐ Zhǔn Bèi Le.", "Tối thứ Sáu chúng tôi đã bắt đầu chuẩn bị."], [18.408, 22.06, "早上爸爸、妈妈和我都很忙。", "Zǎo Shàng Bà Ba, Mā Ma Hé Wǒ Dōu Hěn Máng.", "Sáng bố, mẹ và tôi đều bận."], [22.06, 26.0, "爸爸说，我们先把小东西放好。", "Bà Ba Shuō, Wǒ Men Xiān Bǎ Xiǎo Dōng Xi Fàng Hǎo.", "Bố nói chúng ta xếp đồ nhỏ gọn trước."], [26.0, 29.34, "我们把衣服和书放进箱子。", "Wǒ Men Bǎ Yī Fu Hé Shū Fàng Jìn Xiāng Zi.", "Chúng tôi cho quần áo và sách vào thùng."], [29.341, 33.089, "我的书很多，我用了两个箱子。", "Wǒ De Shū Hěn Duō, Wǒ Yòng Le Liǎng Gè Xiāng Zi.", "Sách của tôi nhiều, tôi dùng hai thùng."], [33.089, 36.837, "妈妈告诉我，别把书放得太多。", "Mā Ma Gào Su Wǒ, Bié Bǎ Shū Fàng De Tài Duō.", "Mẹ bảo tôi đừng cho sách vào nhiều quá."], [36.841, 40.157, "哥哥开车来帮我们搬东西。", "Gē Ge Kāi Chē Lái Bāng Wǒ Men Bān Dōng Xi.", "Anh trai lái xe giúp chuyển đồ."], [40.157, 44.337, "哥哥说，新家的房间比旧家大。", "Gē Ge Shuō, Xīn Jiā De Fáng Jiān Bǐ Jiù Jiā Dà.", "Anh nói phòng ở nhà mới to hơn nhà cũ."], [44.337, 48.517, "我听了很高兴，想快一点儿去看看。", "Wǒ Tīng Le Hěn Gāo Xìng, Xiǎng Kuài Yì Diǎn Ér Qù Kàn Kan.", "Tôi nghe xong rất vui, muốn nhanh đến xem."], [48.541, 52.577, "旧家离新家不远，走了很多次。", "Jiù Jiā Lí Xīn Jiā Bù Yuǎn, Zǒu Le Hěn Duō Cì.", "Nhà cũ cách nhà mới không xa, đi lại nhiều lần."], [52.577, 56.277, "可是东西很多，我们还是很累。", "Kě Shì Dōng Xi Hěn Duō, Wǒ Men Hái Shì Hěn Lèi.", "Nhưng đồ nhiều nên chúng tôi vẫn rất mệt."], [56.281, 60.893, "路上我的一个箱子开了，书都出来了。", "Lù Shàng Wǒ De Yí Gè Xiāng Zi Kāi Le, Shū Dōu Chū Lái Le.", "Giữa đường một thùng của tôi bị mở, sách rơi ra hết."], [60.893, 65.505, "我有点儿担心，哥哥笑着说没关系。", "Wǒ Yǒu Yì Diǎn Ér Dān Xīn, Gē Ge Xiào Zhe Shuō Méi Guān Xì.", "Tôi hơi lo, anh cười nói không sao."], [65.505, 68.749, "我们把书一本一本放回去。", "Wǒ Men Bǎ Shū Yì Běn Yì Běn Fàng Huí Qù.", "Chúng tôi xếp sách từng quyển trở lại."], [68.781, 72.649, "中午在外面吃饭，休息一会儿。", "Zhōng Wǔ Zài Wài Miàn Chī Fàn, Xiū Xi Yí Huì Er.", "Trưa ăn ngoài và nghỉ một lát."], [72.649, 77.117, "吃饭的时候，爸爸说下午还要搬两次。", "Chī Fàn De Shí Hòu, Bà Ba Shuō Xià Wǔ Hái Yào Bān Liǎng Cì.", "Lúc ăn cơm, bố nói chiều còn phải chuyển hai chuyến nữa."], [77.121, 80.749, "下午我开始收拾自己的房间。", "Xià Wǔ Wǒ Kāi Shǐ Shōu Shi Zì Jǐ De Fáng Jiān.", "Chiều tôi bắt đầu dọn phòng mình."], [80.749, 84.281, "我的新房间很大，也很安静。", "Wǒ De Xīn Fáng Jiān Hěn Dà, Yě Hěn Ān Jìng.", "Phòng mới của tôi rất rộng và yên tĩnh."], [84.281, 88.869, "我先把书放在桌子上，再放衣服。", "Wǒ Xiān Bǎ Shū Fàng Zài Zhuō Zi Shàng, Zài Fàng Yī Fu.", "Tôi để sách lên bàn trước, rồi mới xếp quần áo."], [88.888, 92.804, "妈妈做饭，爸爸擦桌子和椅子。", "Mā Ma Zuò Fàn, Bà Ba Cā Zhuō Zi Hé Yǐ Zi.", "Mẹ nấu cơm, bố lau bàn và ghế."], [92.804, 96.816, "哥哥帮我收拾房间，他做了很多。", "Gē Ge Bāng Wǒ Shōu Shi Fáng Jiān, Tā Zuò Le Hěn Duō.", "Anh giúp tôi dọn phòng, anh làm rất nhiều."], [96.816, 101.668, "爸爸坐在箱子上休息，妈妈给他水喝。", "Bà Ba Zuò Zài Xiāng Zi Shàng Xiū Xi, Mā Ma Gěi Tā Shuǐ Hē.", "Bố ngồi trên chiếc thùng nghỉ ngơi, mẹ đưa nước cho bố uống."], [101.668, 105.704, "虽然很累，我觉得新家很舒服。", "Suī Rán Hěn Lèi, Wǒ Jué De Xīn Jiā Hěn Shū Fu.", "Dù mệt nhưng tôi thấy nhà mới thoải mái."], [105.704, 110.028, "晚上吃饭的时候，我说我喜欢新家。", "Wǎn Shàng Chī Fàn De Shí Hòu, Wǒ Shuō Wǒ Xǐ Huan Xīn Jiā.", "Lúc ăn tối, tôi nói tôi thích nhà mới."], [110.035, 112.871, "晚上我们一起看电视。", "Wǎn Shàng Wǒ Men Yì Qǐ Kàn Diàn Shì.", "Tối cả nhà xem ti vi."], [112.871, 116.811, "看电视的时候，妈妈给我们倒茶。", "Kàn Diàn Shì De Shí Hòu, Mā Ma Gěi Wǒ Men Dào Chá.", "Lúc xem ti vi, mẹ rót trà cho chúng tôi."], [116.811, 120.943, "爸爸说，明天我们还要买一些东西。", "Bà Ba Shuō, Míng Tiān Wǒ Men Hái Yào Mǎi Yì Xiē Dōng Xi.", "Bố nói ngày mai chúng tôi còn phải mua một ít đồ."], [120.968, 124.692, "搬家很累，可是我也很开心。", "Bān Jiā Hěn Lèi, Kě Shì Wǒ Yě Hěn Kāi Xīn.", "Chuyển nhà rất vất vả nhưng tôi cũng rất vui."], [124.692, 128.56, "我想，以后在这里会很开心的。", "Wǒ Xiǎng, Yǐ Hòu Zài Zhè Lǐ Huì Hěn Kāi Xīn De.", "Tôi nghĩ sau này sống ở đây sẽ rất vui."]]}, "hsk2-24": {"dur": 134.65, "cues": [[7.448, 11.364, "你会骑自行车吗？我以前不会。", "Nǐ Huì Qí Zì Xíng Chē Ma? Wǒ Yǐ Qián Bú Huì.", "Bạn có biết đi xe đạp không? Trước đây tôi không biết."], [11.364, 15.496, "去年春天爸爸教我学骑自行车。", "Qù Nián Chūn Tiān Bà Ba Jiāo Wǒ Xué Qí Zì Xíng Chē.", "Mùa xuân năm ngoái bố dạy tôi đi xe đạp."], [15.496, 20.372, "爸爸说，骑车很好玩儿，也很方便。", "Bà Ba Shuō, Qí Chē Hěn Hǎo Wánr, Yě Hěn Fāng Biàn.", "Bố nói đạp xe rất vui và cũng tiện."], [20.381, 24.249, "我想学，可是我又有点儿害怕。", "Wǒ Xiǎng Xué, Kě Shì Wǒ Yòu Yǒu Yì Diǎn Ér Hài Pà.", "Tôi muốn học, nhưng tôi lại hơi sợ."], [24.249, 28.141, "一开始我很害怕，车总是倒。", "Yì Kāi Shǐ Wǒ Hěn Hài Pà, Chē Zǒng Shì Dǎo.", "Lúc đầu tôi sợ, xe cứ ngã."], [28.148, 32.568, "爸爸告诉我，不要看下面，要看前面。", "Bà Ba Gào Su Wǒ, Bú Yào Kàn Xià Miàn, Yào Kàn Qián Miàn.", "Bố bảo tôi đừng nhìn xuống, hãy nhìn phía trước."], [32.568, 35.932, "爸爸扶着车，让我练习。", "Bà Ba Fú Zhe Chē, Ràng Wǒ Liàn Xí.", "Bố đỡ xe, bảo tôi luyện tập."], [35.932, 39.824, "我慢慢骑，爸爸在后面跟着我。", "Wǒ Màn Màn Qí, Bà Ba Zài Hòu Miàn Gēn Zhe Wǒ.", "Tôi đạp chậm, bố đi theo phía sau tôi."], [39.848, 43.956, "我每天下午在公园练半个小时。", "Wǒ Měi Tiān Xià Wǔ Zài Gōng Yuán Liàn Bàn Gè Xiǎo Shí.", "Mỗi chiều tôi tập nửa tiếng ở công viên."], [43.956, 47.848, "有时候朋友也来公园看我练习。", "Yǒu Shí Hòu Péng Yǒu Yě Lái Gōng Yuán Kàn Wǒ Liàn Xí.", "Có lúc bạn cũng đến công viên xem tôi tập."], [47.848, 51.476, "摔了几次，膝盖有一点儿痛。", "Shuāi Le Jǐ Cì, Xī Gài Yǒu Yì Diǎn Ér Tòng.", "Ngã vài lần, đầu gối hơi đau."], [51.476, 54.768, "我想回家，不想再练了。", "Wǒ Xiǎng Huí Jiā, Bù Xiǎng Zài Liàn Le.", "Tôi muốn về nhà, không muốn tập nữa."], [54.768, 58.276, "爸爸问我，为什么不想练了。", "Bà Ba Wèn Wǒ, Wèi Shén Me Bù Xiǎng Liàn Le.", "Bố hỏi tôi sao không muốn tập nữa."], [58.281, 62.293, "我说我怕再摔，膝盖还会痛。", "Wǒ Shuō Wǒ Pà Zài Shuāi, Xī Gài Hái Huì Tòng.", "Tôi nói tôi sợ ngã nữa, đầu gối sẽ lại đau."], [62.293, 65.921, "爸爸说要勇敢，别骑太快。", "Bà Ba Shuō Yào Yǒng Gǎn, Bié Qí Tài Kuài.", "Bố nói phải dũng cảm, đừng đi quá nhanh."], [65.921, 69.837, "听了爸爸的话，我又开始练习了。", "Tīng Le Bà Ba De Huà, Wǒ Yòu Kāi Shǐ Liàn Xí Le.", "Nghe lời bố, tôi lại bắt đầu tập."], [69.837, 73.585, "一星期后我能骑一小段路了。", "Yì Xīng Qī Hòu Wǒ Néng Qí Yí Xiǎo Duàn Lù Le.", "Một tuần sau tôi đi được một đoạn ngắn."], [73.588, 78.368, "那天爸爸没有扶车，我自己骑了很远。", "Nà Tiān Bà Ba Méi Yǒu Fú Chē, Wǒ Zì Jǐ Qí Le Hěn Yuǎn.", "Hôm đó bố không đỡ xe, tôi tự đạp được rất xa."], [78.368, 81.828, "我高兴地说：“我会骑车了！”", "Wǒ Gāo Xìng De Shuō: “Wǒ Huì Qí Chē Le!”", "Tôi vui mừng nói: “Con biết đi xe đạp rồi!”"], [81.828, 85.072, "他又教我转弯和停车。", "Tā Yòu Jiāo Wǒ Zhuǎn Wān Hé Tíng Chē.", "Bố dạy thêm rẽ và dừng xe."], [85.072, 89.012, "转弯的时候，我还是有点儿紧张。", "Zhuǎn Wān De Shí Hòu, Wǒ Hái Shì Yǒu Yì Diǎn Ér Jǐn Zhāng.", "Lúc rẽ, tôi vẫn hơi căng thẳng."], [89.012, 92.928, "爸爸说，先慢一点儿，再转弯。", "Bà Ba Shuō, Xiān Màn Yì Diǎn Ér, Zài Zhuǎn Wān.", "Bố nói chậm lại một chút trước, rồi mới rẽ."], [92.928, 96.628, "练了几次以后，我就不紧张了。", "Liàn Le Jǐ Cì Yǐ Hòu, Wǒ Jiù Bù Jǐn Zhāng Le.", "Tập vài lần rồi, tôi không căng thẳng nữa."], [96.628, 101.216, "现在星期六我常跟朋友骑车去公园。", "Xiàn Zài Xīng Qī Liù Wǒ Cháng Gēn Péng Yǒu Qí Chē Qù Gōng Yuán.", "Giờ thứ Bảy tôi thường cùng bạn đạp xe ra công viên."], [101.216, 104.916, "朋友说我骑得比以前快多了。", "Péng Yǒu Shuō Wǒ Qí De Bǐ Yǐ Qián Kuài Duō Le.", "Bạn nói tôi đạp nhanh hơn trước nhiều."], [104.928, 108.508, "我们在公园一起玩儿，很高兴。", "Wǒ Men Zài Gōng Yuán Yì Qǐ Wánr, Hěn Gāo Xìng.", "Chúng tôi chơi cùng nhau ở công viên, rất vui."], [108.508, 111.92, "我觉得骑车又方便又快。", "Wǒ Jué De Qí Chē Yòu Fāng Biàn Yòu Kuài.", "Tôi thấy đạp xe vừa tiện vừa nhanh."], [111.92, 116.028, "如果天气好，我们每个星期都去。", "Rú Guǒ Tiān Qì Hǎo, Wǒ Men Měi Gè Xīng Qī Dōu Qù.", "Nếu trời đẹp, tuần nào chúng tôi cũng đi."], [116.028, 119.584, "我很想谢谢耐心教我的爸爸。", "Wǒ Hěn Xiǎng Xiè Xiè Nài Xīn Jiāo Wǒ De Bà Ba.", "Tôi rất muốn cảm ơn bố đã kiên nhẫn dạy."], [119.584, 124.484, "爸爸笑着说，你学会了，我最高兴。", "Bà Ba Xiào Zhe Shuō, Nǐ Xué Huì Le, Wǒ Zuì Gāo Xìng.", "Bố cười nói con học được rồi là bố vui nhất."]]}, "hsk2-25": {"dur": 142.01, "cues": [[8.223, 12.523, "你去过爸爸的公司吗？里面有意思吗？", "Nǐ Qù Guò Bà Ba De Gōng Sī Ma? Lǐ Miàn Yǒu Yì Si Ma?", "Bạn đã đến công ty của bố bao giờ chưa? Ở đó có thú vị không?"], [12.523, 15.767, "星期一爸爸带我去公司。", "Xīng Qī Yī Bà Ba Dài Wǒ Qù Gōng Sī.", "Thứ Hai bố đưa tôi đến công ty."], [15.767, 20.423, "爸爸说，今天公司有一件高兴的事情。", "Bà Ba Shuō, Jīn Tiān Gōng Sī Yǒu Yí Jiàn Gāo Xìng De Shì Qing.", "Bố nói hôm nay công ty có một chuyện vui."], [20.423, 23.931, "他说今天有新同事来上班。", "Tā Shuō Jīn Tiān Yǒu Xīn Tóng Shì Lái Shàng Bān.", "Bố nói hôm nay có đồng nghiệp mới đi làm."], [23.931, 28.519, "我问爸爸，新同事是男的还是女的。", "Wǒ Wèn Bà Ba, Xīn Tóng Shì Shì Nán De Hái Shì Nǚ De.", "Tôi hỏi bố đồng nghiệp mới là nam hay nữ."], [28.519, 32.433, "爸爸笑着说，你一会儿就知道了。", "Bà Ba Xiào Zhe Shuō, Nǐ Yí Huì Er Jiù Zhī Dào Le.", "Bố cười nói một lát con sẽ biết."], [32.433, 36.277, "新同事叫小张，说话很清楚。", "Xīn Tóng Shì Jiào Xiǎo Zhāng, Shuō Huà Hěn Qīng Chu.", "Người mới tên Tiểu Trương, nói rất rõ."], [36.277, 40.169, "小张看见我，笑着问我叫什么。", "Xiǎo Zhāng Kàn Jiàn Wǒ, Xiào Zhe Wèn Wǒ Jiào Shén Me.", "Tiểu Trương thấy tôi, cười hỏi tôi tên gì."], [40.169, 45.141, "我告诉他我的名字，他说名字很好听。", "Wǒ Gào Su Tā Wǒ De Míng Zi, Tā Shuō Míng Zi Hěn Hǎo Tīng.", "Tôi cho anh biết tên tôi, anh nói tên rất hay."], [45.166, 48.41, "爸爸让他坐在电脑旁边。", "Bà Ba Ràng Tā Zuò Zài Diàn Nǎo Páng Biān.", "Bố bảo anh ngồi cạnh máy tính."], [48.41, 52.998, "一开始小张有点儿紧张，不太说话。", "Yì Kāi Shǐ Xiǎo Zhāng Yǒu Yì Diǎn Ér Jǐn Zhāng, Bú Tài Shuō Huà.", "Lúc đầu Tiểu Trương hơi căng thẳng, ít nói."], [52.998, 57.514, "爸爸告诉他，不用紧张，大家都很好。", "Bà Ba Gào Su Tā, Bú Yòng Jǐn Zhāng, Dà Jiā Dōu Hěn Hǎo.", "Bố bảo anh đừng căng thẳng, mọi người đều rất tốt."], [57.533, 61.425, "我给他们倒茶，他们对我说谢谢。", "Wǒ Gěi Tā Men Dào Chá, Tā Men Duì Wǒ Shuō Xiè Xiè.", "Tôi rót trà, họ cảm ơn tôi."], [61.425, 65.053, "小张喝了茶，说茶很好喝。", "Xiǎo Zhāng Hē Le Chá, Shuō Chá Hěn Hǎo Hē.", "Tiểu Trương uống trà, nói trà rất ngon."], [65.066, 68.502, "中午他跟爸爸去饭馆吃饭。", "Zhōng Wǔ Tā Gēn Bà Ba Qù Fàn Guǎn Chī Fàn.", "Trưa anh ăn cơm với bố ở quán."], [68.502, 72.898, "我也跟他们一起去，饭馆离公司不远。", "Wǒ Yě Gēn Tā Men Yì Qǐ Qù, Fàn Guǎn Lí Gōng Sī Bù Yuǎn.", "Tôi cũng đi cùng họ, quán ăn cách công ty không xa."], [72.898, 77.006, "吃饭的时候，小张问了很多问题。", "Chī Fàn De Shí Hòu, Xiǎo Zhāng Wèn Le Hěn Duō Wèn Tí.", "Lúc ăn cơm, Tiểu Trương hỏi nhiều câu hỏi."], [77.006, 80.466, "爸爸都慢慢回答了他的问题。", "Bà Ba Dōu Màn Màn Huí Dá Le Tā De Wèn Tí.", "Bố đều từ từ trả lời các câu hỏi của anh."], [80.466, 83.998, "回公司后，他在桌前工作。", "Huí Gōng Sī Hòu, Tā Zài Zhuō Qián Gōng Zuò.", "Về công ty anh làm việc ở bàn."], [84.006, 87.562, "下午他的电脑忽然有问题了。", "Xià Wǔ Tā De Diàn Nǎo Hū Rán Yǒu Wèn Tí Le.", "Buổi chiều máy tính của anh bỗng có vấn đề."], [87.562, 91.814, "他有点儿担心，问爸爸：“我怎么做？”", "Tā Yǒu Yì Diǎn Ér Dān Xīn, Wèn Bà Ba: “Wǒ Zěn Me Zuò?”", "Anh hơi lo, hỏi bố: “Con phải làm thế nào ạ?”"], [91.814, 96.086, "爸爸看了看，说问题不大，可以做好。", "Bà Ba Kàn Le Kàn, Shuō Wèn Tí Bú Dà, Kě Yǐ Zuò Hǎo.", "Bố xem qua, nói vấn đề không lớn, sửa được."], [96.086, 100.122, "他们一起做了半个小时，电脑好了。", "Tā Men Yì Qǐ Zuò Le Bàn Gè Xiǎo Shí, Diàn Nǎo Hǎo Le.", "Họ cùng làm nửa tiếng, máy tính lại tốt rồi."], [100.122, 103.866, "小张高兴地说，谢谢你教我。", "Xiǎo Zhāng Gāo Xìng De Shuō, Xiè Xiè Nǐ Jiāo Wǒ.", "Tiểu Trương vui nói cảm ơn anh đã chỉ cho tôi."], [103.866, 106.894, "第一天他学东西很快。", "Dì Yī Tiān Tā Xué Dōng Xi Hěn Kuài.", "Ngày đầu anh học rất nhanh."], [106.894, 110.93, "爸爸也说，小张工作做得很好。", "Bà Ba Yě Shuō, Xiǎo Zhāng Gōng Zuò Zuò De Hěn Hǎo.", "Bố cũng nói Tiểu Trương làm việc rất tốt."], [110.933, 114.369, "下班爸爸说他是一个好人。", "Xià Bān Bà Ba Shuō Tā Shì Yí Gè Hǎo Rén.", "Tan làm bố nói anh là người tốt."], [114.369, 118.045, "回家路上爸爸说多了一个朋友。", "Huí Jiā Lù Shàng Bà Ba Shuō Duō Le Yí Gè Péng Yǒu.", "Trên đường về bố nói thêm một người bạn."], [118.066, 122.222, "我问爸爸，小张明天还来上班吗。", "Wǒ Wèn Bà Ba, Xiǎo Zhāng Míng Tiān Hái Lái Shàng Bān Ma.", "Tôi hỏi bố ngày mai Tiểu Trương còn đến làm không."], [122.222, 128.106, "爸爸笑着说：来，他人很好，我们都很喜欢他。", "Bà Ba Xiào Zhe Shuō: Lái, Tā Rén Hěn Hǎo, Wǒ Men Dōu Hěn Xǐ Huan Tā.", "Bố cười nói: Có chứ, cậu ấy rất tốt, mọi người đều quý cậu ấy."], [128.106, 131.734, "我觉得公司比以前热闹了一点儿。", "Wǒ Jué De Gōng Sī Bǐ Yǐ Qián Rè Nao Le Yì Diǎn Ér.", "Tôi thấy công ty đông vui hơn trước một chút."]]}, "hsk2-26": {"dur": 139.78, "cues": [[8.377, 12.941, "星期天早上，妈妈很早就叫我起床。", "Xīng Qī Tiān Zǎo Shàng, Mā Ma Hěn Zǎo Jiù Jiào Wǒ Qǐ Chuáng.", "Sáng chủ nhật, mẹ gọi tôi dậy từ rất sớm."], [12.941, 16.737, "星期天妈妈让我帮忙做家务。", "Xīng Qī Tiān Mā Ma Ràng Wǒ Bāng Máng Zuò Jiā Wù.", "Chủ nhật mẹ nhờ tôi giúp việc nhà."], [16.744, 20.636, "妈妈问我：“你想和我一起做吗？”", "Mā Ma Wèn Wǒ: “Nǐ Xiǎng Hé Wǒ Yì Qǐ Zuò Ma?”", "Mẹ hỏi tôi: \"Con muốn làm cùng mẹ không?\""], [20.636, 24.384, "我说：“想，我先做什么呢？”", "Wǒ Shuō: “Xiǎng, Wǒ Xiān Zuò Shén Me Ne?”", "Tôi nói: \"Muốn ạ, con làm gì trước?\""], [24.384, 28.708, "妈妈告诉我，先扫地，再擦桌子。", "Mā Ma Gào Su Wǒ, Xiān Sǎo Dì, Zài Cā Zhuō Zi.", "Mẹ bảo tôi quét nhà trước, rồi lau bàn."], [28.71, 32.554, "我先扫地，再把桌子擦干净。", "Wǒ Xiān Sǎo Dì, Zài Bǎ Zhuō Zi Cā Gàn Jìng.", "Tôi quét nhà rồi lau bàn sạch."], [32.554, 36.877, "桌子下面有很多东西，我都放好了。", "Zhuō Zi Xià Miàn Yǒu Hěn Duō Dōng Xi, Wǒ Dōu Fàng Hǎo Le.", "Dưới bàn có nhiều đồ, tôi xếp gọn hết."], [36.877, 40.625, "衣服很多，我一个人洗得很慢。", "Yī Fu Hěn Duō, Wǒ Yí Gè Rén Xǐ De Hěn Màn.", "Quần áo nhiều, một mình tôi giặt rất chậm."], [40.625, 44.781, "然后我洗衣服，晾在窗户边。", "Rán Hòu Wǒ Xǐ Yī Fu, Liàng Zài Chuāng Hu Biān.", "Sau đó giặt quần áo, phơi cạnh cửa sổ."], [44.781, 49.105, "妈妈走过来，教我怎么把衣服洗干净。", "Mā Ma Zǒu Guò Lái, Jiào Wǒ Zěn Me Bǎ Yī Fu Xǐ Gān Jìng.", "Mẹ đi lại, dạy tôi giặt quần áo cho sạch."], [49.11, 52.714, "到了中午，我觉得想吃饭了。", "Dào Le Zhōng Wǔ, Wǒ Jué De Xiǎng Chī Fàn Le.", "Đến trưa, tôi thấy muốn ăn cơm rồi."], [52.714, 55.79, "爸爸洗碗，妈妈做饭。", "Bà Ba Xǐ Wǎn, Mā Ma Zuò Fàn.", "Bố rửa bát, mẹ nấu cơm."], [55.81, 59.102, "爸爸问我：“今天累不累？”", "Bà Ba Wèn Wǒ: “Jīn Tiān Lèi Bú Lèi?”", "Bố hỏi tôi: \"Hôm nay có mệt không?\""], [59.102, 63.33, "我回答：“有一点儿累，可是很高兴。”", "Wǒ Huí Dá: “Yǒu Yì Diǎn Ér Lèi, Kě Shì Hěn Gāo Xìng.”", "Tôi trả lời: \"Hơi mệt, nhưng rất vui.\""], [63.33, 67.462, "饭很快就做好了，我们一起吃饭。", "Fàn Hěn Kuài Jiù Zuò Hǎo Le, Wǒ Men Yì Qǐ Chī Fàn.", "Cơm nhanh chóng nấu xong, chúng tôi cùng ăn."], [67.477, 71.465, "吃完午饭，我收拾自己的房间。", "Chī Wán Wǔ Fàn, Wǒ Shōu Shi Zì Jǐ De Fáng Jiān.", "Ăn trưa xong tôi dọn phòng mình."], [71.465, 74.805, "把书和本子放进书包。", "Bǎ Shū Hé Běn Zi Fàng Jìn Shū Bāo.", "Cho sách và vở vào cặp."], [74.805, 78.553, "我的房间不大，可是东西不少。", "Wǒ De Fáng Jiān Bú Dà, Kě Shì Dōng Xi Bù Shǎo.", "Phòng tôi không lớn, nhưng đồ không ít."], [78.577, 82.325, "我把桌子上的书一本一本放好。", "Wǒ Bǎ Zhuō Zi Shàng De Shū Yì Běn Yì Běn Fàng Hǎo.", "Tôi xếp từng cuốn sách trên bàn cho gọn."], [82.325, 86.121, "妈妈走进来，看了看我的房间。", "Mā Ma Zǒu Jìn Lái, Kàn Le Kàn Wǒ De Fáng Jiān.", "Mẹ bước vào, nhìn quanh phòng tôi."], [86.121, 89.605, "妈妈说干净的家很舒服。", "Mā Ma Shuō Gān Jìng De Jiā Hěn Shū Fu.", "Mẹ nói nhà sạch thì thoải mái."], [89.61, 93.454, "我问妈妈：“下午我们还做什么？”", "Wǒ Wèn Mā Ma: “Xià Wǔ Wǒ Men Hái Zuò Shén Me?”", "Tôi hỏi mẹ: \"Chiều chúng ta còn làm gì?\""], [93.454, 96.53, "下午我们一起洗窗户。", "Xià Wǔ Wǒ Men Yì Qǐ Xǐ Chuāng Hu.", "Chiều chúng tôi cùng lau cửa sổ."], [96.53, 100.35, "窗户有点儿高，我洗不到上面。", "Chuāng Hu Yǒu Diǎn Ér Gāo, Wǒ Xǐ Bú Dào Shàng Miàn.", "Cửa sổ hơi cao, tôi lau không tới phía trên."], [100.35, 104.266, "爸爸说：“别担心，我来帮你。”", "Bà Ba Shuō: “Bié Dān Xīn, Wǒ Lái Bāng Nǐ.”", "Bố nói: \"Đừng lo, bố giúp con.\""], [104.266, 108.23, "我们三个人一起，很快就洗完了。", "Wǒ Men Sān Gè Rén Yì Qǐ, Hěn Kuài Jiù Xǐ Wán Le.", "Ba người chúng tôi cùng làm, nhanh chóng lau xong."], [108.25, 112.166, "看着干净的家，我心里很高兴。", "Kàn Zhe Gān Jìng De Jiā, Wǒ Xīn Lǐ Hěn Gāo Xìng.", "Nhìn ngôi nhà sạch sẽ, trong lòng tôi rất vui."], [112.166, 116.058, "虽然有一点儿累，我觉得很有用。", "Suī Rán Yǒu Yì Diǎn Ér Lèi, Wǒ Jué De Hěn Yǒu Yòng.", "Hơi mệt nhưng tôi thấy việc có ích."], [116.06, 120.312, "晚上，我们坐在桌子前一起喝茶。", "Wǎn Shàng, Wǒ Men Zuò Zài Zhuō Zi Qián Yì Qǐ Hē Chá.", "Buổi tối, chúng tôi ngồi bên bàn cùng uống trà."], [120.312, 123.628, "晚上妈妈说我做得不错。", "Wǎn Shàng Mā Ma Shuō Wǒ Zuò De Bù Cuò.", "Tối mẹ nói tôi làm tốt."], [123.628, 129.584, "晚饭后我洗了碗，妈妈笑着说我做得越来越好了。", "Wǎn Fàn Hòu Wǒ Xǐ Le Wǎn, Mā Ma Xiào Zhe Shuō Wǒ Zuò Dé Yuè Lái Yuè Hǎo Le.", "Sau bữa tối tôi rửa bát, mẹ cười nói tôi làm ngày càng tốt hơn."]]}, "hsk2-27": {"dur": 137.22, "cues": [[7.949, 11.961, "你第一次自己点菜的时候，紧张吗？", "Nǐ Dì Yī Cì Zì Jǐ Diǎn Cài De Shí Hòu, Jǐn Zhāng Ma?", "Lần đầu tự gọi món, bạn có hồi hộp không?"], [11.961, 15.253, "昨天晚上朋友请我吃饭。", "Zuó Tiān Wǎn Shàng Péng Yǒu Qǐng Wǒ Chī Fàn.", "Tối qua bạn mời tôi đi ăn."], [15.253, 19.097, "朋友说他知道一家很好的饭馆。", "Péng Yǒu Shuō Tā Zhī Dào Yì Jiā Hěn Hǎo De Fàn Guǎn.", "Bạn nói bạn ấy biết một quán ăn rất ngon."], [19.116, 22.696, "我们走进饭馆，服务员问好。", "Wǒ Men Zǒu Jìn Fàn Guǎn, Fú Wù Yuán Wèn Hǎo.", "Chúng tôi vào quán, nhân viên chào."], [22.696, 27.14, "服务员笑着说：“请坐，请看菜单。”", "Fú Wù Yuán Xiào Zhe Shuō: “Qǐng Zuò, Qǐng Kàn Cài Dān.”", "Nhân viên cười nói: \"Mời ngồi, mời xem thực đơn.\""], [27.149, 31.281, "菜单上的菜很多，我不知道选什么。", "Cài Dān Shàng De Cài Hěn Duō, Wǒ Bù Zhī Dào Xuǎn Shén Me.", "Thực đơn nhiều món, tôi không biết chọn gì."], [31.281, 35.245, "我看了很久，还是不知道吃什么好。", "Wǒ Kàn Le Hěn Jiǔ, Hái Shì Bù Zhī Dào Chī Shén Me Hǎo.", "Tôi xem rất lâu, vẫn không biết ăn gì thì ngon."], [35.245, 38.969, "我小声问朋友：“你能帮帮我吗？”", "Wǒ Xiǎo Shēng Wèn Péng Yǒu: “Nǐ Néng Bāng Bāng Wǒ Ma?”", "Tôi khẽ hỏi bạn: \"Cậu giúp tớ được không?\""], [38.982, 44.338, "朋友教我看菜单，我点了米饭、鱼和鸡蛋。", "Péng Yǒu Jiào Wǒ Kàn Cài Dān, Wǒ Diǎn Le Mǐ Fàn, Yú Hé Jī Dān.", "Bạn dạy tôi xem thực đơn, tôi gọi cơm, cá và trứng."], [44.338, 47.462, "他还点了青菜和一碗汤。", "Tā Hái Diǎn Le Qīng Cài Hé Yì Wǎn Tāng.", "Bạn còn gọi rau và một tô canh."], [47.462, 51.162, "朋友问我：“你还想吃一点儿什么？”", "Péng Yǒu Wèn Wǒ: “Nǐ Hái Xiǎng Chī Yì Diǎn Ér Shén Me?”", "Bạn hỏi tôi: \"Cậu còn muốn ăn thêm gì không?\""], [51.162, 54.718, "我说：“不用了，这些很好。”", "Wǒ Shuō: “Bú Yòng Le, Zhè Xiē Hěn Hǎo.”", "Tôi nói: \"Không cần nữa, mấy món này rất được rồi.\""], [54.718, 58.082, "我们等了一会儿，菜还没来。", "Wǒ Men Děng Le Yí Huì Er, Cài Hái Méi Lái.", "Chúng tôi đợi một lát, món vẫn chưa lên."], [58.082, 63.462, "我有点儿担心，朋友说：“别担心，慢慢等。”", "Wǒ Yǒu Diǎn Ér Dān Xīn, Péng Yǒu Shuō: “Bié Dān Xīn, Màn Màn Děng.”", "Tôi hơi lo, bạn nói: “Đừng lo, cứ từ từ đợi.”"], [63.462, 67.45, "朋友告诉服务员，我们的菜还没来。", "Péng Yǒu Gào Su Fú Wù Yuán, Wǒ Men De Cài Hái Méi Lái.", "Bạn nói với nhân viên là món của chúng tôi chưa lên."], [67.45, 71.362, "服务员说：“对不起，马上就来。”", "Fú Wù Yuán Shuō: “Duì Bu Qǐ, Mǎ Shàng Jiù Lái.”", "Nhân viên nói: \"Xin lỗi, món lên ngay đây.\""], [71.362, 74.774, "菜来了，我们一起慢慢吃。", "Cài Lái Le, Wǒ Men Yì Qǐ Màn Màn Chī.", "Món lên, chúng tôi ăn chậm."], [74.774, 79.458, "朋友先吃了一口鱼，笑着说很好吃。", "Péng Yǒu Xiān Chī Le Yì Kǒu Yú, Xiào Zhe Shuō Hěn Hǎo Chī.", "Bạn ăn một miếng cá trước, cười nói rất ngon."], [79.458, 82.962, "我也吃了一口，真的很好吃。", "Wǒ Yě Chī Le Yì Kǒu, Zhēn De Hěn Hǎo Chī.", "Tôi cũng ăn một miếng, thật sự rất ngon."], [82.962, 86.494, "我觉得味道很好，也不太贵。", "Wǒ Jué De Wèi Dào Hěn Hǎo, Yě Bú Tài Guì.", "Tôi thấy vị rất ngon, cũng không đắt."], [86.494, 89.69, "我们一边吃，一边说话。", "Wǒ Men Yì Biān Chī, Yì Biān Shuō Huà.", "Chúng tôi vừa ăn vừa trò chuyện."], [89.69, 93.726, "朋友告诉我，他常常来这家饭馆。", "Péng Yǒu Gào Su Wǒ, Tā Cháng Cháng Lái Zhè Jiā Fàn Guǎn.", "Bạn kể bạn ấy thường đến quán này."], [93.729, 97.309, "吃完后我们决定一起付钱。", "Chī Wán Hòu Wǒ Men Jué Dìng Yì Qǐ Fù Qián.", "Ăn xong chúng tôi cùng trả tiền."], [97.309, 100.481, "服务员说四十五块钱。", "Fú Wù Yuán Shuō Sì Shí Wǔ Kuài Qián.", "Nhân viên nói bốn mươi lăm tệ."], [100.496, 105.156, "我们一起付钱，一人一半，觉得这样很好。", "Wǒ Men Yì Qǐ Fù Qián, Yì Rén Yí Bàn, Jué De Zhè Yàng Hěn Hǎo.", "Chúng tôi cùng trả tiền, mỗi người một nửa, thấy vậy rất hay."], [105.156, 108.424, "朋友说我第一次点菜不错。", "Péng Yǒu Shuō Wǒ Dì Yī Cì Diǎn Cài Bù Cuò.", "Bạn nói lần đầu tôi gọi món khá tốt."], [108.429, 112.009, "我说谢谢，下次我来请客。", "Wǒ Shuō Xiè Xiè, Xià Cì Wǒ Lái Qǐng Kè.", "Tôi cảm ơn và nói lần sau tôi mời."], [112.009, 116.357, "走出饭馆，我问朋友下次去哪里吃。", "Zǒu Chū Fàn Guǎn, Wǒ Wèn Péng Yǒu Xià Cì Qù Nǎ Lǐ Chī.", "Ra khỏi quán, tôi hỏi bạn lần sau ăn ở đâu."], [116.357, 121.401, "朋友笑着说：“下次你来点，我等着吃。”", "Péng Yǒu Xiào Zhe Shuō: “Xià Cì Nǐ Lái Diǎn, Wǒ Děng Zhe Chī.”", "Bạn cười nói: \"Lần sau cậu gọi món, tớ chờ ăn.\""], [121.401, 126.997, "回家的路上，我想：下次我也能自己点菜了。", "Huí Jiā De Lù Shàng, Wǒ Xiǎng: Xià Cì Wǒ Yě Néng Zì Jǐ Diǎn Cài Le.", "Trên đường về nhà, tôi nghĩ: lần sau mình cũng có thể tự gọi món rồi."]]}, "hsk2-28": {"dur": 146.4, "cues": [[7.64, 11.868, "如果你在外面迷路了，你会怎么做？", "Rú Guǒ Nǐ Zài Wài Miàn Mí Lù Le, Nǐ Huì Zěn Me Zuò?", "Nếu bạn bị lạc ở ngoài, bạn sẽ làm thế nào?"], [11.868, 16.144, "昨天下午，妈妈让我去商店买东西。", "Zuó Tiān Xià Wǔ, Mā Ma Ràng Wǒ Qù Shāng Diàn Mǎi Dōng Xi.", "Chiều qua, mẹ nhờ tôi đi cửa hàng mua đồ."], [16.144, 21.45, "她告诉我，商店不远，走路十分钟就到。", "Tā Gào Su Wǒ, Shāng Diàn Bù Yuǎn, Zǒu Lù Shí Fēn Zhōng Jiù Dào.", "Mẹ bảo cửa hàng không xa, đi bộ mười phút là tới."], [21.45, 25.414, "我说：“好，我很快就回来。”", "Wǒ Shuō: “Hǎo, Wǒ Hěn Kuài Jiù Huí Lái.”", "Tôi nói: \"Vâng, con sẽ về nhanh thôi.\""], [25.414, 29.474, "昨天下午我去商店，走错了路。", "Zuó Tiān Xià Wǔ Wǒ Qù Shāng Diàn, Zǒu Cuò Le Lù.", "Chiều qua tôi đi cửa hàng và đi nhầm đường."], [29.474, 33.942, "我走着走着，看见的路都不认识。", "Wǒ Zǒu Zhe Zǒu Zhe, Kàn Jiàn De Lù Dōu Bú Rèn Shi.", "Đi mãi, những con đường tôi thấy đều không quen."], [33.95, 37.89, "走了一会儿，我发现自己迷路了。", "Zǒu Le Yí Huì Er, Wǒ Fā Xiàn Zì Jǐ Mí Lù Le.", "Đi một lát tôi thấy mình bị lạc."], [37.89, 41.758, "路上的人不多，我心里很紧张。", "Lù Shàng De Rén Bù Duō, Wǒ Xīn Lǐ Hěn Jǐn Zhāng.", "Trên đường không nhiều người, trong lòng tôi rất lo lắng."], [41.76, 45.436, "心里紧张，我给妈妈打电话。", "Xīn Lǐ Jǐn Zhāng, Wǒ Gěi Mā Ma Dǎ Diàn Huà.", "Hơi lo, tôi gọi điện cho mẹ."], [45.436, 50.192, "电话里，妈妈问我：“你现在在哪里？”", "Diàn Huà Lǐ, Mā Ma Wèn Wǒ: “Nǐ Xiàn Zài Zài Nǎ Lǐ?”", "Trong điện thoại, mẹ hỏi tôi: \"Con đang ở đâu?\""], [50.192, 54.2, "我看了看旁边，告诉她我不知道。", "Wǒ Kàn Le Kàn Páng Biān, Gào Su Tā Wǒ Bù Zhī Dào.", "Tôi nhìn quanh, bảo mẹ là tôi không biết."], [54.2, 58.572, "妈妈说：“别担心，慢慢找银行。”", "Mā Ma Shuō: “Bié Dān Xīn, Màn Màn Zhǎo Yín Háng.”", "Mẹ nói: \"Đừng lo, từ từ tìm ngân hàng.\""], [58.572, 64.96, "妈妈让我先向右走，再往前走，走到银行门口等她。", "Mā Ma Ràng Wǒ Xiān Xiàng Yòu Zǒu, Zài Wǎng Qián Zǒu, Zǒu Dào Yín Háng Mén Kǒu Děng Tā.", "Mẹ bảo tôi rẽ phải trước, rồi đi thẳng tiếp, đến cửa ngân hàng thì đợi mẹ."], [64.967, 68.739, "我向右走，又往前走了很久。", "Wǒ Xiàng Yòu Zǒu, Yòu Wǎng Qián Zǒu Le Hěn Jiǔ.", "Tôi rẽ phải, lại đi thẳng rất lâu."], [68.739, 72.199, "我还是没看见她说的银行。", "Wǒ Hái Shì Méi Kàn Jiàn Tā Shuō De Yín Háng.", "Tôi vẫn không thấy ngân hàng mẹ nói."], [72.199, 76.043, "我站在路边，不知道往哪里走。", "Wǒ Zhàn Zài Lù Biān, Bù Zhī Dào Wǎng Nǎ Lǐ Zǒu.", "Tôi đứng bên đường, không biết đi về đâu."], [76.067, 79.935, "这时候，一位奶奶慢慢走过来。", "Zhè Shí Hòu, Yí Wèi Nǎi Nai Màn Màn Zǒu Guò Lái.", "Lúc này, một bà cụ từ từ đi lại."], [79.935, 84.523, "我先不敢问，想了想，还是问了。", "Wǒ Xiān Bù Gǎn Wèn, Xiǎng Le Xiǎng, Hái Shì Wèn Le.", "Lúc đầu tôi không dám hỏi, nghĩ một lát, rồi vẫn hỏi."], [84.523, 87.667, "我问一位奶奶路怎么走。", "Wǒ Wèn Yí Wèi Nǎi Nai Lù Zěn Me Zǒu.", "Tôi hỏi một bà đường đi thế nào."], [87.667, 91.271, "奶奶笑着问我：“你要去哪里？”", "Nǎi Nai Xiào Zhe Wèn Wǒ: “Nǐ Yào Qù Nǎ Lǐ?”", "Bà cười hỏi tôi: \"Cháu muốn đi đâu?\""], [91.271, 96.459, "我告诉她我在等妈妈，还问银行在哪里。", "Wǒ Gào Su Tā Wǒ Zài Děng Mā Ma, Hái Wèn Yín Háng Zài Nǎ Lǐ.", "Tôi bảo bà là tôi đang đợi mẹ, và hỏi ngân hàng ở đâu."], [96.459, 99.919, "奶奶带我去前面的小路口。", "Nǎi Nai Dài Wǒ Qù Qián Miàn De Xiǎo Lù Kǒu.", "Bà dẫn tôi đến ngã nhỏ phía trước."], [99.933, 103.657, "到了路口，我就看见了银行。", "Dào Le Lù Kǒu, Wǒ Jiù Kàn Jiàn Le Yín Háng.", "Đến ngã đường, tôi liền thấy ngân hàng."], [103.657, 107.237, "银行门口，妈妈正在等我。", "Yín Háng Mén Kǒu, Mā Ma Zhèng Zài Děng Wǒ.", "Trước cửa ngân hàng, mẹ đang đợi tôi."], [107.237, 111.057, "我跑过去，高兴地叫：“妈妈！”", "Wǒ Pǎo Guò Qù, Gāo Xìng De Jiào: “Mā Ma!”", "Tôi chạy lại, vui mừng gọi: “Mẹ ơi!”"], [111.067, 114.959, "妈妈问我：“你是怎么找到这里的？”", "Mā Ma Wèn Wǒ: “Nǐ Shì Zěn Me Zhǎo Dào Zhè Lǐ De?”", "Mẹ hỏi tôi: \"Con tìm đến đây bằng cách nào?\""], [114.959, 118.299, "我把问路的事告诉了妈妈。", "Wǒ Bǎ Wèn Lù De Shì Gào Su Le Mā Ma.", "Tôi kể cho mẹ chuyện hỏi đường."], [118.299, 122.143, "见到妈妈，我说以后要问路。", "Jiàn Dào Mā Ma, Wǒ Shuō Yǐ Hòu Yào Wèn Lù.", "Gặp mẹ tôi nói sau này sẽ hỏi đường."], [122.167, 125.171, "妈妈笑着夸我做得对。", "Mā Ma Xiào Zhe Kuā Wǒ Zuò De Duì.", "Mẹ cười khen tôi làm đúng."], [125.171, 130.191, "回家的路上，我和妈妈一边走一边说话。", "Huí Jiā De Lù Shàng, Wǒ Hé Mā Ma Yì Biān Zǒu Yì Biān Shuō Huà.", "Trên đường về, tôi và mẹ vừa đi vừa trò chuyện."], [130.2, 136.2, "到家以后，妈妈给我一杯热水，我很快就不紧张了。", "Dào Jiā Yǐ Hòu, Mā Ma Gěi Wǒ Yì Bēi Rè Shuǐ, Wǒ Hěn Kuài Jiù Bù Jǐn Zhāng Le.", "Về đến nhà, mẹ đưa tôi một cốc nước nóng, tôi nhanh chóng hết lo lắng."]]}, "hsk2-29": {"dur": 144.89, "cues": [[7.657, 11.501, "考试前的一个月，你会怎么学习？", "Kǎo Shì Qián De Yí Gè Yuè, Nǐ Huì Zěn Me Xué Xí?", "Một tháng trước kỳ thi, bạn sẽ học như thế nào?"], [11.501, 16.233, "下月我们要考汉语，大家都有点儿忙。", "Xià Yuè Wǒ Men Yào Kǎo Hàn Yǔ, Dà Jiā Dōu Yǒu Diǎn Ér Máng.", "Tháng sau chúng tôi thi tiếng Trung, mọi người hơi bận."], [16.233, 20.19, "老师在课上告诉我们考试的时间。", "Lǎo Shī Zài Kè Shàng Gào Su Wǒ Men Kǎo Shì De Shí Jiān.", "Thầy thông báo trên lớp thời gian thi."], [20.19, 24.298, "老师让我们每天复习生词和课文。", "Lǎo Shī Ràng Wǒ Men Měi Tiān Fù Xí Shēng Cí Hé Kè Wén.", "Thầy bảo mỗi ngày ôn từ mới và bài khóa."], [24.298, 28.55, "我想好了，每天晚上复习一个小时。", "Wǒ Xiǎng Hǎo Le, Měi Tiān Wǎn Shàng Fù Xí Yí Gè Xiǎo Shí.", "Tôi đã định, mỗi tối ôn tập một tiếng."], [28.557, 33.073, "我把汉字写在本子上，多读几遍。", "Wǒ Bǎ Hàn Zì Xiě Zài Běn Zi Shàng, Duō Dú Jǐ Biàn.", "Tôi viết chữ Hán vào vở và đọc thêm vài lần."], [33.073, 37.733, "有的汉字我写了好几遍，还是写错。", "Yǒu De Hàn Zì Wǒ Xiě Le Hǎo Jǐ Biàn, Hái Shì Xiě Cuò.", "Có chữ Hán tôi viết mấy lần vẫn viết sai."], [37.733, 41.385, "我问妈妈：“这个字怎么写才对？”", "Wǒ Wèn Mā Ma: “Zhè Gè Zì Zěn Me Xiě Cái Duì?”", "Tôi hỏi mẹ: \"Chữ này viết thế nào mới đúng?\""], [41.39, 46.626, "妈妈笑着说：“没关系，一遍一遍慢慢写。”", "Mā Ma Xiào Zhe Shuō: “Méi Guān Xì, Yí Biàn Yí Biàn Màn Màn Xiě.”", "Mẹ cười nói: “Không sao, viết từ từ từng lần một.”"], [46.626, 49.798, "晚上妈妈陪着我做练习。", "Wǎn Shàng Mā Ma Péi Zhe Wǒ Zuò Liàn Xí.", "Tối mẹ ngồi bên làm bài luyện cùng tôi."], [49.798, 54.36, "妈妈读课文，我听，听完我再读。", "Mā Ma Dú Kè Wén, Wǒ Tīng, Tīng Wán Wǒ Zài Dú.", "Mẹ đọc bài khóa, tôi nghe, nghe xong tôi đọc lại."], [54.36, 58.228, "有一道题我不会做，想了很久。", "Yǒu Yí Dào Tí Wǒ Bú Huì Zuò, Xiǎng Le Hěn Jiǔ.", "Có một câu tôi không biết làm, nghĩ rất lâu."], [58.228, 61.376, "同学打电话问题怎么做。", "Tóng Xué Dǎ Diàn Huà Wèn Tí Zěn Me Zuò.", "Bạn gọi hỏi câu làm sao."], [61.376, 66.66, "我告诉同学，我也不会，明天一起问老师。", "Wǒ Gào Su Tóng Xué, Wǒ Yě Bú Huì, Míng Tiān Yì Qǐ Wèn Lǎo Shī.", "Tôi bảo bạn là tôi cũng không biết, mai cùng hỏi thầy."], [66.66, 69.784, "不会的第二天去问老师。", "Bú Huì De Dì Èr Tiān Qù Wèn Lǎo Shī.", "Chỗ không biết hôm sau đi hỏi thầy."], [69.784, 73.676, "老师听了，笑着给我们说了一遍。", "Lǎo Shī Tīng Le, Xiào Zhe Gěi Wǒ Men Shuō Le Yí Biàn.", "Thầy nghe xong, cười nói lại cho chúng tôi một lần."], [73.676, 77.424, "这次我听懂了，心里很高兴。", "Zhè Cì Wǒ Tīng Dǒng Le, Xīn Lǐ Hěn Gāo Xìng.", "Lần này tôi hiểu rồi, trong lòng rất vui."], [77.427, 81.511, "考试前一周，我每天都睡得很早。", "Kǎo Shì Qián Yì Zhōu, Wǒ Měi Tiān Dōu Shuì De Hěn Zǎo.", "Một tuần trước thi, ngày nào tôi cũng ngủ sớm."], [81.511, 85.26, "考试前我每天晚上少玩一会儿。", "Kǎo Shì Qián Wǒ Měi Tiān Wǎn Shàng Shǎo Wán Yí Huì Er.", "Trước kỳ thi mỗi tối tôi bớt chơi một lát."], [85.26, 89.103, "妈妈叫我不要担心，要有信心。", "Mā Ma Jiào Wǒ Bú Yào Dān Xīn, Yào Yǒu Xìn Xīn.", "Mẹ bảo đừng lo và phải tự tin."], [89.127, 93.763, "考试那天早上，我吃完早饭就去学校。", "Kǎo Shì Nà Tiān Zǎo Shàng, Wǒ Chī Wán Zǎo Fàn Jiù Qù Xué Xiào.", "Sáng ngày thi, ăn sáng xong tôi đến trường."], [93.763, 97.727, "走进教室，我心里有点儿紧张。", "Zǒu Jìn Jiào Shì, Wǒ Xīn Lǐ Yǒu Diǎn Ér Jǐn Zhāng.", "Bước vào lớp, trong lòng tôi hơi hồi hộp."], [97.727, 101.807, "老师说：“先看一遍题，慢慢来。”", "Lǎo Shī Shuō: “Xiān Kàn Yí Biàn Tí, Màn Màn Lái.”", "Thầy nói: “Xem đề một lượt trước, cứ từ từ.”"], [101.807, 105.795, "考场上我先写名字，再做题。", "Kǎo Chǎng Shàng Wǒ Xiān Xiě Míng Zi, Zài Zuò Tí.", "Trong phòng thi tôi viết tên trước rồi làm bài."], [105.795, 110.431, "有一道题我不会，我先做下面的题。", "Yǒu Yí Dào Tí Wǒ Bú Huì, Wǒ Xiān Zuò Xià Miàn De Tí.", "Có một câu tôi không biết, tôi làm các câu phía dưới trước."], [110.431, 114.371, "后来我又想了想，慢慢想出来了。", "Hòu Lái Wǒ Yòu Xiǎng Le Xiǎng, Màn Màn Xiǎng Chū Lái Le.", "Sau đó tôi nghĩ lại, từ từ cũng nghĩ ra."], [114.374, 117.93, "时间到了，我把题都做完了。", "Shí Jiān Dào Le, Wǒ Bǎ Tí Dōu Zuò Wán Le.", "Hết giờ, tôi đã làm xong hết các câu."], [117.93, 121.075, "考完我觉得自己努力了。", "Kǎo Wán Wǒ Jué De Zì Jǐ Nǔ Lì Le.", "Thi xong tôi thấy mình đã nỗ lực."], [121.075, 125.71, "回家的路上，我给妈妈打电话告诉她。", "Huí Jiā De Lù Shàng, Wǒ Gěi Mā Ma Dǎ Diàn Huà Gào Su Tā.", "Trên đường về, tôi gọi điện kể cho mẹ."], [125.71, 130.346, "回家我对妈妈说，我还想继续学。", "Huí Jiā Wǒ Duì Mā Ma Shuō, Wǒ Hái Xiǎng Jì Xù Xué.", "Về nhà tôi nói với mẹ vẫn muốn học tiếp."], [130.346, 134.695, "妈妈笑着说：“好，我们一起慢慢学。”", "Mā Ma Xiào Zhe Shuō: “Hǎo, Wǒ Men Yì Qǐ Màn Màn Xué.”", "Mẹ cười nói: \"Tốt, chúng ta cùng học từ từ nhé.\""]]}, "hsk2-30": {"dur": 145.58, "cues": [[8.089, 11.141, "你给好朋友写过信吗？", "Nǐ Gěi Hǎo Péng Yǒu Xiě Guò Xìn Ma?", "Bạn đã từng viết thư cho bạn thân chưa?"], [11.141, 15.729, "我的好朋友去美国了，我很想念他。", "Wǒ De Hǎo Péng Yǒu Qù Měi Guó Le, Wǒ Hěn Xiǎng Niàn Tā.", "Bạn thân tôi sang Mỹ, tôi rất nhớ anh ấy."], [15.729, 19.525, "他走的那天，我去机场送他。", "Tā Zǒu De Nà Tiān, Wǒ Qù Jī Chǎng Sòng Tā.", "Ngày bạn ấy đi, tôi ra sân bay tiễn bạn."], [19.529, 23.709, "他说：“到了美国，我给你打电话。”", "Tā Shuō: “Dào Le Měi Guó, Wǒ Gěi Nǐ Dǎ Diàn Huà.”", "Bạn ấy nói: \"Đến Mỹ, tớ sẽ gọi cho cậu.\""], [23.709, 27.457, "我们说好，每个月写一封信。", "Wǒ Men Shuō Hǎo, Měi Gè Yuè Xiě Yì Fēng Xìn.", "Chúng tôi hẹn nhau mỗi tháng viết một lá thư."], [27.457, 32.669, "回来以后，我常常想到我们一起玩儿的时候。", "Huí Lái Yǐ Hòu, Wǒ Cháng Cháng Xiǎng Dào Wǒ Men Yì Qǐ Wánr De Shí Hòu.", "Về rồi, tôi thường nhớ lúc chúng tôi chơi cùng nhau."], [32.669, 36.633, "今晚我坐在桌子前给他写信。", "Jīn Wǎn Wǒ Zuò Zài Zhuō Zi Qián Gěi Tā Xiě Xìn.", "Tối nay tôi ngồi bàn viết thư cho bạn."], [36.633, 40.261, "写什么好呢，我想了好一会儿。", "Xiě Shén Me Hǎo Ne, Wǒ Xiǎng Le Hǎo Yí Huì Er.", "Viết gì đây, tôi nghĩ một lúc lâu."], [40.261, 44.945, "我先问他身体好吗，工作忙不忙。", "Wǒ Xiān Wèn Tā Shēn Tǐ Hǎo Ma, Gōng Zuò Máng Bù Máng.", "Tôi hỏi trước sức khỏe và việc có bận không."], [44.969, 49.221, "我先写下这里的天气和我的学习。", "Wǒ Xiān Xiě Xià Zhè Lǐ De Tiān Qì Hé Wǒ De Xué Xí.", "Tôi viết trước về thời tiết ở đây và việc học của tôi."], [49.221, 54.069, "他在美国工作，我很想知道他累不累。", "Tā Zài Měi Guó Gōng Zuò, Wǒ Hěn Xiǎng Zhī Dào Tā Lèi Bú Lèi.", "Bạn ấy làm việc ở Mỹ, tôi rất muốn biết bạn có mệt không."], [54.069, 57.745, "告诉他我在北京学习汉语。", "Gào Su Tā Wǒ Zài Běi Jīng Xué Xí Hàn Yǔ.", "Kể tôi đang học tiếng Trung ở Bắc Kinh."], [57.745, 61.037, "我的汉语比以前好了一点儿。", "Wǒ De Hàn Yǔ Bǐ Yǐ Qián Hǎo Le Yì Diǎn Ér.", "Tiếng Trung của tôi khá hơn trước một chút."], [61.037, 64.879, "信里我说这里的秋天很漂亮。", "Xìn Lǐ Wǒ Shuō Zhè Lǐ De Qiū Tiān Hěn Piào Liang.", "Trong thư tôi nói mùa thu ở đây rất đẹp."], [64.879, 68.507, "秋天到了，天气慢慢冷了。", "Qiū Tiān Dào Le, Tiān Qì Màn Màn Lěng Le.", "Mùa thu đến rồi, thời tiết từ từ lạnh đi."], [68.507, 73.142, "我一边写，一边想他读信的时候。", "Wǒ Yì Biān Xiě, Yì Biān Xiǎng Tā Dú Xìn De Shí Hòu.", "Tôi vừa viết vừa nghĩ đến lúc bạn ấy đọc thư."], [73.142, 76.77, "写着写着，我写错了一个字。", "Xiě Zhe Xiě Zhe, Wǒ Xiě Cuò Le Yí Gè Zì.", "Viết mãi, tôi viết sai một chữ."], [76.779, 80.502, "我又读了一遍，改了两个错字。", "Wǒ Yòu Dú Le Yí Biàn, Gǎi Le Liǎng Gè Cuò Zì.", "tôi đọc lại và sửa hai chữ sai."], [80.502, 85.139, "读第二遍的时候，我又多写了几个字。", "Dú Dì Èr Biàn De Shí Hòu, Wǒ Yòu Duō Xiě Le Jǐ Gè Zì.", "Đọc lần hai, tôi viết thêm vài chữ nữa."], [85.139, 89.319, "我写：“下次回来，我们一起去玩儿。”", "Wǒ Xiě: “Xià Cì Huí Lái, Wǒ Men Yì Qǐ Qù Wánr.”", "Tôi viết: \"Lần sau về, chúng ta cùng đi chơi nhé.\""], [89.319, 93.331, "我看了看时间，邮局还没关门。", "Wǒ Kàn Le Kàn Shí Jiān, Yóu Jú Hái Méi Guān Mén.", "Tôi xem giờ, bưu điện vẫn chưa đóng cửa."], [93.331, 97.367, "写完后我去邮局买邮票寄出去。", "Xiě Wán Hòu Wǒ Qù Yóu Jú Mǎi Yóu Piào Jì Chū Qu.", "Viết xong tôi ra bưu điện mua tem gửi đi."], [97.367, 100.995, "路上有点儿冷，我走得很快。", "Lù Shàng Yǒu Diǎn Ér Lěng, Wǒ Zǒu De Hěn Kuài.", "Trên đường hơi lạnh, tôi đi rất nhanh."], [101.019, 105.27, "到了邮局，工作人员问我寄到哪里。", "Dào Le Yóu Jú, Gōng Zuò Rén Yuán Wèn Wǒ Jì Dào Nǎ Lǐ.", "Đến bưu điện, nhân viên hỏi tôi gửi đi đâu."], [105.27, 109.115, "我说：“寄到美国，谢谢您。”", "Wǒ Shuō: “Jì Dào Měi Guó, Xiè Xiè Nín.”", "Tôi nói: \"Gửi đi Mỹ ạ, cảm ơn cô.\""], [109.115, 113.099, "工作人员说我这封信六天能到。", "Gōng Zuò Rén Yuán Shuō Wǒ Zhè Fēng Xìn Liù Tiān Néng Dào.", "Nhân viên nói bức thư này sáu ngày tới."], [113.099, 117.735, "我问：“六天以后，他就能收到了吗？”", "Wǒ Wèn: “Liù Tiān Yǐ Hòu, Tā Jiù Néng Shōu Dào Le Ma?”", "Tôi hỏi: \"Sáu ngày nữa là bạn ấy nhận được phải không?\""], [117.735, 124.651, "工作人员笑着点点头，说：“对，六天就到，别担心。”", "Gōng Zuò Rén Yuán Xiào Zhe Diǎn Diǎn Tóu, Shuō: “Duì, Liù Tiān Jiù Dào, Bié Dān Xīn.”", "Nhân viên cười gật đầu, nói: “Đúng vậy, sáu ngày là tới, đừng lo.”"], [124.666, 128.145, "我想朋友收到一定很高兴。", "Wǒ Xiǎng Péng Yǒu Shōu Dào Yí Dìng Hěn Gāo Xìng.", "Tôi nghĩ bạn nhận được chắc sẽ rất vui."], [128.145, 131.822, "写信比打电话更有意思。", "Xiě Xìn Bǐ Dǎ Diàn Huà Gèng Yǒu Yì Si.", "Viết thư thú vị hơn gọi điện."], [131.822, 135.377, "我觉得写信让我们更近一点。", "Wǒ Jué De Xiě Xìn Ràng Wǒ Men Gèng Jìn Yì Diǎn.", "Tôi thấy viết thư giúp chúng tôi gần nhau hơn."]]}};
